INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4939b38c-9ec7-4ca8-a3c1-8940a2549946', '21feff02-016d-46e2-bb9d-c27495133b1b', '25. óra: Tesztfeladatok megoldása', 'Feladatmegoldási gyakorlat önállóan az oszthatósági téma lezárása előtt.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "31bf7d86-9d71-4f57-9706-a99212ace97f", "text": "Hány osztója van a 10-nek? (1, 2, 5, 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "1ff1078b-2e21-40c0-ba4c-36d00f3f53d7", "text": "Osztható-e a 432 6-tal?", "type": "true-false", "options": [{"id": "8f9673a4-e434-4b5b-b721-7bdba7a06cd3", "text": "Igaz (páros és 4+3+2=9)", "isCorrect": true}, {"id": "f823bd8c-b749-4bca-a1b7-468f132ecba0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0b5893dd-cd46-4f61-8f59-3ce32ee13acd", "text": "Mennyi (-7) * (+6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-42"}, {"id": "e5593ecf-f07e-4941-913b-565ed6ee6119", "text": "Melyik szorzat eredménye pozitív?", "type": "multiple-choice", "options": [{"id": "325f14b3-c1af-412b-be29-2c27053aed48", "text": "(-4) * (-5)", "isCorrect": true}, {"id": "fc42804c-f0d6-45c0-b8f6-3749eba90608", "text": "(-4) * (+5)", "isCorrect": false}, {"id": "e85dcaef-fc3f-474e-9e66-1cf1a23a5e3d", "text": "(+4) * (-5)", "isCorrect": false}, {"id": "85b01a89-a76d-4153-a769-68a28517e609", "text": "(-4) * 0", "isCorrect": false}], "timeLimit": 15}, {"id": "4b4bac90-abdd-4fcb-bf66-b6b12534a214", "text": "Mennyi a maradék, ha 47-et 5-tel osztunk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "1ec3b8a7-fece-46da-a80e-99db792a6111", "text": "A 17 prímszám.", "type": "true-false", "options": [{"id": "27b05368-923e-42ed-bee1-19baa71c6288", "text": "Igaz", "isCorrect": true}, {"id": "f584c24b-c3a4-4f64-9769-bc92b87d20a0", "text": "Hamis", "isCorrect": false}