INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ff68e7e0-fb77-41c9-9a53-4a986c37980f', '21feff02-016d-46e2-bb9d-c27495133b1b', '26. óra: Témazáró dolgozat', 'Témazáró számonkérés az Egész számok és oszthatóság témakörből (10 kérdés).', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "e58439cd-7663-4093-b347-3e6bbffad867", "text": "1. Mennyi (-18) + (+30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "1fff693a-fce1-4498-9619-131c3c698fd6", "text": "2. Mennyi (-7) * (-9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "63"}, {"id": "5a58216b-dbfd-4696-93e6-db7cdc595971", "text": "3. Mennyi (-72) : (+8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-9"}, {"id": "e34c709a-64be-4035-ae83-f767979d3b98", "text": "4. Osztható-e a 534 3-mal?", "type": "true-false", "options": [{"id": "fe8639cd-6a63-4639-aa84-240407abcae3", "text": "Igaz (5+3+4=12)", "isCorrect": true}, {"id": "9d64676b-66c0-4ca9-84a0-5889d9403114", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ed3dfeea-6d18-4308-a8a3-e501388e7f13", "text": "5. Osztható-e a 620 4-gyel?", "type": "true-false", "options": [{"id": "4a0f9ae0-69f4-4879-9a9c-d808ca22819f", "text": "Igaz (20 osztható 4-gyel)", "isCorrect": true}, {"id": "7290d610-0c36-46ea-b105-24e85314db4e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c4fc1fd9-5bef-470e-9f08-307d1d8ef35c", "text": "6. Mennyi lkkt(6, 10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "6626d77a-e74d-48d7-a642-2bfa03c71f6f", "text": "7. Mennyi lnko(18, 24)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "1d783878-b10f-436e-8666-938836a11c0c", "text": "8. Hány prímszám van 1 és 10 között? (2, 3, 5, 7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "2ac6a451-3eb5-43a4-841f-02eb1a2f010e", "text": "9. Hányféleképpen ülhet le 3 gyermek 3 székre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "c8c621c9-049f-4839-b4e6-b03046da8f98", "text": "10. Két negatív szám szorzata mindig pozitív.", "type": "true-false", "options": [{"id": "b2bc06c1-46ef-44b4-8cab-f003ddcbe1d9", "text": "Igaz", "isCorrect": true}, {"id": "e653ae71-d8f8-4da0-987b-534caf9acb47", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ec919c27-64a0-444e-a82b-9143d51060fa', '21feff02-016d-46e2-bb9d-c27495133b1b', '27. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat megbeszélése, hibák elemzése, tapasztalatok összegzése.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "86b5660c-30d7-41d1-abd0-777e1e0e20ed", "text": "Mi volt a leggyakoribb hiba az előjelszabályok alkalmazásakor?", "type": "multiple-choice", "options": [{"id": "311391fc-4f47-4bee-8ad2-2f64b7830955", "text": "A szorzás/osztás és összeadás előjelszabályainak összetévesztése", "isCorrect": true}, {"id": "013bcf4d-e6d9-44ae-b91c-8c90b14a8b65", "text": "A számok leírása", "isCorrect": false}, {"id": "5c9b5548-3ac1-4754-831d-70faab4f4f83", "text": "A vonalzó használata", "isCorrect": false}, {"id": "8a12f527-d3ec-4243-95bc-c5a329233e07", "text": "A válasz elhagyása", "isCorrect": false}], "timeLimit": 15}, {"id": "2b70ed63-8155-44d9-8452-899d4eebbbc8", "text": "Az osztási szabályok (pl. 3-mal, 9-cel) esetén a számjegyek összege a döntő.", "type": "true-false", "options": [{"id": "21c150ab-9c7f-4349-b25e-4d8334222a10", "text": "Igaz", "isCorrect": true}, {"id": "9586546c-dc21-46e7-81f4-3d9b6a3e9a0e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6777e30c-3de1-4679-9b1f-940144a71776", "text": "Mennyi (-5) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "fb00a235-f1c7-4a75-976b-a6171b50686c", "text": "A lkkt meghatározásánál a többszörösök közül a legkisebbet választjuk.", "type": "true-false", "options": [{"id": "d5cabd9c-47cc-49b2-a28e-e60b34174369", "text": "Igaz", "isCorrect": true}, {"id": "37938855-f196-441f-93b5-6c4846dda6d8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2127ba0d-5947-4a68-a527-df6f6ea74515", "text": "Mennyi (-30) : (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "c16b5d97-0391-4007-a5b5-f4a00bc00dda", "text": "A dolgozatok áttekintése segít a hiányosságok pótlásában.", "type": "true-false", "options": [{"id": "d66beaf7-1121-43ef-a259-a922e64e4994", "text": "Igaz", "isCorrect": true}, {"id": "7a8e8a2c-ec1d-4f39-829e-d5aaeb9b2122", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e7040702-55a4-4626-bdf7-c7bcd82a4af2", "text": "Mennyi lnko(10, 15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('69996473-6474-4890-a26c-e7cae3f62784', '21feff02-016d-46e2-bb9d-c27495133b1b', '30. óra: Szorzás törttel, a reciprok', 'Tört szorzása törttel, reciprok fogalma.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "cc0c1fa5-be10-48cb-87ff-84672bcdd0f6", "text": "Hogyan szorzunk törttel törtet?", "type": "multiple-choice", "options": [{"id": "13c20b56-eba8-4a9c-b412-b7493f3b8366", "text": "A számlálót a számlálóval, a nevezőt a nevezővel szorozzuk", "isCorrect": true}, {"id": "e50e5975-001d-4001-9b87-296ecd858273", "text": "Közös nevezőre hozzuk őket", "isCorrect": false}, {"id": "cc02fda8-14e5-49ee-b007-d3f2d7063712", "text": "A számlálót a nevezővel szorozzuk", "isCorrect": false}, {"id": "75fd31a2-968b-46e7-b97a-ce03272c3604", "text": "Keresztbe szorzunk", "isCorrect": false}], "timeLimit": 15}, {"id": "fd62e583-cb01-4cd8-9d37-a0ed11cccd13", "text": "Mennyi 2/3 * 3/5?", "type": "multiple-choice", "options": [{"id": "859d5c09-62b9-4f7f-ab07-29121be01f25", "text": "6/15 (azaz 2/5)", "isCorrect": true}, {"id": "b5c70bbe-a1bd-4ccf-9bc3-581b8cdf3a29", "text": "5/8", "isCorrect": false}, {"id": "81220785-2e8b-4947-b792-76d422d45334", "text": "6/8", "isCorrect": false}, {"id": "3e7687ad-adb7-44ca-828f-4bb00a2d3a41", "text": "2/15", "isCorrect": false}], "timeLimit": 15}, {"id": "62e7fa2a-1ffa-4d13-836b-7a3f2a740f77", "text": "Mi a 3/4 reciproka?", "type": "multiple-choice", "options": [{"id": "3f7fff84-d71e-4fd8-a9eb-6bb40e124ec7", "text": "4/3", "isCorrect": true}, {"id": "2a598af6-9d6a-4ca2-951e-abc1f2e7cd9f", "text": "-3/4", "isCorrect": false}, {"id": "1384e5f6-03de-43e6-af7a-feac01eada28", "text": "1/4", "isCorrect": false}, {"id": "fd638889-152b-42e7-968c-5e3c53c9df6c", "text": "3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "fe1b1062-7af6-4e4b-8d73-e8abc15a6780", "text": "Egy szám és a reciproka szorzata mindig 1.", "type": "true-false", "options": [{"id": "c8300eba-c14f-427f-8457-3c0c2473d7d5", "text": "Igaz", "isCorrect": true}, {"id": "3d934967-25b8-4527-b1a6-6d3f1d4d5738", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "df9b3c03-022f-4895-b567-9e9eb36bc781", "text": "Mi a 5 egész reciproka?", "type": "multiple-choice", "options": [{"id": "ebd3331d-2f15-4dc5-971e-67e6608583a1", "text": "1/5", "isCorrect": true}, {"id": "a1731f50-abc7-4345-a67d-95ba2ed0e557", "text": "-5", "isCorrect": false}, {"id": "c2c05764-6778-4717-916c-7ba182df06a1", "text": "5/1", "isCorrect": false}, {"id": "3711afbe-4f45-4f0b-a0bb-7c15d9e6fd5c", "text": "0", "isCorrect": false}], "timeLimit": 15}, {"id": "35c823f8-04cf-442d-b4e1-5c073cf38168", "text": "A 0-nak nincs reciproka.", "type": "true-false", "options": [{"id": "aa1634bf-e254-4dbb-90b2-aa4beede12ee", "text": "Igaz", "isCorrect": true}, {"id": "8d18a5f6-0481-4a15-ae05-c9f49c534e24", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5bf3aa3b-ba59-4042-85a9-5e0d6f6c5f30", "text": "Mennyi 1/2 * 1/3?", "type": "multiple-choice", "options": [{"id": "94beac25-1dc0-441a-b9e7-fb07693bf28f", "text": "1/6", "isCorrect": true}, {"id": "ed681fbd-c9ab-46f3-a726-cd0269882fe4", "text": "2/5", "isCorrect": false}, {"id": "8f625a52-85ca-4a6e-8eeb-6274bf9d6248", "text": "1/5", "isCorrect": false}, {"id": "e62b99a2-1a58-4ee1-a9c9-b78c7a4c6986", "text": "2/6", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e446f30b-172b-449c-9aa1-1ee4560c9558', '21feff02-016d-46e2-bb9d-c27495133b1b', '31. óra: A törtek szorzását alkalmazó feladatok megoldása', 'Törtrész kiszámítása és szöveges feladatok megoldása szorzással.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "613f2c3a-dd81-4b9c-b641-f5e0974db8f8", "text": "Mennyi 60-nak a 3/4 része? (60 * 3/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "e5e34e45-19df-42a8-accb-cc8f825ff5c9", "text": "Mennyi 100-nak az 1/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "bb3af801-8b8a-4a4d-a159-bd7dca2e2c99", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szeletet ettek meg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "4d9eba3e-e974-4cc4-9492-e08a92942206", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szelet maradt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "a0c09205-f094-4707-bb77-1d7464f01712", "text": "Egy szám törtrészének kiszámításához a számot megszorozzuk a törttel.", "type": "true-false", "options": [{"id": "45e995fb-56a6-44ef-acfe-94901a432c14", "text": "Igaz", "isCorrect": true}, {"id": "d87d02e8-7714-4a53-8947-c0c9d14e5ab1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "996e2bdf-4a11-41fa-b353-3e6c076df399", "text": "Mennyi 50-nek a 2/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "4cf3d259-129b-4cc1-9482-6737eb0b46f6", "text": "Mennyi 1/2 óra percekben? (60 * 1/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a99e6786-8cb6-4344-8ae4-41c5f817f548', '21feff02-016d-46e2-bb9d-c27495133b1b', '32. óra: Osztás törttel', 'Törttel való osztás szabálya: szorzás a reciprokával.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "871b1f3c-1fe3-47c9-8bce-f1a24c2813d7", "text": "Hogyan osztunk törttel?", "type": "multiple-choice", "options": [{"id": "472d415e-e6bd-4f8a-9d5b-8c76517dfd9c", "text": "Az osztandót megszorozzuk az osztó reciprokával", "isCorrect": true}, {"id": "ebd09001-955b-4ab2-9944-5eaea6c7c385", "text": "Az osztandót elosztjuk a nevezővel", "isCorrect": false}, {"id": "59887ed7-90bb-4fce-94fd-f9cabb1fbe36", "text": "Mindig 1-et kapunk", "isCorrect": false}, {"id": "f5f00447-30c2-4c58-bcdf-844aa8bb8b0f", "text": "A számlálókat elosztjuk egymással", "isCorrect": false}], "timeLimit": 15}, {"id": "a86bfefb-2e39-4058-9662-027ff25dc321", "text": "Mennyi 2/3 : 4/5? (2/3 * 5/4)", "type": "multiple-choice", "options": [{"id": "5ed463a4-ff1b-4c35-b27d-6b32b9262f03", "text": "10/12 (azaz 5/6)", "isCorrect": true}, {"id": "29b05d79-baa5-48e9-9954-aba9c021dd3f", "text": "8/15", "isCorrect": false}, {"id": "5b17cd89-45d4-4b6a-b0c6-14633cfdddf5", "text": "6/8", "isCorrect": false}, {"id": "600cc0c5-3242-4f84-a791-f3e1b160f369", "text": "15/8", "isCorrect": false}], "timeLimit": 15}, {"id": "5d262335-cbeb-4095-88d9-759d39b2051b", "text": "Mennyi 1/2 : 1/2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "26ce8c06-1ab2-444c-a715-cd8a0a753440", "text": "Ha egy számot 1/2-del osztunk, az eredmény megegyezik a szám 2-vel való szorzatával.", "type": "true-false", "options": [{"id": "eb4c53c5-2a6b-43af-aad0-3a45ac462b20", "text": "Igaz ( : 1/2 = * 2)", "isCorrect": true}, {"id": "23f6d9b7-a561-4b18-bca2-8224e6e68800", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dd215f39-0599-4e36-9296-32ff83f70cd4", "text": "Mennyi 6 : 1/3? (6 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "d9d60cbd-5eb6-4a47-9f10-4d5ebbd98c98", "text": "Törttel való osztáskor az osztandó nem változik, csak az osztót fordítjuk meg.", "type": "true-false", "options": [{"id": "7a7b25bf-b5c4-43d5-b07a-16c0d34dabf9", "text": "Igaz", "isCorrect": true}, {"id": "ddcc65e4-328f-425a-8b54-a8b5fb4e1dc9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b97de811-f09a-4d1b-b2e8-7e29d838afcd", "text": "Mennyi 3/4 : 3/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('02986052-2926-40d2-ac07-0971566f4e60', '21feff02-016d-46e2-bb9d-c27495133b1b', '33. óra: Hétköznapi problémák megoldása törtek osztásának felhasználásával', 'Szöveges feladatok mérésekkel, átdarabolásokkal, törtek osztásával.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "0886c330-f51f-4031-9b99-332178a0ead5", "text": "Hány 1/4 literes pohár tölthető meg 3 liter almaléből? (3 : 1/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "fc807549-efe8-4834-9ce4-446c296a7613", "text": "Hány 1/2 kg-os csomag képezhető 5 kg cukorból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "0e17a318-8df9-41ad-99bf-0a39b6cd7fc1", "text": "Egy 6 méteres szalagból 3/4 méteres darabokat vágunk. Hány darabot kapunk? (6 : 3/4 = 6 * 4/3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "5168580d-d365-43af-95d4-7f820f269bf7", "text": "Törtek osztásakor az eredmény lehet nagyobb az eredeti osztandónál, ha az osztó 1-nél kisebb tört.", "type": "true-false", "options": [{"id": "5ebdd7aa-e931-4354-a38a-b40ef95af462", "text": "Igaz", "isCorrect": true}, {"id": "7998b754-ca53-4bf0-82a2-efd97682222e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "07fccf8a-0096-42cc-b7b9-f13265df961d", "text": "Hány 1/5 méteres darab vágható ki 2 méter anyagból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "5c68c345-419b-423a-869f-0ffdf969a625", "text": "A szöveges feladatoknál az adatok lejegyzése és a mértékegységek egyeztetése elengedhetetlen.", "type": "true-false", "options": [{"id": "10ee890c-87fa-4434-9f06-50834a4940b5", "text": "Igaz", "isCorrect": true}, {"id": "379b92cd-775f-45b1-9843-299908bba53a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8075fded-04e9-4ae5-bbff-7057313d50ea", "text": "Mennyi 4 : 2/3? (4 * 3/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('552a3d87-acf8-4d1c-a756-ef1697800e65', '21feff02-016d-46e2-bb9d-c27495133b1b', '34. óra: Gyakorlóóra', 'A törtek szorzásának és osztásának rögzítése, feladatok gyakorlása.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "8f4919ac-d359-4c19-aef7-e121decc6377", "text": "Mennyi 3/5 * 5/3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "d54a93af-ce49-4824-bd6c-a3ca17340c7c", "text": "Mennyi 4/7 : 2/7? (4/7 * 7/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "4f7b5ad3-279c-45ca-8731-05fdf74cc02b", "text": "Melyik állítás igaz?", "type": "multiple-choice", "options": [{"id": "2346eada-d46c-49b3-a916-6215ed9c9143", "text": "Két 1-nél kisebb pozitív tört szorzata kisebb mindkét tényezőnél", "isCorrect": true}, {"id": "539e5f77-2a87-45d5-bc2f-019a281abe39", "text": "A szorzat mindig nagyobb a tényezőknél", "isCorrect": false}, {"id": "90dbb2bd-6a7c-4d29-83a2-cd97b25facfc", "text": "Az osztás mindig kisebb számot ad", "isCorrect": false}, {"id": "6be32f16-f7c5-4039-9e5d-5aaf44c782c0", "text": "Nincs reciproka a 4/5-nek", "isCorrect": false}], "timeLimit": 15}, {"id": "e4da4423-b441-48c1-90c7-1a0322f1143f", "text": "Mennyi 5/6 * 12? (5 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "25712e5d-5377-4b10-8980-2d67d33be673", "text": "A 2/3 osztva 1/3-dal 2-t ad.", "type": "true-false", "options": [{"id": "1a799eef-2287-47d1-98d5-9a02df378dc1", "text": "Igaz", "isCorrect": true}, {"id": "8620ed37-f572-43db-8e47-505bb834b520", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "157f751e-8c28-493d-b12d-32524d0c3ec9", "text": "Mennyi 3/8 : 3/8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "abfeb1e1-404a-4be4-8a67-e8eb89c9fd2d", "text": "Mennyi 1/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "6b02bd48-d4ae-436a-b10f-2e9c463f7855", "text": "1/5", "isCorrect": true}, {"id": "991d3947-3917-4a94-949f-097193448240", "text": "4/20", "isCorrect": false}, {"id": "12118afd-e32a-4542-a5b6-b58a0e4e7e35", "text": "1/20", "isCorrect": false}, {"id": "64cd5150-1543-422c-b973-4394aeabe7ba", "text": "4/9", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7ad6c97a-c5d0-4b9f-b34e-cdd1839a6279', '21feff02-016d-46e2-bb9d-c27495133b1b', '35. óra: Számonkérés', 'Számonkérés a közönséges törtek műveleteiből (10 kérdés).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "5a2f4638-2516-426e-9729-df5cf803d622", "text": "1. Mennyi 2/5 + 1/5?", "type": "multiple-choice", "options": [{"id": "6948dee9-dfba-49a7-9c09-ec688f50008d", "text": "3/5", "isCorrect": true}, {"id": "8b00fec7-45bb-4eab-b094-c9a3bf4df6dd", "text": "3/10", "isCorrect": false}, {"id": "7dcaa067-a586-4f0b-8e45-bb1e02a1413a", "text": "2/10", "isCorrect": false}, {"id": "608f9e2d-38b1-4de7-a155-72589f6ac8e4", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "4e6bdb91-42b8-4880-a27a-3e6fa2ce18c6", "text": "2. Mennyi 3/4 - 1/2? (3/4 - 2/4)", "type": "multiple-choice", "options": [{"id": "3e834ec3-b4ec-49b2-bb77-2d8b047a704e", "text": "1/4", "isCorrect": true}, {"id": "0257be15-9721-438a-a5ab-2c4aa8aa1716", "text": "2/2", "isCorrect": false}, {"id": "b1e4ae1b-363a-4458-91d3-332e9332daeb", "text": "1/2", "isCorrect": false}, {"id": "c98c34f0-021c-492f-a46a-275cc9d847fb", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "3b49290a-a455-4328-90bd-0a84752200db", "text": "3. Mennyi 2/3 * 3/4?", "type": "multiple-choice", "options": [{"id": "2e8894b2-3386-4302-be86-2f7045b2ad8e", "text": "6/12 (azaz 1/2)", "isCorrect": true}, {"id": "123ad4f2-6b29-4151-b3ad-8cea63b5041c", "text": "5/7", "isCorrect": false}, {"id": "67147c3c-985a-4aa7-ba32-01d4d7537bdf", "text": "6/7", "isCorrect": false}, {"id": "b95cb933-b178-4d45-946c-e55efd1e28a7", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "eb7156bf-01fb-4a2b-9227-a03e25413027", "text": "4. Mennyi 1/2 : 1/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "6a46a98a-5a6c-411c-ba93-83bf078be1c3", "text": "5. Mi a 7/8 reciproka?", "type": "multiple-choice", "options": [{"id": "22bd4113-ee3d-4dd2-a42c-298c01361332", "text": "8/7", "isCorrect": true}, {"id": "4624a66a-014f-4a4e-81e9-f98e6771225f", "text": "-7/8", "isCorrect": false}, {"id": "446ecbcb-6f18-4df6-a39e-d18d6b30932b", "text": "1/7", "isCorrect": false}, {"id": "cf2b0d53-1777-45c4-b6cf-3d15945b5bcd", "text": "7/8", "isCorrect": false}], "timeLimit": 15}, {"id": "7eadda4f-dfd5-420e-9874-22aa87c173b7", "text": "6. Mennyi 40-nek a 3/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "b4e3eee8-1562-43e6-8d30-742349bfd9f8", "text": "7. Egy szám és reciproka szorzata 1.", "type": "true-false", "options": [{"id": "44fda263-f6a9-4f7d-afc3-55cb637deefc", "text": "Igaz", "isCorrect": true}, {"id": "ff3911f3-0b99-4cd0-b19a-6e1280031478", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cddfefe7-d888-4d34-9fa0-d4fd1cac5ade", "text": "8. Mennyi 5 : 1/2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "d4a22fac-7d65-4432-b080-96bb80bdc1c7", "text": "9. A törtek szorzásakor a számlálót a számlálóval, a nevezőt a nevezővel szorozzuk.", "type": "true-false", "options": [{"id": "2bf216f8-e146-4343-9986-7b19b19eaedf", "text": "Igaz", "isCorrect": true}, {"id": "9949f175-ac2d-4899-af80-bf2234710d01", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1b53aaa6-2e69-436d-980e-3494ca14aff2", "text": "10. Hány negyedből áll 3 egész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f2961343-267f-4be8-bff5-46e3209fece9', '21feff02-016d-46e2-bb9d-c27495133b1b', '36. óra: Matematikai játékok', 'Matematikai társasjátékok, stratégiák törtekkel, csoport- és páros munka.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "4c96db93-3c06-49b0-b175-477af85e9b82", "text": "Melyik állítás igaz a matematikai társasjátékokról?", "type": "multiple-choice", "options": [{"id": "3fd2335e-8261-4e16-b298-ad4f3e9c5559", "text": "Fejlesztik a számolási gyorsaságot és a logikai stratégiát", "isCorrect": true}, {"id": "ce2db145-e675-428a-a9a7-a600c00c1164", "text": "Nincs közük a matematikához", "isCorrect": false}, {"id": "7cf2742c-e170-47e7-ab76-007d6a70fddb", "text": "Kizárólag szerencse kell hozzájuk", "isCorrect": false}, {"id": "f28ddb22-3728-4fb0-9742-a5ff22178dd3", "text": "Tiltható az együttműködés", "isCorrect": false}], "timeLimit": 15}, {"id": "5fd210d0-6ef3-4b44-bd40-00972615f379", "text": "A tört domino játékban az egyenlő értékű törteket illesztjük össze.", "type": "true-false", "options": [{"id": "f103c802-173d-42d9-8476-ea2832d54581", "text": "Igaz", "isCorrect": true}, {"id": "6df1e808-3be8-4a16-9ceb-c0fe8b4ddb36", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5c752538-2345-4a29-bcac-0b89b18e37be", "text": "Melyik tört felel meg a 0,5 tizedes törtnek?", "type": "multiple-choice", "options": [{"id": "69cd66df-bd2e-46fb-ad91-0d6c8175a360", "text": "1/2", "isCorrect": true}, {"id": "ab2cf384-498d-4b5c-b2b3-b88e003b5b62", "text": "1/5", "isCorrect": false}, {"id": "1b42a804-3dc8-4b59-8c88-ab0152cdf1f6", "text": "2/5", "isCorrect": false}, {"id": "ca85d5ae-0a6c-4037-8607-75351be99c91", "text": "5/2", "isCorrect": false}], "timeLimit": 15}, {"id": "49e4100b-26f8-4cf4-9cae-3ef4a4d43c05", "text": "Melyik tört felel meg a 0,25-nek?", "type": "multiple-choice", "options": [{"id": "c3b6cc52-1489-4bb6-ad06-c305fd9a0c44", "text": "1/4", "isCorrect": true}, {"id": "6e3fc535-0f8d-4241-8ddb-2445f6f0a1b3", "text": "1/2", "isCorrect": false}, {"id": "d92ffddc-bf00-41d0-b02d-e366906fbebc", "text": "2/5", "isCorrect": false}, {"id": "142bc2b7-1e91-475a-a485-75e369a84674", "text": "3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "ddf825b1-6303-46d2-81a1-e3f8f2a92a16", "text": "A 3/4 tizedes tört alakja 0,75.", "type": "true-false", "options": [{"id": "058f44e6-65c9-4d51-995a-75774848306d", "text": "Igaz", "isCorrect": true}, {"id": "d8a5c6c4-ef65-47a8-afbe-0514fa51cce1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7b56089f-3c74-4678-ad07-443504f41332", "text": "Mennyi 0,2 közönséges tört alakban legegyszerűbb formában?", "type": "multiple-choice", "options": [{"id": "7e3631c5-22aa-4ec8-98d6-3da569b09241", "text": "1/5", "isCorrect": true}, {"id": "8b7e4a1c-2112-4cde-95a9-b84573258d5a", "text": "2/10", "isCorrect": false}, {"id": "153ccf85-3c4d-4896-95bf-2d9103d63d5d", "text": "1/2", "isCorrect": false}, {"id": "a7dba829-0cf2-478b-9352-a432a9fe31c7", "text": "2/5", "isCorrect": false}], "timeLimit": 15}, {"id": "3852d313-e751-4b23-b079-736fe2faafb9", "text": "A tört-bingó játékban a válaszok gyors és pontos kiszámítása a nyerő stratégia.", "type": "true-false", "options": [{"id": "f6e58607-9ca1-4164-8612-b3d6fcb1fdad", "text": "Igaz", "isCorrect": true}, {"id": "812a1d77-4704-4475-9e3d-2305df31ae02", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('40683b5b-183a-49e6-a133-bbcbebdc6d8a', '21feff02-016d-46e2-bb9d-c27495133b1b', '40. óra: Hétköznapi problémák megoldása tizedes törtek szorzásának, osztásának felhasználásával', 'Vásárlási, mértékegységes és szöveges feladatok.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "77debc8d-a700-4bd5-80d3-a4fe0bd2b947", "text": "1 kg sajt ára 3200 Ft. Mennyibe kerül 0,5 kg sajt? (3200 * 0,5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1600"}, {"id": "054becc1-affa-4e95-87f7-580c5bb196cb", "text": "Peti 3,5 kg almát vett 400 Ft/kg áron. Hány Ft-ot fizetett?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1400"}, {"id": "8b8a4dec-187e-495f-b703-07bb66e0aef4", "text": "Egy 4,8 méteres lécet 4 egyenlő darabra vágunk. Hány méter egy darab?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.2"}, {"id": "8205bc1c-0672-4317-87da-cdb9f63fe6d5", "text": "Ha 0,25 liter üdítő 150 Ft, akkor 1 liter üdítő (4 * 0,25) 600 Ft-ba kerül.", "type": "true-false", "options": [{"id": "f5329441-ab07-46c4-9e0e-2b38a2850f7d", "text": "Igaz", "isCorrect": true}, {"id": "e2af44da-1724-47b2-990c-538e6f8c954d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "21406b82-86ec-4b62-b6bd-5bbab44fad46", "text": "Hány liter benzin fér a tankba 12000 Ft-ért, ha 1 liter benzin 600 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "0e6532bf-72ec-484e-b254-fb9c11cae3ec", "text": "A becslés segít ellenőrizni, hogy a tizedesvesszőt jó helyre tettük-e a végeredményben.", "type": "true-false", "options": [{"id": "02aeaf49-fd89-437f-8b78-ff65e54c63ab", "text": "Igaz", "isCorrect": true}, {"id": "ed31e480-1479-4143-8a0a-12d28c3fb2fe", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d72c6aba-ee63-4756-b566-461ccb4f317d", "text": "Mennyi 1,5 kg narancs ára, ha 1 kg 800 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8e370b58-7eec-405a-bc6b-c49b94666a82', '21feff02-016d-46e2-bb9d-c27495133b1b', '41. óra: Összetett műveletek, zárójelfelbontás', 'Műveleti sorrend, zárójelezés szabályai tizedes és közönséges törtekkel.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "2e675160-7cc3-4aef-850b-f85fdc8b30c4", "text": "Mi a helyes műveleti sorrend?", "type": "multiple-choice", "options": [{"id": "9c00017a-f049-413b-8901-6ec98ce789fc", "text": "Zárójelben lévő műveletek -> szorzás/osztás balról jobbra -> összeadás/kivonás balról jobbra", "isCorrect": true}, {"id": "41c8ba91-1f4c-4b07-84ef-cda39ad288ad", "text": "Mindig összeadással kezdünk", "isCorrect": false}, {"id": "8045c569-3878-4e94-ab6b-671803a9a8ac", "text": "Balról jobbra haladunk művelet típustól függetlenül", "isCorrect": false}, {"id": "7a31a126-7255-45a4-bde7-cc290c3820e4", "text": "Kivonással kezdünk", "isCorrect": false}], "timeLimit": 15}, {"id": "c1922784-51d3-46e4-bf2e-f341b1a2c352", "text": "Mennyi 2 + 3 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "5dd13700-ec39-4813-bb10-f26a95278b71", "text": "Mennyi (2 + 3) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "5df674e0-87c8-4fa6-a043-69169030f308", "text": "Mennyi 10 - 2 * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "690e554d-4bb2-495a-97b8-cca412d6c860", "text": "A zárójel megváltoztatja a műveletek elvégzésének megszokott sorrendjét.", "type": "true-false", "options": [{"id": "04bf64f6-26e4-46f1-b5b6-6a2b63685978", "text": "Igaz", "isCorrect": true}, {"id": "8ef061c9-757a-45eb-94ea-0ed6f777d445", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c815efb1-5231-4e8a-a67e-e58c0372c6e6", "text": "Mennyi 0,5 + 0,5 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "f3077808-2ea0-44a6-b149-e934e769eed6", "text": "Mennyi (0,5 + 0,5) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('67050fd3-90b4-49ce-9dba-730885795b83', '21feff02-016d-46e2-bb9d-c27495133b1b', '42. óra: Összetett műveletek, zárójelfelbontás gyakorlása', 'Gyakorlás feladatlapok és összetett kifejezések segítségével.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "8e9ecc75-3760-4123-8b89-83ccf96f1356", "text": "Mennyi 100 - (20 + 30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "f4f63ab8-97ed-4625-8751-68244eb01e2a", "text": "Mennyi 15 : 3 + 2 * 5? (5 + 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "35afd8f3-75c9-4a29-8b8e-a08f2e4c0521", "text": "Mennyi 0,2 * 5 + 0,8 : 2? (1 + 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.4"}, {"id": "25e86c05-77f0-430d-ba08-47f45c695ea1", "text": "A szorzás és az osztás egyenrangú műveletek, elvégzésük balról jobbra haladva történik.", "type": "true-false", "options": [{"id": "5ec35707-0c44-47bc-815c-e62c25cce381", "text": "Igaz", "isCorrect": true}, {"id": "3bb50c08-292e-466b-b060-cc799b19afd4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8f2880ed-a8a2-477f-b129-09f89c9fd570", "text": "Mennyi (1,2 + 0,8) * (3,5 - 1,5)? (2 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "0d6e8863-011a-4eaa-b5c0-4d7bb467d9f9", "text": "Ha a zárójel előtt minusz jel áll, a zárójel elhagyásakor a bent lévő tagok előjele az ellenkezőjére vált.", "type": "true-false", "options": [{"id": "2a962341-ef05-4f09-a299-11b7d339b028", "text": "Igaz", "isCorrect": true}, {"id": "6c71e349-c3c8-4522-8cbe-978dd2b31f11", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "41c517be-d11c-42df-9126-2f8135cc46d4", "text": "Mennyi 50 - 5 * 8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c1eab21a-1697-44c2-a37c-1e8622c175f0', '21feff02-016d-46e2-bb9d-c27495133b1b', '43. óra: Összefoglalás', 'A törtekről tanultak ismétlése, rendszerezése, algoritmusos gondolkodás.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "277c6376-345c-4008-96f3-5db5c8c1ae77", "text": "Mennyi 3/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "a6372977-cd32-4795-93ad-c0f837e99524", "text": "3/5", "isCorrect": true}, {"id": "2ae62f1f-e6a0-4991-baad-9ebcaeebe28d", "text": "12/20", "isCorrect": false}, {"id": "f0a24ede-c523-4f9e-9a46-ed7cf507cf31", "text": "7/9", "isCorrect": false}, {"id": "9b346f57-ec30-4ed0-a1f2-dff7c8d8b373", "text": "4/5", "isCorrect": false}], "timeLimit": 15}, {"id": "03d60242-d355-4e44-86d7-768a77b4f8ee", "text": "Mennyi 1/2 : 1/3? (1/2 * 3/1)", "type": "multiple-choice", "options": [{"id": "0ca1be80-c0ea-4e33-96d7-15e71892d603", "text": "3/2 (1,5)", "isCorrect": true}, {"id": "1f7a7c06-131f-4bf3-8e38-eda8eacfb7f2", "text": "1/6", "isCorrect": false}, {"id": "bd337b2b-4eeb-4c3b-aeca-22d0cca28eb4", "text": "2/3", "isCorrect": false}, {"id": "d5056ce6-ec6d-44b6-9552-03987301c851", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "6b89cbd7-9811-4293-9d96-ece461ac05e2", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "c6d222de-48f3-4687-83d5-2fedd0b0ef97", "text": "Mennyi 6,4 : 0,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "460dc95a-9e67-4041-b203-d00148f16b82", "text": "A 0,75 megegyezik a 3/4 közönséges tört értékével.", "type": "true-false", "options": [{"id": "8254745a-a207-4ce8-b72b-a85ea41b8944", "text": "Igaz", "isCorrect": true}, {"id": "8ebe96cf-7f98-4645-9ef5-b5ce61f0f9bc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9a5e54ca-a085-48f5-8620-3e5e839d1ba3", "text": "Mennyi 50-nek a 40%-a (vagy 2/5 része)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "13d0c19f-5401-4072-988c-d1c3dfb6770c", "text": "Melyik szám reciproka 0,5 (azaz 1/2)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b2d3b672-563b-4d10-98a7-f3b8d4a620f6', '21feff02-016d-46e2-bb9d-c27495133b1b', '44. óra: Feladatmegoldás', 'Gyakorló feladatok megbeszélése egyéni és csoportmunkában.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "85f080bf-484b-491a-824c-0b0ce5a87012", "text": "Mennyi 0,75 + 1/4? (0,75 + 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "4e3c68f8-1d81-4c43-b3d5-130bbe2630c4", "text": "Mennyi 1,5 - 3/4? (1,5 - 0,75)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.75"}, {"id": "4c5ee6ce-a43c-4448-ade3-2774569aa945", "text": "Peti elköltötte a pénze 2/5-ét, majd a maradék 1/2-ét. A pénze hányadrésze maradt meg?", "type": "multiple-choice", "options": [{"id": "dbe2fb90-34c1-483b-b919-41691c03a5db", "text": "3/10 (azaz 30%-a)", "isCorrect": true}, {"id": "29d53ccd-65fc-45c4-b897-6e9ec0cf7ac9", "text": "1/5", "isCorrect": false}, {"id": "6585c23c-4c9b-408c-a4a5-b36dae4bd9ec", "text": "1/2", "isCorrect": false}, {"id": "219b1de4-5dd4-454b-a99a-9e381f6ae19c", "text": "0", "isCorrect": false}], "timeLimit": 15}, {"id": "984e61b0-4bd5-481d-b7a0-40784ecd5880", "text": "Ha a számláló és a nevező megegyezik, a tört értéke 1.", "type": "true-false", "options": [{"id": "b0dc2da2-b454-458b-86f4-51344898c8da", "text": "Igaz", "isCorrect": true}, {"id": "db1675ad-8482-4463-8cbe-f269184037bd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2db9e2cc-d3f0-4fad-abef-fd182f0ee37e", "text": "Mennyi 0,8 * 2,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "3c4412dc-8f64-4203-b00d-3731416b25fb", "text": "Mennyi 9 : 0,3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "a6a76a0f-13da-4748-a8a9-01f63d132fac", "text": "A 0,125 megegyezik az 1/8 tört értékével.", "type": "true-false", "options": [{"id": "9396e370-9907-4388-98a9-a32bc7090a55", "text": "Igaz", "isCorrect": true}, {"id": "5272e95d-f3ff-4ad5-92f1-5de62562a471", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f7f313b8-23af-4109-bb3d-08e4581168ee', '21feff02-016d-46e2-bb9d-c27495133b1b', '45. óra: Játékos feladatok törtekkel', 'Társasjáték törtekkel, folyamatos tanári ellenőrzés és hibajavítás.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "b3d7d695-5756-4cc0-b457-5326c0ed309c", "text": "Melyik tört azonos értékű 4/12-vel?", "type": "multiple-choice", "options": [{"id": "f9dfcb0a-94e7-485b-a52f-d862f56e519e", "text": "1/3", "isCorrect": true}, {"id": "97b72d61-5607-4527-89d2-bdbfe0ebb908", "text": "1/4", "isCorrect": false}, {"id": "d26bc62a-6560-456f-8c13-50115bcb37e5", "text": "2/3", "isCorrect": false}, {"id": "0aa08c00-6edb-47fe-af00-8769aee3030b", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "b579d566-23cb-404a-9066-9d7a15135169", "text": "Melyik tört azonos értékű 5/20-szal?", "type": "multiple-choice", "options": [{"id": "9422f945-1f41-42a9-ad7a-40c04db88404", "text": "1/4", "isCorrect": true}, {"id": "1aab0c35-ce87-40ce-b465-a84ffa2af66a", "text": "1/5", "isCorrect": false}, {"id": "b077b4fe-3cc8-431e-84a8-424c488554fc", "text": "2/5", "isCorrect": false}, {"id": "a2e06aa3-9c4a-48d1-ab90-770474312314", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "82d7afd2-0888-492b-92b4-214f2a03271d", "text": "Mennyi 0,6 * 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.3"}, {"id": "13709d29-410d-426e-9630-5f30fb9d29fc", "text": "Mennyi 0,4 : 0,2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "31106d1e-7ed0-4d1f-bb23-37ac764dad2b", "text": "A 0,5 nagyobb, mint a 0,45.", "type": "true-false", "options": [{"id": "1ed66007-d8aa-4996-a089-d252f4150400", "text": "Igaz (0,50 > 0,45)", "isCorrect": true}, {"id": "ce267357-a949-45f1-bb01-c9a8276d2233", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "65363c71-84b7-44fe-a3e2-627def78bdf4", "text": "Hány század van 0,3-ban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "e4e7a379-b0e0-45fd-be51-bc69c79346d9", "text": "A törtek átírása tizedes tört alakba megkönnyíti az összehasonlítást.", "type": "true-false", "options": [{"id": "2bd4f339-ac14-48e2-9301-b43cb6b03d23", "text": "Igaz", "isCorrect": true}, {"id": "50e8e2d8-cfdb-4865-9958-b1663acc9d5f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('dd85ccce-285b-4f67-b715-ef1315b44a1f', '21feff02-016d-46e2-bb9d-c27495133b1b', '46. óra: Témazáró dolgozat', 'Témazáró számonkérés a Törtek fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "062c4287-1e9e-42ba-ba27-4f5f3a362a91", "text": "1. Mennyi 2/3 + 1/6? (4/6 + 1/6)", "type": "multiple-choice", "options": [{"id": "3b3ce691-4214-4e35-9f9b-0f24727756f0", "text": "5/6", "isCorrect": true}, {"id": "a2b89cd5-749a-4f2b-b661-0371c3e9a4a4", "text": "3/9", "isCorrect": false}, {"id": "dfdb67db-bc93-46f3-9020-52659f0ed22d", "text": "3/6", "isCorrect": false}, {"id": "b61055d3-da67-416a-b499-3d797e4b9bcd", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "3a738c2f-74af-41e7-bd16-f01b0576c44d", "text": "2. Mennyi 3/5 * 5/6?", "type": "multiple-choice", "options": [{"id": "55c06f96-abe0-4bd6-83cf-ac8a5f129fbe", "text": "15/30 (azaz 1/2)", "isCorrect": true}, {"id": "b61992fc-8425-404b-898f-72f3a9b1841f", "text": "8/11", "isCorrect": false}, {"id": "74e50d7d-fa55-4530-b79c-644cfe23c511", "text": "15/11", "isCorrect": false}, {"id": "bb844c08-b867-477d-8f81-63629e0a2f0d", "text": "3/6", "isCorrect": false}], "timeLimit": 15}, {"id": "33e8b950-d067-4c08-a0fb-da73df64830a", "text": "3. Mennyi 3/4 : 1/2? (3/4 * 2/1)", "type": "multiple-choice", "options": [{"id": "f8a30cc3-bc24-477b-b42e-bc9348cc7bc6", "text": "6/4 (azaz 3/2 vagy 1,5)", "isCorrect": true}, {"id": "c106a3f8-7103-484e-acae-dfb6a7fc50f8", "text": "3/8", "isCorrect": false}, {"id": "603e33a5-0964-410f-9577-37abf03dbee0", "text": "1/4", "isCorrect": false}, {"id": "d35e3af8-6f59-43a9-8c63-238bda1da65b", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "bfdc77dc-b77f-41ad-a14f-180e269d6dff", "text": "4. Mi a 4/9 reciproka?", "type": "multiple-choice", "options": [{"id": "cf7de230-7f6d-46d0-98d9-373345c01b44", "text": "9/4", "isCorrect": true}, {"id": "44376c88-801a-49f3-b933-5a237dc34551", "text": "-4/9", "isCorrect": false}, {"id": "cea87919-77c9-466d-a724-13ee3cf31530", "text": "1/4", "isCorrect": false}, {"id": "92cc2b35-4199-484d-9e84-eaa143434b19", "text": "4/9", "isCorrect": false}], "timeLimit": 15}, {"id": "5686637a-0006-4601-87c1-f19e545bf41b", "text": "5. Mennyi 2,4 + 3,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6.2"}, {"id": "7307a5d6-ffad-4f13-a425-e44222af50de", "text": "6. Mennyi 1,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.6"}, {"id": "d94e39fe-e9b8-45db-916a-9e07a7630fb9", "text": "7. Mennyi 4,2 : 0,7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "31e3f815-cbb0-4489-af26-af01c5211960", "text": "8. Mennyi 60-nak a 2/3 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "4682b51e-39a3-48c8-ae93-48351598db4d", "text": "9. A 0,25 megegyezik az 1/4 törttel.", "type": "true-false", "options": [{"id": "1ac2961a-2808-4421-823c-7051f334bdbe", "text": "Igaz", "isCorrect": true}, {"id": "7d823ac4-2c3a-4617-8321-48ed7ee08955", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9adbeaa8-616d-496a-9305-2e2fc97bf934", "text": "10. Mennyi (1,5 + 0,5) * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d021f628-04a1-435e-b4f7-6c518cf5d8bb', '21feff02-016d-46e2-bb9d-c27495133b1b', '47. óra: Témazáró dolgozat értékelése', 'A dolgozat megbeszélése, a törtek műveleteinek összefoglaló értékelése.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "025197ce-1383-4c38-a689-a88d5b4ad864", "text": "Mi a leggyakoribb hiba a törtek osztásakor?", "type": "multiple-choice", "options": [{"id": "0dadc499-3da5-4475-a671-359f5c1a2b6a", "text": "Az osztó reciprokával való szorzás elfelejtése", "isCorrect": true}, {"id": "9b693763-628f-4bae-a1cd-be56456204a7", "text": "A számlálók leírása", "isCorrect": false}, {"id": "50b3df95-3e0f-4ee6-bd56-bb4d8e570197", "text": "A zárójel használata", "isCorrect": false}, {"id": "6d2cda92-4729-43f0-9e9c-0163a0ded730", "text": "A művelet elvégzése", "isCorrect": false}], "timeLimit": 15}, {"id": "a6342e5c-0167-4f2c-87f7-4995ca92db5f", "text": "Tizedes törtek osztásakor az osztónak egész számnak kell lennie a művelet elvégzése előtt.", "type": "true-false", "options": [{"id": "289e5631-50fb-49eb-9fbc-8424e6fe3555", "text": "Igaz", "isCorrect": true}, {"id": "866a8fde-37dd-4509-a07f-012e4f41bfd5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2bb53d41-635f-4cff-ba48-1ccfef22f91b", "text": "Mennyi 1/2 * 4/5?", "type": "multiple-choice", "options": [{"id": "f879a931-2c31-44c7-bb0a-0714aed5f11b", "text": "2/5", "isCorrect": true}, {"id": "f14bad91-fb0c-4a37-9a74-750c48ccccef", "text": "4/10", "isCorrect": false}, {"id": "284a5c72-f090-44db-aeb6-3887c1330a8a", "text": "1/5", "isCorrect": false}, {"id": "dc0816ca-ed35-49ad-950e-563be71584a0", "text": "5/7", "isCorrect": false}], "timeLimit": 15}, {"id": "32fc1562-8aa0-45ee-af30-573cfff4cae8", "text": "Mennyi 2,5 : 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "8c17227f-ecae-4e43-a2aa-511a9c880c6b", "text": "A gyakorlás és a hibák javítása segít a jobb teljesítmény elérésében.", "type": "true-false", "options": [{"id": "faccfb71-7065-45d6-b5f6-0be41bf9bb2c", "text": "Igaz", "isCorrect": true}, {"id": "5ff64f1f-e78f-4364-b63f-48d138b8dc9a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c3677b4a-b2a6-4131-90c0-23be348b162b", "text": "Mennyi 100-nak a 3/10 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "f9d1e18f-0afa-494b-8fa7-17acd8dcbf61", "text": "Mennyi 0,8 + 0,4 - 0,2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('154a7732-9368-4c42-a3b6-ce832b1f45d4', '21feff02-016d-46e2-bb9d-c27495133b1b', '50. óra: Egybevágóság', 'Egybevágó alakzatok felismerése, fedésbe hozása eltolással, forgatással, tükrözéssel.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "701f6abb-4318-4326-a3e3-119a41cd4237", "text": "Mikor nevezünk két síkbeli alakzatot egybevágónak?", "type": "multiple-choice", "options": [{"id": "a8fa6cdb-e71f-4763-ace9-0e40f3dc48a9", "text": "Ha alakjuk és méretük pontosan megegyezik, mozgatással fedésbe hozhatók", "isCorrect": true}, {"id": "15a091da-2a5f-4e6a-a596-2387582f8388", "text": "Ha csak a színük egyezik", "isCorrect": false}, {"id": "879a1e82-e716-4d54-8b68-66c2f5e9da92", "text": "Ha a területük 0", "isCorrect": false}, {"id": "59bc3c78-a184-4c36-9469-1479a762cdba", "text": "Ha az egyik kétszer akkora", "isCorrect": false}], "timeLimit": 15}, {"id": "a0a03d87-a521-4144-a7aa-4abf0e81b9f8", "text": "Két egybevágó alakzat kerülete és területe megegyezik.", "type": "true-false", "options": [{"id": "14df9067-4734-44e5-a407-0eb3e4f18c4b", "text": "Igaz", "isCorrect": true}, {"id": "cba27f34-5a59-44a1-af49-9bc81dbf49ca", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dd13b22e-2203-4fb2-bd4d-995df775681f", "text": "Az eltolás, forgatás és tükrözés egybevágósági transzformációk.", "type": "true-false", "options": [{"id": "1dd277cd-77e8-4ceb-b817-5300afaf1ac5", "text": "Igaz", "isCorrect": true}, {"id": "e0e400b3-8399-40c4-a141-787f2cea1c8c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c2161dbc-61ef-48a4-b2f5-41a116c56550", "text": "Egy alakzat eltolása során megváltozik-e az alakzat területe?", "type": "true-false", "options": [{"id": "5c783189-46c1-4cda-9da1-aea78e659d38", "text": "Igaz", "isCorrect": false}, {"id": "f916833d-02a8-4086-b768-62d3075318d3", "text": "Hamis (a terület nem változik)", "isCorrect": true}], "timeLimit": 15}, {"id": "9ad72b71-4f15-4026-8b73-2b0dfb69bfb5", "text": "Melyik állítás HAMIS az egybevágó alakzatokról?", "type": "multiple-choice", "options": [{"id": "38ffca9a-4363-44c7-994a-9b4460efa8f4", "text": "A megfelelő oldalaik hossza eltérő", "isCorrect": true}, {"id": "05413663-c08e-4290-aef4-b985eb763e34", "text": "A megfelelő szögeik egyenlőek", "isCorrect": false}, {"id": "b14e414b-3601-4c6f-b2c6-46866663ba37", "text": "A megfelelő oldalaik hossza egyenlő", "isCorrect": false}, {"id": "766b3a9f-7ce2-4dc2-8086-556d63bfd897", "text": "Területük megegyezik", "isCorrect": false}], "timeLimit": 15}, {"id": "55a1161a-741c-4313-aeaf-6a34d298db6e", "text": "Minden négyzet egybevágó minden más négyzettel.", "type": "true-false", "options": [{"id": "d39db0a3-8875-45f8-88a2-25f2f3dab313", "text": "Igaz", "isCorrect": false}, {"id": "ac7124c6-2f86-446e-a948-a1d03ae62ba7", "text": "Hamis (csak akkor ha oldalhosszuk megegyezik)", "isCorrect": true}], "timeLimit": 15}, {"id": "4fb891d6-91a2-4756-b7a4-af9e6e145cd2", "text": "A tükrözés megtartja a szakaszok hosszát és a szögek nagyságát.", "type": "true-false", "options": [{"id": "2a87fe48-dbd1-4857-bd39-b6457b46b32a", "text": "Igaz", "isCorrect": true}, {"id": "8dc72bae-663a-4cf5-9dee-b4ae603b1ea4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('85f86c9b-de0b-418b-8cdf-ddee618a20be', '21feff02-016d-46e2-bb9d-c27495133b1b', '51. óra: A kör', 'A kör elemei: középpont (O), sugár (r), átmérő (d), húr, körív, körző használata.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "21c70b4b-7f0a-42ae-a86f-ec9fabdaa475", "text": "Hogyan viszonylik a kör átmérője (d) a sugárhoz (r)?", "type": "multiple-choice", "options": [{"id": "5297b634-0c8f-48ea-b95a-5fdae105f8e2", "text": "d = 2 * r (az átmérő a sugár kétszerese)", "isCorrect": true}, {"id": "4ac3c3ef-19a9-4132-9a48-2d0f80c292cf", "text": "d = r / 2", "isCorrect": false}, {"id": "7789a119-b972-4e0a-8079-62c39095b1cc", "text": "d = r + 5", "isCorrect": false}, {"id": "d887f1ba-7b74-404e-93ef-ce17fcb4088d", "text": "d = r * r", "isCorrect": false}], "timeLimit": 15}, {"id": "b6c76598-8c2e-4a21-a994-869f58b939f9", "text": "Ha a kör sugara r = 5 cm, mennyi az átmérője (d)? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "89baba16-c9cb-42c7-8552-2a93cdf58555", "text": "Ha a kör átmérője d = 16 cm, mennyi a sugara (r)? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "c42974d6-3284-4edb-9a51-57ba300aebf2", "text": "A körvonal pontjai a középponttól egyenlő távolságra (sugárnyira) vannak.", "type": "true-false", "options": [{"id": "d4d3c3a1-2721-4a10-9af8-86a4283e28ef", "text": "Igaz", "isCorrect": true}, {"id": "88190bd2-346e-42ec-b74b-bec5429e5bca", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "eec72918-b165-46e6-9f3e-23c02b1d5863", "text": "Mi a kör leghosszabb húrja?", "type": "multiple-choice", "options": [{"id": "6e5eb04c-cd61-4915-9b27-e7bfbed18223", "text": "Az átmérő", "isCorrect": true}, {"id": "4c39fc75-ef15-4e12-bd68-831e7b1ab881", "text": "A sugár", "isCorrect": false}, {"id": "cb1f5c96-d21e-4b20-9f94-d5edb398b8b4", "text": "A körív", "isCorrect": false}, {"id": "65c28dff-2ae6-416b-a1ac-d850c965f20f", "text": "A körcikk", "isCorrect": false}], "timeLimit": 15}, {"id": "2a988446-6a88-4d4e-8e8f-0ed3db4f596a", "text": "A körző a körök rajzolására és távolságok másolására szolgáló szerkesztőeszköz.", "type": "true-false", "options": [{"id": "9be1e188-6003-480c-9597-6b1b118e365d", "text": "Igaz", "isCorrect": true}, {"id": "4ad3b8e2-9c92-45be-b27f-e4e468b6c61e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ca225733-ca69-47b4-9d5b-00b1468fc5a7", "text": "A kör belsejében lévő pontok távolsága a középponttól kisebb, mint a sugár.", "type": "true-false", "options": [{"id": "1b7707ae-fad5-4c53-ab6e-63d26420d8d8", "text": "Igaz", "isCorrect": true}, {"id": "78658d3f-e39b-4057-9b36-ba18cf22fac7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9f934f20-e3a8-4b43-a791-069846e329dc', '21feff02-016d-46e2-bb9d-c27495133b1b', '52. óra: A szakasz felezőmerőlegese', 'A szakaszfelező merőleges tulajdonságai, szerkesztése körzővel és vonalzóval.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "f6831031-279d-42fd-bd2f-6e823aa32c9f", "text": "Mi a szakaszfelező merőleges egyenes fő tulajdonsága?", "type": "multiple-choice", "options": [{"id": "9455b548-389e-4d5f-b228-45c53528c79c", "text": "A szakasz felezőpontján áthaladó, a szakaszra merőleges egyenes, melynek pontjai egyenlő távolságra vannak a szakasz két végpontjától", "isCorrect": true}, {"id": "241e065d-ad8e-4323-8582-f71aac82b4a8", "text": "A szakasszal párhuzamos egyenes", "isCorrect": false}, {"id": "cf2537b5-b56d-400a-a829-809f1da1de4a", "text": "A szakasz egyik végpontján átmenő egyenes", "isCorrect": false}, {"id": "acd533cb-bd60-450b-8c60-bcb19e882c99", "text": "Minden szakaszhoz 2 felezőmerőleges tartozik", "isCorrect": false}], "timeLimit": 15}, {"id": "c020a22e-d9e3-4509-a9a2-6ec6d0b8708d", "text": "Hány felezőmerőlegese van egy szakasznak a síkban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "6297fc16-b234-4a4f-9fc2-f8a1f9db763c", "text": "A szakaszfelező merőleges egyenes pontjai egyenlő távolságra vannak a szakasz két végpontjától.", "type": "true-false", "options": [{"id": "d68165b0-79fe-45fa-8970-95b875ebfc46", "text": "Igaz", "isCorrect": true}, {"id": "9e6c1eac-3005-4530-b811-0c88128a5d72", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ebb4faa8-ff59-4658-b2b2-d3b490eb6be7", "text": "A szakasz felezőmerőlegesének megszerkesztéséhez a szakasz felénél nagyobb körzőnyílás szükséges.", "type": "true-false", "options": [{"id": "2f147ab3-1d15-4b22-b083-609615903d3b", "text": "Igaz", "isCorrect": true}, {"id": "25c80c0e-4393-47e6-b582-63b022e5c38d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "91516589-7c83-4160-a7ab-22f303d2f6cd", "text": "Hány fokos szöget zár be a felezőmerőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "f5b8d2a5-1c58-4f7d-8abf-9b72573afdfb", "text": "A háromszög oldalfelező merőlegesei egy pontban metszik egymást (a körülírt kör középpontjában).", "type": "true-false", "options": [{"id": "469b6df6-a16f-46da-9763-45981271f0d6", "text": "Igaz", "isCorrect": true}, {"id": "266ae877-3d5f-443d-aa07-56a114a14818", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "335efaab-462a-4ffb-9656-0931ddbf833e", "text": "Egy 8 cm-es szakasz felezőpontja a végponttól 4 cm-re van.", "type": "true-false", "options": [{"id": "56bd7460-7e25-42fc-87b4-17b1d36245bb", "text": "Igaz", "isCorrect": true}, {"id": "d8e0e13f-c2b2-4cac-869b-4017643777a7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e348cfc7-e96b-4b45-9914-d3b8730f333f', '21feff02-016d-46e2-bb9d-c27495133b1b', '53. óra: Szerkesztések', 'Alapszerkesztések: szakasz másolása, szög másolása, merőleges és párhuzamos állítása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "c0bd447e-f58a-4992-90d7-86ed1ea6e381", "text": "Milyen eszközt használunk körök és ívek rajzolásához szerkesztéskor?", "type": "multiple-choice", "options": [{"id": "de260dda-c06d-41f4-b4b9-0c542d5b76c8", "text": "Körzőt", "isCorrect": true}, {"id": "6606835f-3061-4a3a-a1a9-9bb1642def77", "text": "Szögmérőt", "isCorrect": false}, {"id": "cb7daf00-f849-4bca-b78d-d6c366b2319b", "text": "Radírt", "isCorrect": false}, {"id": "e1f4d149-399c-45ad-8068-b97573ff6eb7", "text": "Tollat", "isCorrect": false}], "timeLimit": 15}, {"id": "b159315c-7e8f-40cf-9cf1-edd3c03e66ce", "text": "Milyen vonalzót használunk a tiszta geometrikai szerkesztésekhez?", "type": "multiple-choice", "options": [{"id": "2787325a-0cf8-48a1-97fd-57d03100c611", "text": "Beosztás nélküli (egyenes) vonalzót", "isCorrect": true}, {"id": "cf93aa0b-8f46-44b6-b052-2f302b4210c4", "text": "Derékszögű vonalzót beosztással", "isCorrect": false}, {"id": "ce198f2d-6b5e-4646-9794-1008b1e966d2", "text": "Görbe vonalzót", "isCorrect": false}, {"id": "53e3cdeb-5101-4af5-9cde-9060234dc2d9", "text": "Mérőszalagot", "isCorrect": false}], "timeLimit": 15}, {"id": "474c98c3-b31b-4b0e-8540-8b074fe51843", "text": "Szakasz másolásakor körzővel mérjük fel a szakasz hosszát.", "type": "true-false", "options": [{"id": "04b71a79-e110-4a23-b355-24145dc2034b", "text": "Igaz", "isCorrect": true}, {"id": "6a50b9fe-b205-4086-8351-98acf8a0a47f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1a55445b-832a-4876-a0ca-4c685c21eb6f", "text": "A szerkesztéseknél a körzőívek metszéspontjai adják meg a keresett pontokat.", "type": "true-false", "options": [{"id": "aebb5645-0421-4b5a-ba33-82754b895406", "text": "Igaz", "isCorrect": true}, {"id": "20645574-0ff6-4210-8896-29bf1dbc990c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d38c622b-5a09-4958-920d-f2a7d0372168", "text": "Hány fokos szöget zár be két egymásra merőleges egyenes?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "8c181a07-2bd8-4e0a-a85c-20510ecd5b61", "text": "Két párhuzamos egyenes sehol sem metszi egymást a síkban.", "type": "true-false", "options": [{"id": "138982f1-4688-4552-ac37-6adc2aada309", "text": "Igaz", "isCorrect": true}, {"id": "0cfa0294-9d84-42d6-a241-c6b79e603c9b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "15e0e0c8-9b79-4a64-87b3-5bf3a1228f03", "text": "A pontos és esztétikus szerkesztés alapkövetelmény a geometriában.", "type": "true-false", "options": [{"id": "7b4fb38b-a961-42b4-9340-58289b8d3fb6", "text": "Igaz", "isCorrect": true}, {"id": "c4a083ae-41c5-49ae-a6f4-5e759981c609", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e17b2cb1-2aea-433c-b8bd-ecaee069d1c0', '21feff02-016d-46e2-bb9d-c27495133b1b', '54. óra: Szerkesztések II.', 'Egyszerű szerkesztési feladatok: háromszög szerkesztése oldalaiból (SSSZ), háromszög-egyenlőtlenség.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "009ef738-029c-4ed8-a018-00994f9e0b9b", "text": "Mi a háromszög-egyenlőtlenség szabálya?", "type": "multiple-choice", "options": [{"id": "53651ddd-1e19-4e77-81ba-c876fa0fb74c", "text": "A háromszög bármely két oldalának összege nagyobb a harmadik oldalnál (a + b > c)", "isCorrect": true}, {"id": "97623cd0-ab5c-4dfe-a724-61b477e19a99", "text": "A három oldal összege 180", "isCorrect": false}, {"id": "75293ede-6056-496c-940d-67765e078e1c", "text": "A két rövidebb oldal összege kisebb a harmadiknál", "isCorrect": false}, {"id": "ed66c5eb-d214-4f5a-ac31-eb1d947662e4", "text": "Minden oldal egyenlő", "isCorrect": false}], "timeLimit": 15}, {"id": "643b9bf6-8712-44cc-9da6-b4f004e30c53", "text": "Szerkeszthető-e háromszög a 3 cm, 4 cm, 8 cm oldalakkal? (3+4 = 7 < 8)", "type": "true-false", "options": [{"id": "f682fadb-83a4-43f5-8e02-90025c53a5c9", "text": "Igaz", "isCorrect": false}, {"id": "a70733dd-b98c-485b-807b-dacaf8effa8a", "text": "Hamis (nem teljesül a háromszög-egyenlőtlenség)", "isCorrect": true}], "timeLimit": 15}, {"id": "e0a4e27e-22f9-4104-9bb6-59ff002acc47", "text": "Szerkeszthető-e háromszög 5 cm, 6 cm, 7 cm oldalakkal?", "type": "true-false", "options": [{"id": "a3e7b703-d4d3-415b-8e87-6de60e741183", "text": "Igaz (5+6 > 7)", "isCorrect": true}, {"id": "fbe0a8ab-fb9d-4409-ba2d-95ab8be760c9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0d339893-ce04-486d-9a9b-0a461ac52147", "text": "Hány adatra van szükség legalább egy háromszög egyértelmű megszerkesztéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "3e0b6914-64b5-468d-a6b7-508e1b49c513", "text": "A háromszög szerkesztésének lépései: Vázlat -> Adatok -> Szerkesztés -> Ellenőrzés.", "type": "true-false", "options": [{"id": "a14f1009-05f4-4796-b53d-4f88f9435fda", "text": "Igaz", "isCorrect": true}, {"id": "46ce334a-30e2-4a77-8bb3-6beaa67a088b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b937bd46-cda7-46d2-b544-e11b14640aa5", "text": "Szerkeszthető-e háromszög 2 cm, 3 cm, 5 cm oldalakkal? (2+3 = 5)", "type": "true-false", "options": [{"id": "d056a8d0-3177-46e9-b03a-93caf1ab9943", "text": "Igaz", "isCorrect": false}, {"id": "1c289b85-b0de-4a3c-9a52-228b10407ed4", "text": "Hamis (kell hogy > legyen, nem =)", "isCorrect": true}], "timeLimit": 15}, {"id": "6842c771-f0dd-4d38-989a-2c5e0af421b0", "text": "Az egyenlő oldalú háromszög minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "b651d4b0-b616-487e-a13c-dbc67e36e1a6", "text": "Igaz", "isCorrect": true}, {"id": "2b8795ed-0b5f-47b4-ab58-d35a1ebf978e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d3001996-fea1-4af4-b468-bc56df8419a0', '21feff02-016d-46e2-bb9d-c27495133b1b', '55. óra: Számonkérés', 'Számonkérés a síkbeli alakzatokból és alapszerkesztésekből (10 kérdés).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "e6655ee9-e822-4f43-914d-f422f389be25", "text": "1. Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "763f3893-a801-4954-8dbc-31e5fb4f4ce9", "text": "2. Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "8d89da59-477f-4b07-978c-b93c1b2c8ba3", "text": "3. Szerkeszthető-e háromszög 4 cm, 5 cm, 10 cm oldalakkal?", "type": "true-false", "options": [{"id": "51d0b4fb-0509-4ca4-9687-5b9a4a675f7d", "text": "Igaz", "isCorrect": false}, {"id": "2d102dfd-1219-403c-b24f-da497b0f5ecb", "text": "Hamis (4+5 < 10)", "isCorrect": true}], "timeLimit": 15}, {"id": "dccceefb-aef3-4a43-88eb-7abed1d28f47", "text": "4. Ha a kör sugara 7 cm, mennyi az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "26793712-dba0-4ca5-8ae6-a9ef731f5c12", "text": "5. Hány fokos szöget zár be a szakaszfelező merőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "0723526d-caca-4680-93f5-39d2b1bdbd90", "text": "6. A rombusz minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "a6ad2cfc-8237-4cf1-afe2-f720263f6a35", "text": "Igaz", "isCorrect": true}, {"id": "1e18c562-2178-4f05-8117-124610d2c12d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3abb00f9-8784-429e-9dd1-eb4aff5f53d0", "text": "7. Milyen szög a 120°-os szög?", "type": "multiple-choice", "options": [{"id": "b81a66b5-921e-4201-a051-5216e6981567", "text": "Tompaszög", "isCorrect": true}, {"id": "048aa694-4168-43ed-86dd-49d40366b834", "text": "Hegyesszög", "isCorrect": false}, {"id": "2286cf2e-c5e8-4f19-8e5d-b8d8eccde7a4", "text": "Derékszög", "isCorrect": false}, {"id": "41c764c2-8ac4-4932-a15e-e97cb948da11", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "cf0bf3fc-49e1-4d73-9841-5c8f26033358", "text": "8. Hány átlója van egy négyszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "e282cbbb-26a9-42d3-9fec-63d4c63f5088", "text": "9. Az egybevágó alakzatok területe megegyezik.", "type": "true-false", "options": [{"id": "d78055f7-212e-4a38-8767-1b3a1d50b846", "text": "Igaz", "isCorrect": true}, {"id": "ca110bcc-bab3-4923-bb1d-43a005a1772d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "aa072b17-983f-4772-a5ae-1da52f6ac31c", "text": "10. Hány fokosak a szabályos háromszög szögei?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('258b8cde-30a5-40b0-bbd0-dd654b42df33', '21feff02-016d-46e2-bb9d-c27495133b1b', '56. óra: Matematikai játékok', 'Geometriai kirakók (Tangram), alakzatok építése, stratégiák.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "e1f7d1b2-c4b0-41d1-a86e-4b26fe9adf58", "text": "Hány darabból (tanból) áll a klasszikus Tangram kirakó játék?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "689d85d1-91ea-43e8-813b-615427f25e88", "text": "Milyen síkidomokból áll a Tangram készlet?", "type": "multiple-choice", "options": [{"id": "029f863c-10c2-489a-baf3-f5b0ae3deb23", "text": "5 háromszög, 1 négyzet, 1 paralelogramma", "isCorrect": true}, {"id": "2c793ed1-6b4e-4965-90a0-a1b4ef766bb7", "text": "7 négyzet", "isCorrect": false}, {"id": "ae137c76-825c-474c-beb1-4c706ed69604", "text": "7 kör", "isCorrect": false}, {"id": "471d8757-f9bc-477f-9114-75ef4d8d6138", "text": "3 háromszög, 4 téglalap", "isCorrect": false}], "timeLimit": 15}, {"id": "da8a8a83-d38e-473d-b62d-c56d1f0005f2", "text": "A Tangram elemeiből sokféle figura (állatok, emberi alakok, tárgyak) kirakható.", "type": "true-false", "options": [{"id": "da41613f-375b-460c-be59-71516802bdc0", "text": "Igaz", "isCorrect": true}, {"id": "8fd96e58-4102-443c-8398-dae9dc50e068", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f52ae7aa-8265-4c66-baae-eaaa2d0e27eb", "text": "A kirakós játékok fejlesztik a térszemléletet és a síkbeli alakzatok felismerését.", "type": "true-false", "options": [{"id": "2afa2704-20e6-46b7-8216-e3ed547b6b13", "text": "Igaz", "isCorrect": true}, {"id": "056d699c-38b7-4889-8b56-81ae7916523b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d4d36040-22e7-4f69-b8c5-9aa5aec979ac", "text": "A szabályos sokszögekkel hégmentesen lefedhető a sík (pl. szabályos hatoszögekkel).", "type": "true-false", "options": [{"id": "71b0d0c0-dd6f-42f6-a4f8-faf93d301de1", "text": "Igaz", "isCorrect": true}, {"id": "09138b28-795d-4f49-8236-22e5ae8f3a28", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "20f77a53-dbbf-4208-9d04-f5d9026b359e", "text": "Hány oldala van a szabályos hexagonnak (hatszögnek)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "84bd9855-aa04-4cff-b6ca-4a7e5d946da7", "text": "A geometriai játékok során a próbálgatás és a logikai tervezés együtt segít a megoldásban.", "type": "true-false", "options": [{"id": "1925d663-2b7e-4a8e-9901-84a65e2b9750", "text": "Igaz", "isCorrect": true}, {"id": "d629b80f-311a-4d15-ab59-fbf4ba219f81", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('cd14e92c-a969-42a7-b9a8-95444e87c000', '21feff02-016d-46e2-bb9d-c27495133b1b', '57. óra: Tengelyes tükrözés', 'Tengelyes tükrözés fogalma, tengely (t), tárgy és tükörkép (A és A'').', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "3044f0cd-133e-463f-9840-68e2c30e94e7", "text": "Mi a tengelyes tükrözés lényege egy ''t'' tengelyre nézve?", "type": "multiple-choice", "options": [{"id": "ac5bcd2f-4a9b-47e3-a79a-7ae0b4dcd6e3", "text": "A pont és tükörképe a tengelyre merőleges egyenesen van, és egyenlő távolságra van a tengelytől", "isCorrect": true}, {"id": "12816632-5f01-43d3-974f-ff640b220f67", "text": "A pontot eltoljuk párhuzamosan", "isCorrect": false}, {"id": "b78beba8-ed33-4ce0-9810-15ec1279bf6b", "text": "A pontot elforgatjuk 180 fokkal", "isCorrect": false}, {"id": "3d05472c-390f-4b0f-8e6a-7ae7eb2d7c29", "text": "A pontot lefelé mozgatjuk 5 cm-rel", "isCorrect": false}], "timeLimit": 15}, {"id": "8efadf53-cd4f-4eb6-bccc-c63177ef8d7e", "text": "Hol van a tengelyen lévő pont tükörképe?", "type": "multiple-choice", "options": [{"id": "ba671c0b-d1a8-4d4a-a9fe-fdb0d6ccf748", "text": "Önmagában (fixpont)", "isCorrect": true}, {"id": "d566ee41-821f-4d86-9205-85993129e451", "text": "Az origóban", "isCorrect": false}, {"id": "d4d58324-bf6f-461f-8dba-09735666e950", "text": "Végtelenben", "isCorrect": false}, {"id": "7bc3be44-90f2-4870-90d0-b6fb808e0d4e", "text": "A tengely másik végén", "isCorrect": false}], "timeLimit": 15}, {"id": "a944df1d-fc45-4317-82b3-1156beb7ff3d", "text": "Ha a P pont 4 cm-re van a tükörtengelytől, milyen messze van a P'' tükörkép a tengelytől?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "38b5f186-d61e-4728-9aac-71a4846a51b3", "text": "Milyen messze van a P pont a P'' tükörképétől, ha a tengelytől való távolsága 4 cm?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "fa1fbca4-4041-46c5-bb91-44f318c142bb", "text": "A tengelyes tükrözés egybevágósági transzformáció.", "type": "true-false", "options": [{"id": "e3255e79-71b6-461e-b1d9-4b6600f64f3f", "text": "Igaz", "isCorrect": true}, {"id": "9ead64b8-dfb6-46dc-bacb-c26aea8905fa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b0729891-493c-4ae8-8c75-c8e9f94723c6", "text": "A tengelyes tükrözés megváltoztatja az alakzat körüljárási irányát (pl. óramutató járásával megegyezőből ellentétes lesz).", "type": "true-false", "options": [{"id": "5d7b4b29-e74d-4636-9f58-29fb00b5abc1", "text": "Igaz", "isCorrect": true}, {"id": "cb983058-0c6c-4d43-861b-398dc90623dc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9ca36c2a-919c-418e-8a70-1034ec147823", "text": "A tengelyesen tükrös alakzat és tükörképe egybevágó.", "type": "true-false", "options": [{"id": "c4a48591-1274-4f57-b216-8a03b8bdeca9", "text": "Igaz", "isCorrect": true}, {"id": "3b574b1e-cb41-4367-8274-adb0f3d56a3a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('324c3773-ff0d-4e9e-b21a-75803621cfa9', '21feff02-016d-46e2-bb9d-c27495133b1b', '60. óra: Tengelyes szimmetria', 'Tengelyesen szimmetrikus alakzatok, szögfelező és felezőmerőleges szimmetriatengelyként.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "1892e992-5d94-44c7-8755-ea0720c34590", "text": "Mikor nevezünk egy síkidomot tengelyesen szimmetrikusnak?", "type": "multiple-choice", "options": [{"id": "7246d41e-1690-4ccd-81ea-e49ff2018b29", "text": "Ha van legalább egy olyan egyenes (szimmetriatengely), amelyre tükrözve a síkidom önmagába megy át", "isCorrect": true}, {"id": "b1047e56-02ef-40e1-a932-cd1be897196b", "text": "Ha minden oldala egyenlő", "isCorrect": false}, {"id": "74f458b3-7e12-4f61-86fc-1357728bf9fd", "text": "Ha kerek", "isCorrect": false}, {"id": "f77f2ccd-63e3-4e31-ae10-abb7ed07a3e3", "text": "Ha nincs szöge", "isCorrect": false}], "timeLimit": 15}, {"id": "cae57539-f9ec-4c56-8a59-b5dca3d0aecf", "text": "Mi a szögfelező egyenes fő tulajdonsága?", "type": "multiple-choice", "options": [{"id": "249e5b23-c747-4f95-a26e-11151a0f01cd", "text": "A szögtartományt két egyenlő szögre osztja, és pontjai egyenlő távolságra vannak a szög száraitól", "isCorrect": true}, {"id": "578ec1e2-79c8-4f13-8457-8dc30f950cc5", "text": "A szög szárait meghosszabbítja", "isCorrect": false}, {"id": "f5c2c739-d4ba-4f7f-8575-32660fa79281", "text": "Merőleges a szög száira", "isCorrect": false}, {"id": "1cf31799-9317-4782-bd1a-347fd290e2eb", "text": "Párhuzamos a szög száival", "isCorrect": false}], "timeLimit": 15}, {"id": "8f866f01-9100-4b4c-888b-bc65b795acbc", "text": "A szögfelező egyenes a szög szimmetriatengelye.", "type": "true-false", "options": [{"id": "75e2134d-a330-47e5-8682-f26702711a88", "text": "Igaz", "isCorrect": true}, {"id": "5c087363-b14e-4f9f-893d-73cf3a5beda4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7afca1ed-9277-4dd9-b5c6-65fc67e71180", "text": "Hány szimmetriatengelye van egy 60°-os szögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "86d6dbdf-3847-44f0-8175-6c50133f9655", "text": "Hány szimmetriatengelye van a körnek?", "type": "multiple-choice", "options": [{"id": "b9e94a6b-304d-44b2-8ee9-048e06e9e98e", "text": "Végtelen sok (minden középponton átmenő egyenes)", "isCorrect": true}, {"id": "aae3d88d-7c4b-48dc-b149-4986d55aaf8c", "text": "1", "isCorrect": false}, {"id": "3de0cd3d-0b1c-4cf9-878b-2992c77ac7d5", "text": "2", "isCorrect": false}, {"id": "78189f8c-6ce6-4c73-9f03-df089956a69b", "text": "4", "isCorrect": false}], "timeLimit": 15}, {"id": "75dbd41d-0d3f-4cb7-8dd2-abe09a0a8b09", "text": "A szögfelező megszerkesztéséhez körzőíveket használunk a szög szárain.", "type": "true-false", "options": [{"id": "e94c2721-102d-4a3c-a40a-bf786d3d47c5", "text": "Igaz", "isCorrect": true}, {"id": "432a491a-7f62-4f57-89cf-137a82c2ed71", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b7302e63-60e0-40c0-bbd7-95caf643dc10", "text": "Hány fokos két 30°-os részre osztja a szögfelező a 60°-os szöget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0b8a00d4-474e-42d6-bd49-2d4410792c3d', '21feff02-016d-46e2-bb9d-c27495133b1b', '61. óra: Tengelyesen szimmetrikus háromszögek, négyszögek, sokszögek', 'Egyenlő szárú háromszög tulajdonságai és szimmetriatengelye.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "20f30804-bb6a-44c0-960c-77d74e2486cf", "text": "Hány szimmetriatengelye van az egyenlő szárú (nem egyenlő oldalú) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "9395cace-7d27-4f21-9df3-06f60e3937f5", "text": "Hány szimmetriatengelye van a szabályos (egyenlő oldalú) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "844d90ba-94b3-44c1-90db-2da33c144572", "text": "Az egyenlő szárú háromszög alapon fekvő szögei egyenlők.", "type": "true-false", "options": [{"id": "3af6be4b-9aca-42da-9593-c90141d9cd77", "text": "Igaz", "isCorrect": true}, {"id": "12098a37-c809-458c-8a62-4efe625b79f1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "159b4b32-244c-4fe5-9299-c069b4cd967d", "text": "Ha az egyenlő szárú háromszög szárai 8 cm-esek, és alapja 5 cm, mennyi a kerülete? (8+8+5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "21"}, {"id": "44d08eeb-604f-40b7-955b-7c85c9ca9ec9", "text": "Ha az egyenlő szárú háromszög szárszöge (csúcsszöge) 40°, mekkorák az alapon fekvő szögek? ((180-40)/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "c1fd0283-2a7e-49f8-a312-8f844470a02c", "text": "Az egyenlő szárú háromszög szimmetriatengelye az alap felezőmerőlegese és a szárszög felezője is egyben.", "type": "true-false", "options": [{"id": "b0487481-3c19-46fd-846e-8b63c1230c3c", "text": "Igaz", "isCorrect": true}, {"id": "60cc5c16-1dea-41eb-ac93-1df6fb0b872d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b96c6795-3546-4510-9546-fa96b44bcf4c", "text": "Az egyenlő oldalú háromszög minden szöge 60°-os.", "type": "true-false", "options": [{"id": "17ac2ec1-2120-42a4-b1a9-db68d3f2e359", "text": "Igaz", "isCorrect": true}, {"id": "c4a83462-949d-409b-aadc-3ca3e4943282", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8bf6d0cd-3540-41ef-944f-fd225865ba57', '21feff02-016d-46e2-bb9d-c27495133b1b', '62. óra: Tengelyesen szimmetrikus háromszögek, négyszögek, sokszögek II.', 'Tengelyesen szimmetrikus négyszögek (téglalap, négyzet, rombusz, deltoid, szimmetrikus trapéz) szimmetriatengelyei.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "008b37a5-0267-4afc-a844-ebeaf9912558", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "bed1f3d4-a1c5-41ee-93f5-d55312c6301f", "text": "Hány szimmetriatengelye van a téglalapnak (ami nem négyzet)? (az oldalfelező merőlegesek)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "28734016-4e24-4e97-ba7b-6ed9c0203f12", "text": "Hány szimmetriatengelye van a rombusznak (ami nem négyzet)? (az átlók egyenesei)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "93b89270-4045-451b-9d5d-0ff7726eadac", "text": "Hány szimmetriatengelye van a deltoidnak (ha nem rombusz)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "f170ed0d-0791-4def-8f03-1f92987c0f24", "text": "A szimmetrikus (egyenlő szárú) trapéznak 1 szimmetriatengelye van.", "type": "true-false", "options": [{"id": "dd745969-096a-450c-9517-1033ae669c4f", "text": "Igaz", "isCorrect": true}, {"id": "feda310b-62d8-4771-aade-e11834e4aea0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1a34a377-6980-4135-832a-fcc3db771144", "text": "Az általános paralelogrammának (ami nem rombusz és nem téglalap) NINCS tengelyes szimmetriatengelye.", "type": "true-false", "options": [{"id": "e294d207-65fe-4bcb-91a5-48cba3430694", "text": "Igaz (középpontosan szimmetrikus, de tengelyesen nem)", "isCorrect": true}, {"id": "8877942c-5ace-4b36-8b82-4cd1c3ceb83d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d9a9bd94-f9ba-4f0c-8e64-cf180782fd79", "text": "Hány szimmetriatengelye van a szabályos ötszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2b053519-ae8d-489c-a88c-c52bb5064215', '21feff02-016d-46e2-bb9d-c27495133b1b', '63. óra: Szerkesztési feladatok', 'Szakasz- és szögmásolás, szögfelezés, háromszögszerkesztések gyakorlása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "624494c7-b893-4b12-b5fc-73c8412501b9", "text": "Hogyan felezünk meg egy 80°-os szöget szerkesztéssel?", "type": "multiple-choice", "options": [{"id": "e1ab1df7-22df-4627-ae11-5208665e9525", "text": "Megszerkesztjük a szög szögfelező egyenesét, így két 40°-os szöget kapunk", "isCorrect": true}, {"id": "8cbdb295-0da9-4917-9ce4-1fa8143b9e56", "text": "Levágunk belőle 10 fokot", "isCorrect": false}, {"id": "191b5c39-2bff-4b42-bbee-8f55f9c8a7fe", "text": "Merőlegest húzunk a szög egyik szárára", "isCorrect": false}, {"id": "7c974ce5-eb98-4f17-9ee4-194f1272d4ea", "text": "Szögmérővel elosztjuk", "isCorrect": false}], "timeLimit": 15}, {"id": "1d160568-6b44-4083-831c-23e52ade03bd", "text": "A szögfelezéshez körzőt és egyenes vonalzót használsz.", "type": "true-false", "options": [{"id": "bed73c74-f76d-4640-af02-612d73757ffd", "text": "Igaz", "isCorrect": true}, {"id": "8e60756f-37c6-4ecb-b26b-728cc45cce77", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1a0a7898-2b0e-4cbc-9f44-aa4f589012aa", "text": "Hány fokos szögeket kapunk egy 90°-os derékszög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "27faddb5-fc00-44d4-8354-537f3c745cdb", "text": "Hány fokos szögeket kapunk egy 180°-os egyenesszög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "6b34dbbf-ab28-4513-af33-5e1cdb43a171", "text": "Szerkeszthető-e 60°-os szög kizárólag körzővel és vonalzóval (szabályos háromszög szerkesztésével)?", "type": "true-false", "options": [{"id": "17042d6e-994b-4c77-83a6-c16719bfd32c", "text": "Igaz", "isCorrect": true}, {"id": "1a5e6e34-e78b-4316-a1f6-f1e28fd40d7c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d5fbe5ab-f2e9-4f7b-b084-143d98f13469", "text": "Szerkeszthető-e 30°-os szög a 60°-os szög felezésével?", "type": "true-false", "options": [{"id": "ffb8f473-2b11-456a-973c-22603d60c7e3", "text": "Igaz", "isCorrect": true}, {"id": "58ae105e-0624-431a-9653-e42aee2bb03b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "67e929d2-e288-4fab-8683-2c697d55114a", "text": "Szerkeszthető-e 15°-os szög a 30°-os szög felezésével?", "type": "true-false", "options": [{"id": "2d71f26c-7aec-48dd-82eb-8a879d12af55", "text": "Igaz", "isCorrect": true}, {"id": "09349ce1-6f36-47bc-8a2b-936029243df1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('505380aa-ac96-47a0-8375-570ba0c66841', '21feff02-016d-46e2-bb9d-c27495133b1b', '64. óra: Dinamikus szerkesztőprogram megismerése', 'Interaktív geometriai szoftverek (GeoGebra), alakzatok mozgatása, tulajdonságok megfigyelése.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "b4f246c0-41fc-485d-9caa-aeab768ffce1", "text": "Mire való a GeoGebra dinamikus geometriai program?", "type": "multiple-choice", "options": [{"id": "ec4bee8f-b768-49d2-a80b-bd431a8ee7a7", "text": "Geometriai alakzatok szerkesztésére, mozgatására, mérésére és összefüggések felfedezésére", "isCorrect": true}, {"id": "42aba305-9d40-4ce4-9008-07bb2e48cd07", "text": "Szövegszerkesztésre", "isCorrect": false}, {"id": "fa41b80f-d280-4147-a17e-a02b8d44ff99", "text": "Videóvágásra", "isCorrect": false}, {"id": "bdd6c452-9331-41db-aeb4-653453a689fd", "text": "Kódolásra C++ nyelven", "isCorrect": false}], "timeLimit": 15}, {"id": "2c2e7029-262a-422a-97c5-b8bf8382b95a", "text": "Dinamikus szerkesztőprogramban az csúcsok mozgatásakor az alakzat tulajdonságai és összefüggései megőrződnek.", "type": "true-false", "options": [{"id": "4a69954a-05cb-4b78-9cd0-a3e6fcea0bfa", "text": "Igaz", "isCorrect": true}, {"id": "67818d75-0aa2-4a4b-a6bc-c2329359a7df", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "981a13e9-c0e9-4954-9c54-e2198c45152b", "text": "A dinamikus programokban a háromszög belső szögeinek összege mozgattatás közben is mindig 180° marad.", "type": "true-false", "options": [{"id": "e10801dc-ab45-4bdf-83e0-23f2679bb88e", "text": "Igaz", "isCorrect": true}, {"id": "54adfa38-65d3-4974-b519-c68486561140", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c7432845-6fe9-48f3-8b21-3f5ca49e3d9f", "text": "A szerkesztőprogram segítségével ellenőrizhető a kézi szerkesztések pontossága.", "type": "true-false", "options": [{"id": "305e2182-39fe-4a61-8567-174c0a644cad", "text": "Igaz", "isCorrect": true}, {"id": "dfc82afc-e81b-4550-9864-790d563c71ac", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c918d546-cf6e-42bf-8db1-ee86417876fc", "text": "Melyik funkció segít a pontok tengelyes tükörképének azonnali előállításában a szoftverben?", "type": "multiple-choice", "options": [{"id": "c382192e-86e7-4d77-b8c7-0928fc5b3acc", "text": "Tengelyes tükrözés eszköz", "isCorrect": true}, {"id": "adfdd36a-39fc-4b15-8142-19641b827954", "text": "Színezés", "isCorrect": false}, {"id": "4b1e3d08-a037-4d32-864a-80cb5332b81d", "text": "Törlés", "isCorrect": false}, {"id": "035fdd45-c670-4b6d-9189-0d1061351cde", "text": "Nagyítás", "isCorrect": false}], "timeLimit": 15}, {"id": "94a0220a-7964-4b75-8ed1-322e43814d55", "text": "A számítógépes geometriai modellezés segíti a mélyebb megértést.", "type": "true-false", "options": [{"id": "b37825bf-94f0-4985-9c20-7b73f8bef0ab", "text": "Igaz", "isCorrect": true}, {"id": "f4c48eab-824a-4f68-8356-2e52f656416c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "03954fdf-6817-49b9-9856-910e712c9d8d", "text": "Hány fok a teljes szög a geometriában?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f6b819b2-0313-4661-acb8-0e84473a70ae', '21feff02-016d-46e2-bb9d-c27495133b1b', '65. óra: Összefoglalás', 'A Geometria és tengelyes tükrözés fejezet fogalmainak, szerkesztéseinek összefoglalása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "6b76017f-8f4c-4416-ab7f-666f0b489322", "text": "Hány szimmetriatengelye van a téglalapnak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "533dbf6c-f480-4cf6-a833-c1ce3f0536e8", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "27a13086-e99b-48f8-8952-710465e33727", "text": "A tengelyes tükrözés megváltoztatja a síkidom körüljárási irányát.", "type": "true-false", "options": [{"id": "a247591b-046a-4e5f-bddb-a6c6db40eef9", "text": "Igaz", "isCorrect": true}, {"id": "02ccaa3e-8d5d-4974-9dbd-f858437fbda2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7e2cf699-816a-49ec-839b-f8ea8d89e6bf", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "274dcb87-c9da-4ea4-a2ab-cb2f9200583b", "text": "A szakaszfelező merőleges minden pontja egyenlő távolságra van a szakasz két végpontjától.", "type": "true-false", "options": [{"id": "7d47d61f-d790-43f7-a866-d0740172df7d", "text": "Igaz", "isCorrect": true}, {"id": "e0c6f6bf-fc91-423f-8d43-692a8ebf48e8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "18611ea4-492d-42c6-bf66-66b7ff86b225", "text": "Ha a kör átmérője 12 cm, mekkora a sugara? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "261bd4d9-2082-4c25-97ae-06c400f1e910", "text": "A szögfelező egyenes felezi a szöget és egyenlő távolságra van a szög száraitól.", "type": "true-false", "options": [{"id": "a4ad20dc-8dde-423e-b3b4-4f92fc8c25c7", "text": "Igaz", "isCorrect": true}, {"id": "34e551b8-a7ba-40c5-9f30-bc7f9d1121df", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b0889487-23e0-43e4-8631-3394055a6b5a', '21feff02-016d-46e2-bb9d-c27495133b1b', '66. óra: Témazáró dolgozat', 'Témazáró számonkérés a Geometria és tengelyes tükrözés fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "3d090855-c68b-4a71-9326-6f44d911c128", "text": "1. Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "d62b92c2-e2c3-453e-b200-ee3da03ff4a5", "text": "2. Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "78cc8920-e6a6-488a-a790-c31c537d656b", "text": "3. Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "11c8e884-4ce3-4170-8561-9c77e7c5b0cf", "text": "4. Hány szimmetriatengelye van az egyenlő szárú (nem szabályos) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "d0d5f6d8-5f79-4443-b0a8-576591fc0050", "text": "5. Ha a kör sugara 4,5 cm, mekkora az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "8e4400bf-5872-46c7-92ca-cc339c0abe65", "text": "6. A tengelyes tükrözés távolságtartó transzformáció.", "type": "true-false", "options": [{"id": "fccb7ba9-6a6d-459c-8579-c141adf622d8", "text": "Igaz", "isCorrect": true}, {"id": "9b5e08ca-241b-4ba6-a5db-2fb000673855", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b2c9fe76-dd90-493f-bb3f-e0fd9ddfeaf4", "text": "7. Szerkeszthető-e háromszög 3 cm, 5 cm, 9 cm oldalakkal?", "type": "true-false", "options": [{"id": "58dfd890-80e3-473c-a9b8-770e2b6ec8eb", "text": "Igaz", "isCorrect": false}, {"id": "f5b0a44b-e075-4226-abe7-fbf54c45bf51", "text": "Hamis (3+5 < 9)", "isCorrect": true}], "timeLimit": 15}, {"id": "32cc0c4b-51ab-49ce-93eb-f77f4494eb4c", "text": "8. Hány fokos szögeket kapunk egy 120°-os szög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "ae631556-dbcc-49a7-8505-1b2b9d576905", "text": "9. A rombusz minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "43228f10-7c6f-4e4a-8d9b-0c731204265c", "text": "Igaz", "isCorrect": true}, {"id": "650a8a1a-af72-41f4-b611-3507ff355053", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "97e0e5a8-b633-4fa5-a429-b24bbfff91e0", "text": "10. Hol található a tükörtengelyen lévő pont tükörképe?", "type": "multiple-choice", "options": [{"id": "7f846373-5e75-4083-9792-f547fbb6c5c6", "text": "Önmagában", "isCorrect": true}, {"id": "37f61134-9a73-4368-9872-2906d8787ca1", "text": "Az origóban", "isCorrect": false}, {"id": "dc172701-c3ad-484b-a339-17032114f314", "text": "A tengely végétől 5 cm-re", "isCorrect": false}, {"id": "59efb71d-38d5-4641-a65e-4fa11bf457fb", "text": "A sík szélén", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f4f6a969-f1ed-49c1-b684-833a26b4f1a8', '21feff02-016d-46e2-bb9d-c27495133b1b', '67. óra: Témazáró dolgozat értékelése', 'A geometriai témazáró megbeszélése, szerkesztések értékelése és hibajavítás.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "67b5b644-df56-490e-a3a5-fe4e1d99d5a3", "text": "Mi volt a leggyakoribb hiba a szerkesztési feladatok során?", "type": "multiple-choice", "options": [{"id": "6d08ecd4-4296-483a-92e2-7b95640187b0", "text": "A körző pontatlan használata és a háromszög-egyenlőtlenség figyelmen kívül hagyása", "isCorrect": true}, {"id": "2f6e47f0-5cf9-4483-9193-62ecaf206f1a", "text": "A ceruza színe", "isCorrect": false}, {"id": "7e357822-b03d-4224-aa1d-1f0d559c133e", "text": "A füzet vonalazása", "isCorrect": false}, {"id": "803bed32-1ca8-4b6b-bc36-429ec13743e1", "text": "A számok leírása", "isCorrect": false}], "timeLimit": 15}, {"id": "5ec22e11-f04f-4e3f-a3a3-265e51d1ec1a", "text": "A szakaszfelező merőleges merőleges a szakaszra és átmegy a felezőpontján.", "type": "true-false", "options": [{"id": "2262f5f5-7ba9-48d3-9fea-91df64fa229f", "text": "Igaz", "isCorrect": true}, {"id": "17b520d4-0851-4f52-bff5-840ded816a2f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "22ad59a0-328f-496e-842d-652e8834f53a", "text": "Mennyi a kör átmérője, ha a sugara 10 cm?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "c74ccddc-0e9c-4dbe-943c-0efdcd2bae28", "text": "A tengelyes tükrözés során a síkidom területe nem változik.", "type": "true-false", "options": [{"id": "90aba069-d257-4360-8d00-c12b178b9c68", "text": "Igaz", "isCorrect": true}, {"id": "a63cc41f-2f55-48ca-92e2-6c8efd9a1037", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9bc628ef-ca6d-4d4e-ba71-665956f7e854", "text": "Hány szimmetriatengelye van a körnek?", "type": "multiple-choice", "options": [{"id": "8e395a56-43a7-4a2b-b129-fb24bb60480c", "text": "Végtelen sok", "isCorrect": true}, {"id": "ef7a3ca2-cc9d-436d-8357-8b6d5f89e58b", "text": "1", "isCorrect": false}, {"id": "32f0ba35-f84e-4d3d-a8bb-9d384ae6d1b1", "text": "2", "isCorrect": false}, {"id": "9cd7ae5b-c62d-4ad6-95f4-d7de183e3390", "text": "4", "isCorrect": false}], "timeLimit": 15}, {"id": "cc03bd8c-2a9f-4af4-adc6-00bc104a8f72", "text": "A pontos vázlatkészítés megkönnyíti a bonyolultabb szerkesztések elvégzését.", "type": "true-false", "options": [{"id": "85e3239b-ecda-48a3-b4f4-d59a282c446f", "text": "Igaz", "isCorrect": true}, {"id": "a907abac-944d-4c44-95c2-643e8871bb8e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8050539c-fc1b-48ca-8c13-44312c28b0a7", "text": "Mennyi a háromszög harmadik szöge, ha az első kettő 50° és 70°?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0486e64a-84fb-430e-9709-7f71c8f8a35d', '21feff02-016d-46e2-bb9d-c27495133b1b', '70. óra: Feladatok megoldása', 'Hétköznapi recept, ötvözet, keverék és arányos osztási feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "4efc7ab5-1200-44cf-a08b-99623af3d471", "text": "Egy habarcs készítéséhez homok és mész kell 4 : 1 arányban. Hány kg homok kell 50 kg habarcshoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "99796963-c903-44e1-917e-81db8e7ec51b", "text": "Egy szörp elkészítéséhez szörp és víz kell 1 : 4 arányban. Hány dl szörp kell 10 dl (1 liter) italhoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "b3257414-8fe7-4411-918b-a291038009e9", "text": "Ha két testvér 3 : 5 arányban osztozik 800 Ft-on, a nagyobbik rész 500 Ft.", "type": "true-false", "options": [{"id": "cfcd5367-b8dc-46c1-9f0e-8cf4b272fd70", "text": "Igaz (800 / 8 = 100, 5 * 100 = 500)", "isCorrect": true}, {"id": "67df2cc4-1754-4e37-b00a-6809058a4d16", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "73d261bf-8005-44b7-8e83-437f335df025", "text": "Egy téglalap két szomszédos oldalának aránya 2 : 3. Ha a rövidebb oldal 6 cm, hány cm a hosszabb oldal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "05ac7942-293d-4226-8de5-0000e350ea99", "text": "Melyik állítás igaz az arányos osztásra?", "type": "multiple-choice", "options": [{"id": "19035611-8363-42d9-a76c-a68180e7e82c", "text": "A kapott részek aránya megegyezik a megadott aránnyal", "isCorrect": true}, {"id": "1fd4361f-f9c0-4f7f-a5a6-4c14de591db1", "text": "Minden rész egyenlő nagyságú", "isCorrect": false}, {"id": "371bb75d-05cd-4e19-9bb3-3ce3673387a2", "text": "A részek összege kisebb az eredeti mennyiségnél", "isCorrect": false}, {"id": "1c134c1c-2144-4f3f-84a7-fd21a7518f40", "text": "Nem lehet kiszámolni", "isCorrect": false}], "timeLimit": 15}, {"id": "3bbba23b-65fc-4450-ae18-07f02e59ffcf", "text": "Hány g mész kell 50 kg (4:1 arányú) habarcshoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "937568f6-48fd-43d7-abab-351e67fc24c7", "text": "A receptekben megadott hozzávalók aránya lehetővé teszi tetszőleges adag elkészítését.", "type": "true-false", "options": [{"id": "1abc74e8-6f23-4bb6-8f3c-864609c2dc2d", "text": "Igaz", "isCorrect": true}, {"id": "efcad4f8-890a-4ccb-844d-c9aefdef3075", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8d231ea7-597c-446b-99eb-4b0eccdcce80', '21feff02-016d-46e2-bb9d-c27495133b1b', '71. óra: Egyenes arányosság', 'Egyenes arányosság tulajdonságai: hányados állandó, megkétszereződés esetén a másik is megkétszereződik.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "26eec9b0-9449-46d4-8b50-f991789dcdb6", "text": "Mit jelent az egyenes arányosság?", "type": "multiple-choice", "options": [{"id": "d325341a-2052-46e6-90ca-765d7d84b837", "text": "Ha az egyik mennyiség hányszorosára változik, a másik mennyiség is ugyanannyiszorosára változik", "isCorrect": true}, {"id": "3cf6b19d-018f-40be-9273-f5657827792c", "text": "Ha az egyik nő, a másik felére csökken", "isCorrect": false}, {"id": "9ec0d760-db65-4857-8389-d16f507c43d3", "text": "Ha a két mennyiség összege 100", "isCorrect": false}, {"id": "7d2f9efc-95b5-4d89-bb06-85f6e2631b7d", "text": "Ha a két mennyiség szorzata állandó", "isCorrect": false}], "timeLimit": 15}, {"id": "7345e0e4-3dba-40d6-ba5d-e871b830c264", "text": "Egyenes arányosság esetén a két összetartozó érték hányadosa állandó.", "type": "true-false", "options": [{"id": "8135971a-516b-4653-96d0-053e94dd0658", "text": "Igaz", "isCorrect": true}, {"id": "d90288ad-bd07-4fb8-a705-89ba0855ed15", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "35ffc345-3ebf-4722-aaaa-ad5f1dd6633b", "text": "Ha 2 kg alma 800 Ft, mennyibe kerül 6 kg alma? (800 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2400"}, {"id": "26057c48-859a-4444-87b7-4b0d6f5c06bc", "text": "Ha 3 füzet 600 Ft, mennyibe kerül 1 füzet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "54334607-be4f-4cc3-a657-a759d249ab10", "text": "Melyik pár között van egyenes arányosság?", "type": "multiple-choice", "options": [{"id": "6c8c8d17-afed-4d3a-9fcd-69a799fe1d8e", "text": "Az azonos árú termék tömege és a fizetendő összeg", "isCorrect": true}, {"id": "2504baa8-415f-4f3a-abda-a4147ce08060", "text": "Az ember életkora és a magassága felnőttként", "isCorrect": false}, {"id": "0c835593-ffa2-4f3a-af48-2cc5a8aecbd9", "text": "A téglalap két oldala rögzített területnél", "isCorrect": false}, {"id": "6c8e8dd5-052d-4bed-aad2-782415cda30c", "text": "A sebesség és az idő adott úton", "isCorrect": false}], "timeLimit": 15}, {"id": "589cfab8-38fd-494d-bc04-7a9c9b0328c1", "text": "Ha a megvásárolt mennyiséget felére csökkentjük, a fizetendő ár is a felére csökken.", "type": "true-false", "options": [{"id": "38161f79-7f4d-4f34-88bb-cc37892f01bc", "text": "Igaz", "isCorrect": true}, {"id": "39c0f42f-60fa-4724-9091-7b95c410cfae", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ffddc6ad-2e49-4208-ab0c-8917030aef34", "text": "Ha 5 l üdítő 2000 Ft, mennyi 10 l üdítő ára? (Ft-ban)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4000"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9ea2163a-8e90-4e1d-9425-0a7c91afdc34', '21feff02-016d-46e2-bb9d-c27495133b1b', '72. óra: Egyenes arányosság grafikonja', 'Az egyenes arányosság ábrázolása a derékszögű koordináta-rendszerben.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "c5b1ed1b-a563-4b9a-a20a-4ac014df89d7", "text": "Milyen alakzat az egyenes arányosság grafikonja a koordináta-rendszerben?", "type": "multiple-choice", "options": [{"id": "794f7a19-3b22-4e3a-9438-d4cbfdfc8a9f", "text": "Az origóból (0; 0) induló félegyenes (vagy egyenes)", "isCorrect": true}, {"id": "d79e7e95-0765-443e-a167-fb76b8f1bc86", "text": "Parabola", "isCorrect": false}, {"id": "6e25c0c8-3b1f-42d5-966a-c031b29c4427", "text": "Körvonal", "isCorrect": false}, {"id": "7923cd67-aab2-467d-afc3-06a64aedf6fb", "text": "Vízszintes egyenes", "isCorrect": false}], "timeLimit": 15}, {"id": "2967f64f-23ef-4916-bdc7-a3406e406560", "text": "Áthalad-e az egyenes arányosság grafikonja az origón (0; 0)?", "type": "true-false", "options": [{"id": "c0b00916-c172-4c84-be42-c7e5fab38d28", "text": "Igaz (0 mennyiség ára 0 Ft)", "isCorrect": true}, {"id": "1e18d305-1900-4965-9fbd-5e323215cbed", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6d83ede4-ecc7-4b2e-9bac-0458be6f2f6c", "text": "Ha a grafikon áthalad a (1; 300) ponton, mennyi az egységérték?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "3de0e932-3567-4a1e-998d-bd6ee3b58d56", "text": "Ha a grafikon áthalad a (1; 300) ponton, hol metszi a 4-es értéket az y tengelyen? (4 * 300)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}, {"id": "af6b0162-646a-49d3-af26-3a2fd98ee147", "text": "A grafikonról leolvashatók az összetartozó értékpárok.", "type": "true-false", "options": [{"id": "5ce8ddd5-2116-4089-b81b-c03932793059", "text": "Igaz", "isCorrect": true}, {"id": "d72755ce-00bb-4cba-86d9-a192ff1e22a1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "820369ca-cc2e-4109-ba4d-f777ba9a119b", "text": "Egyenes arányosságnál a meredekség megadja az egységárat.", "type": "true-false", "options": [{"id": "768d970b-720f-413f-87b9-f5b7b0771831", "text": "Igaz", "isCorrect": true}, {"id": "24176183-aa09-4dc5-b0aa-c60c5a00aaeb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8fe2853b-e9b7-406d-8378-3d38cbc8aae7", "text": "Ha 0 kg áru 0 Ft, a grafikon a (0;0) pontból indul.", "type": "true-false", "options": [{"id": "7b8c6333-e8ed-4a66-af34-8a5d65b6acea", "text": "Igaz", "isCorrect": true}, {"id": "a909affc-e816-411b-9d2c-a6f26d67c988", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('bdf11f0e-8088-4dcb-a109-1e4f2b28261c', '21feff02-016d-46e2-bb9d-c27495133b1b', '73. óra: Gyakorlóóra', 'Gyakorlati feladatok egyenes arányosságra, táblázatkitöltés, grafikon leolvasás.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "d6784e86-c045-4d97-8aab-e424ebe4d5ee", "text": "Ha 4 méter szalag 1000 Ft, mennyibe kerül 7 méter szalag? (1000/4 = 250 Ft/m, 250*7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1750"}, {"id": "95fb5147-f7e3-4e0b-a3ab-fc82e4642f7d", "text": "Egy autó 100 km-en 7 liter benzint fogyaszt. Hány litert fogyaszt 400 km-en?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "4d2b593d-fbc5-4730-85e5-0b4e4be5eab5", "text": "Ha 2 óra alatt 120 km-t tesz meg a vonat állandó sebességgel, hány km-t tesz meg 5 óra alatt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "a7b4dfe5-71f4-48ee-8adc-7b6c6fdb1c2e", "text": "Az egységár meghatározása megkönnyíti a tetszőleges mennyiség árának kiszámítását.", "type": "true-false", "options": [{"id": "26508728-ed29-40f3-ae83-08d4ca643f68", "text": "Igaz", "isCorrect": true}, {"id": "e7c801a0-a301-44f9-8bbd-56527b1c24f4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5ca7bb5a-8b9a-4d16-af5e-533d6ac2bd87", "text": "Ha 10 füzet 2500 Ft, mennyibe kerül 4 füzet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "63bad138-1e3b-4b8b-b258-f57768e33aae", "text": "Egyenes arányosságnál ha a független változót megháromszorozzuk, a függő változó is megháromszorozódik.", "type": "true-false", "options": [{"id": "2cb281f4-8ff2-425e-82c9-b3e118d6c568", "text": "Igaz", "isCorrect": true}, {"id": "e8fd11b2-d511-4f7e-81ec-a67712be5b69", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6e516af6-620d-425e-870f-69115f9c0020", "text": "Ha 1 kg sajt 4000 Ft, mennyibe kerül 0,25 kg sajt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('86da74d2-aa47-4d6e-9472-2eeb82639077', '21feff02-016d-46e2-bb9d-c27495133b1b', '74. óra: Matematikai játékok', 'Sorozatok szabályai, játékos arányossági feladatok, csoportszervezés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "def84c37-b706-4884-99a5-ac1b934f0956", "text": "Mi a hiányzó szám a sorozatban: 2, 5, 8, 11, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "3955821e-24f3-475b-a122-8c73f311340f", "text": "Mi a szabálya a 2, 4, 8, 16, 32 sorozatnak?", "type": "multiple-choice", "options": [{"id": "1f8170c4-606a-4f63-8578-7892c12c3a93", "text": "Szorzás 2-vel (*2)", "isCorrect": true}, {"id": "ffe17c51-3095-4255-bb9e-44320c44ea29", "text": "Hozzáadás 2-vel (+2)", "isCorrect": false}, {"id": "3641e5e3-e1ce-479f-bb29-600ce6f9c31d", "text": "Négyzetre emelés", "isCorrect": false}, {"id": "038c80ff-22f4-4efa-875f-93abe50a7ec2", "text": "Kivonás 2-vel", "isCorrect": false}], "timeLimit": 15}, {"id": "f9e4d1b3-db5a-4d99-9ba3-d4e7dc80cb10", "text": "A sorozatszabály megállapításához több egymást követő elem vizsgálata szükséges.", "type": "true-false", "options": [{"id": "beafe447-fc9b-4e15-b913-8f0a5be693f7", "text": "Igaz", "isCorrect": true}, {"id": "731c6369-ca19-401f-ac9b-7202b17c98c5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "700adbfc-4af9-4fc1-83cc-980ff60a124e", "text": "Mi a következő szám a 100, 90, 80, 70 sorozatban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "b7135605-adac-4ef4-be75-846139827cae", "text": "Mi a hiányzó szám a Fibonacci sorozatban: 1, 1, 2, 3, 5, 8, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "13"}, {"id": "c85d21b3-7485-4bbd-8313-d98b3043b06b", "text": "A növekvő számsorozatban az elemek értéke folyamatosan nő.", "type": "true-false", "options": [{"id": "b3c258e8-7877-42bd-8a94-3e822953b2a3", "text": "Igaz", "isCorrect": true}, {"id": "adc63050-d3c9-4b51-bd78-7e2010a1d163", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5279c515-33e0-4e86-8c7a-8bebd5f76a3d", "text": "Mi a szabálya a 3, 9, 27, 81 sorozatnak?", "type": "multiple-choice", "options": [{"id": "73d5cfc7-b0d2-4cac-bea8-76d2366009cb", "text": "Szorzás 3-mal (*3)", "isCorrect": true}, {"id": "32d9c164-e60a-497f-8711-93df43126935", "text": "Hozzáadás 6-tal", "isCorrect": false}, {"id": "ef9577ed-d64d-4074-ab5d-ce58744f1e1f", "text": "Hozzáadás 3-mal", "isCorrect": false}, {"id": "1d71a126-82fd-4290-ba42-8be49fc24f63", "text": "Osztás 3-mal", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('afb2d53e-4d19-40bb-aaee-55db6e1313db', '21feff02-016d-46e2-bb9d-c27495133b1b', '75. óra: Szabályok, megfeleltetések', 'Sorozatok megadása képlettel, alakzat-sorozatok, szabályfelismerés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "16b505aa-86f2-4fb8-b768-4aae1360372b", "text": "Ha a sorozat nth elemének szabálya: a_n = 3 * n, mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "b7733847-bd4a-4161-9324-7e14faa6211b", "text": "Ha a sorozat szabálya: a_n = 2 * n + 1, mennyi a 5. elem? (2*5 + 1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "29866836-b59b-4387-b7d1-993e59ba89eb", "text": "A számsorozatok a mindennapi mérésekben és a természetben is megjelennek.", "type": "true-false", "options": [{"id": "bf893f40-3ded-45b2-a4d7-d21db18a0340", "text": "Igaz", "isCorrect": true}, {"id": "7c6f5578-41b0-43e5-a188-3fbe475edca9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a33d3f17-9bf5-4386-8dac-474873300161", "text": "Ha a sorozat szabálya a_n = n * n (négyzetszámok), mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "d9336024-b8a3-4ba5-aa9f-25d140e07091", "text": "Melyik sorozat szabálya a ''Hozzáadás 5-tel''?", "type": "multiple-choice", "options": [{"id": "bb22ff58-57e3-487c-9229-cd962d473817", "text": "5, 10, 15, 20, 25", "isCorrect": true}, {"id": "9fb361d0-a45d-4329-9d7a-c7d20dff7a94", "text": "5, 25, 125", "isCorrect": false}, {"id": "7399167d-7aa1-492e-82fd-f7277590dc22", "text": "5, 4, 3, 2", "isCorrect": false}, {"id": "85f79ed9-4aef-4867-95db-dd8c01b8055d", "text": "1, 2, 4, 8", "isCorrect": false}], "timeLimit": 15}, {"id": "b4909876-32e7-41ed-84aa-3a4d514bcd28", "text": "Az alakzat-sorozatoknál az elemek száma (pl. gyufaszálak száma) számsorozatot alkot.", "type": "true-false", "options": [{"id": "2a71cad1-cf89-467c-9570-443b4370d585", "text": "Igaz", "isCorrect": true}, {"id": "be44c897-b1af-4ad5-8ca9-1a380b2fd554", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c40050a9-6969-4378-89ae-6781faf4c3fb", "text": "Mennyi a 10. páros természetes szám (2, 4, 6, ...)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0845b778-db92-4184-9859-dee5415cf535', '21feff02-016d-46e2-bb9d-c27495133b1b', '76. óra: Gyakorlóóra', 'Gyakorló feladatok sorozatok szabályaira és egyenes arányosságra.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "0c00a668-3563-42a8-ab2f-53698e6ad415", "text": "Mi a hiányzó szám a sorozatban: 1, 4, 9, 16, __, 36? (négyzetszámok)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "fd4c927c-179d-4f1d-a09d-2deae45b2fa9", "text": "Mi a hiányzó szám: 50, 43, 36, 29, __? (kivonás 7-tel)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "8d3b485f-0be3-4eb3-9cd9-dc010f326b40", "text": "Ha 3 kg narancs 1500 Ft, mennyi 1 kg narancs ára?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "500"}, {"id": "e5587a90-1888-46f6-b47e-3711f58a7217", "text": "Ha 1 kg narancs 500 Ft, mennyibe kerül 8 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4000"}, {"id": "5ddcd771-7689-4b34-83ea-942fe0557386", "text": "Egy sorozatnak több különböző folytatása is elképzelhető, ha nem rögzítjük pontosan a szabályt.", "type": "true-false", "options": [{"id": "6c7d5a38-dfe6-4724-adde-91c8ed4bd6d0", "text": "Igaz", "isCorrect": true}, {"id": "0a5e8a2d-bd92-4cd5-bf45-d017caa6c3e9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "609614db-ba57-4b34-8593-ac58bf948a3d", "text": "Mi a szabálya a 1, 3, 7, 15, 31 sorozatnak?", "type": "multiple-choice", "options": [{"id": "a08491de-ce61-4950-abd3-9040ec929d75", "text": "Szorzás 2-vel és hozzáadás 1-gyel (*2 + 1)", "isCorrect": true}, {"id": "1262010d-9be1-4e84-a031-fd006491fa21", "text": "Hozzáadás 2-vel", "isCorrect": false}, {"id": "f84d6ea8-b1f5-4528-9b73-ea98d3b69f58", "text": "Szorzás 3-mal", "isCorrect": false}, {"id": "a5b9dc2c-b2b2-4a0f-8c08-7fbab21ac7d6", "text": "Négyzetre emelés", "isCorrect": false}], "timeLimit": 15}, {"id": "c21c44ec-d91d-407a-adab-1f5c6937c57d", "text": "A számsorozatok logikus gondolkodásra nevelnek.", "type": "true-false", "options": [{"id": "ed7d464b-3c2f-4e0d-8e1e-b6b44e456a2e", "text": "Igaz", "isCorrect": true}, {"id": "d5244f0b-9000-4236-af1d-09af8a404906", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('25d90855-e6c9-4d16-97a5-f188d0ed30d4', '21feff02-016d-46e2-bb9d-c27495133b1b', '80. óra: Létraverseny I.', 'Versenyszerű feladatmegoldás páros munkában az arányosságok témájában.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "aa8f2e3e-9772-40c8-8ea7-e552e2333e44", "text": "Ha 2 m szalag 400 Ft, mennyibe kerül 10 m szalag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "5083348e-707c-4f8a-8291-e8d5eb5b502e", "text": "Mennyi az 5 : 15 arány legegyszerűbb alakja?", "type": "multiple-choice", "options": [{"id": "3da0b675-b264-4ef3-b52a-27addbee745f", "text": "1 : 3", "isCorrect": true}, {"id": "9d38b2e6-d905-47fa-a250-9af2049abce7", "text": "1 : 5", "isCorrect": false}, {"id": "b1ea79a7-f05b-4831-b5c0-9e0b7c60a4be", "text": "3 : 1", "isCorrect": false}, {"id": "3b224ba8-23de-468a-afd6-37022e45ea57", "text": "1 : 2", "isCorrect": false}], "timeLimit": 15}, {"id": "329450d5-a98e-4935-b80b-5da0929f987d", "text": "Mennyi 200-nak a 3/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120"}, {"id": "9f077027-9512-409f-88b2-81b91a315ee8", "text": "Mi a sorozat 5. eleme: 3, 6, 12, 24, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "9acebda2-68e4-47f2-be24-94ada2f89373", "text": "Az arányos osztásnál a részek összege kiadja az eredeti egészet.", "type": "true-false", "options": [{"id": "ad94ac9b-098b-47ad-8b9f-d287be594141", "text": "Igaz", "isCorrect": true}, {"id": "19df9a16-7b42-4d69-97cc-e6e9b6a7f949", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "adb1b578-653b-4ad5-9f8a-be35851d50a1", "text": "Hány dl szörp kell 2 liter (1:4 arányú) hígított italhoz? (20 dl / 5 = 4 dl)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "1463a2ce-5114-46c5-bbea-884e23ffbd86", "text": "A játékos versenyzés növeli a feladatmegoldási motivációt.", "type": "true-false", "options": [{"id": "bd661757-5bbe-426a-912e-49ed127c4f01", "text": "Igaz", "isCorrect": true}, {"id": "ed8cc8c7-6f4d-4310-b2b2-a365cc510579", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('53ec8e46-3547-4ea1-87ce-9a43709e4881', '21feff02-016d-46e2-bb9d-c27495133b1b', '81. óra: Százalékszámítás', '1 egész = 100%, 1% fogalma (századrész), százalék és törtrész kapcsolata.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "6432b90c-59e2-473b-b269-a1f5cebe19a5", "text": "Mit jelent a 1% (egy százalék) fogalma?", "type": "multiple-choice", "options": [{"id": "65d95fd2-361f-4dc2-8d8e-13a34e4c5d86", "text": "Az egész mennyiség 1/100-ad részét (századrészét)", "isCorrect": true}, {"id": "19e1b46a-556a-40da-8e83-a9852f600b92", "text": "Az egész 1/10-ed részét", "isCorrect": false}, {"id": "408ec459-b1d1-4c70-9702-d9c76a7948e0", "text": "100 egészet", "isCorrect": false}, {"id": "3708fe71-871c-401a-bee5-29d78925d68f", "text": "Az egész felét", "isCorrect": false}], "timeLimit": 15}, {"id": "cb664f6d-3962-4751-9276-0cf0d45b0b63", "text": "Hány százalék felel meg a teljes egésznek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "4b002ed4-82cc-4761-a937-ede9a25adc7c", "text": "Hány százalék felel meg a fél (1/2) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "e8eb7ba2-d2a0-400d-ad6a-1b833d71cafa", "text": "Hány százalék felel meg a negyed (1/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "dc0fbc3b-5763-413a-b771-05d54a7ba002", "text": "Hány százalék felel meg a háromnegyed (3/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "75"}, {"id": "17209a23-f0d5-4b26-93a8-11ad198302c1", "text": "A 10% az egész 1/10-ed részét jelenti.", "type": "true-false", "options": [{"id": "ca356491-4067-40d0-a741-8e4d96bf26a5", "text": "Igaz", "isCorrect": true}, {"id": "4722659d-966f-40e9-b4b8-08fe3940a333", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c940eca2-d05c-4e02-9abe-82f8feb70047", "text": "A 20% az egész 1/5-öd részének felel meg.", "type": "true-false", "options": [{"id": "b3bad937-badd-4003-9467-465a3159034b", "text": "Igaz", "isCorrect": true}, {"id": "7f856688-3f4b-4dfc-a4b6-70fc57267e73", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1d2d5e31-f0aa-44eb-a240-677325033162', '21feff02-016d-46e2-bb9d-c27495133b1b', '82. óra: A százalékszámítás gyakorlása', 'Százalékérték kiszámítása következtetéssel (1% kiszámítása) vagy törtrésszel.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "c9c00ded-31f1-437e-88cb-e921b685e5e4", "text": "Mennyi 500 Ft-nak a 10%-a? (500 / 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "aba1dbd1-4c23-4d94-a6ab-c6f91d90ba33", "text": "Mennyi 500 Ft-nak az 1%-a? (500 / 100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "7635e815-d4ae-484e-9fee-501164c5315c", "text": "Mennyi 500 Ft-nak a 20%-a? (500 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "54378d4a-3bc6-42ef-a222-ae6d41b2b03e", "text": "Mennyi 800 kg-nak az 50%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "d6258833-e0cf-4969-9b6b-ad58cca45eae", "text": "A százalékérték kiszámításához az alapmennyiséget megszorozzuk a százaléklábbal és elosztjuk 100-zal.", "type": "true-false", "options": [{"id": "6c4afa46-c5f2-4ccd-a439-c5623afa2420", "text": "Igaz", "isCorrect": true}, {"id": "bd26c044-0ad0-43af-a4f7-268ff6b50900", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2060ebd1-dc4d-4806-805e-7507fa899525", "text": "Mennyi 200 Ft-nak a 25%-a? (200 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "1d1535ca-5822-41c4-944c-e9611b43c139", "text": "Mennyi 1000 Ft-nak a 30%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e06c230c-745c-4f82-ae8a-fa5163702620', '21feff02-016d-46e2-bb9d-c27495133b1b', '83. óra: Feladatmegoldás', 'Százalékszámítással kapcsolatos hétköznapi szöveges feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "79a0a805-4c86-455b-9da1-65ccce19fd6d", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezmény összege? (10000 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "e3b72c87-ca4b-4fd1-bf19-d2a70cf1a4ee", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezményes ár? (10000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8000"}, {"id": "9d15e913-ba35-4c3a-a810-5b0024b10203", "text": "Egy iskolában 400 tanuló van. 55%-uk lány. Hány lány jár az iskolába? (400 * 0,55)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "220"}, {"id": "d3ac4e4d-712e-4bfa-b129-8c85239626ef", "text": "Hány fiú jár az iskolába? (400 - 220)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "6d89789d-b615-4df8-a029-99529e80f4b9", "text": "A kedvezményes ár kiszámításához az eredeti árból kivonjuk a kedvezmény értékét.", "type": "true-false", "options": [{"id": "33db3fbd-19d5-457c-b5a5-e2fb61d5009d", "text": "Igaz", "isCorrect": true}, {"id": "284c203e-e18e-4f96-a93d-f1780fa1cbce", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "da18b45e-9981-4afa-9ab0-4434d3d79998", "text": "Ha egy ár 10%-kal nő, az új ár az eredeti ár 110%-a lesz.", "type": "true-false", "options": [{"id": "ef9e7833-1d3d-4ad0-913b-01b9fd297351", "text": "Igaz", "isCorrect": true}, {"id": "d56bb6cf-1665-43d7-980d-87a1a3485e51", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1ee0829e-b6e3-4c8a-9340-98ea4c6c50a5", "text": "Mennyi 50 000 Ft 5%-os kamata 1 évre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('36be8d08-8afb-46b5-bf98-9a5686f90c1c', '21feff02-016d-46e2-bb9d-c27495133b1b', '84. óra: Feladatmegoldás II.', 'Összetettebb százalékszámítási feladatok, árleértékelések, drágulások.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "ea322f08-46e5-4b29-89c1-19571ede1e7f", "text": "Egy 20 000 Ft-os kabát árát 15%-kal felemelték. Hány Ft a drágulás értéke? (20000 * 0,15)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3000"}, {"id": "cd35e7dc-0acf-41ab-9597-6d646882821b", "text": "Mennyi a kabát új ára a 15%-os drágulás után? (20000 + 3000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "23000"}, {"id": "a99e0c66-103b-4ba0-8498-d0b330d50a51", "text": "A 30-as létszámú osztályban a tanulók 10%-a hiányzott. Hány tanuló hiányzott?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "e4363a45-d5d4-4c47-8f68-f14bdf3051fb", "text": "Hány tanuló volt jelen az osztályban? (30 - 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "5acb5928-5f28-410f-8beb-bd8917207bfc", "text": "Ha a 100 Ft-os termék ára 50%-kal csökken, majd a kedvezményes ár 50%-kal nő, az ár visszatér 100 Ft-ra.", "type": "true-false", "options": [{"id": "a4d15462-26bc-40d3-9517-009c1abbb008", "text": "Igaz", "isCorrect": false}, {"id": "aed0dccc-cae2-463a-93d7-8cafc36f6e8b", "text": "Hamis (50 Ft 50%-os növekedése 75 Ft lesz!)", "isCorrect": true}], "timeLimit": 15}, {"id": "091f4cef-c70e-4d84-bb53-bd876c028fc1", "text": "Mennyi 400 liter 75%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "525e195b-2170-417c-b62a-d0e381a22eff", "text": "A százalékszámítás alapvető ismeret a mindennapi pénzügyi tájékozódáshoz.", "type": "true-false", "options": [{"id": "5a085b0a-2db3-4647-9453-44a38f6b1b15", "text": "Igaz", "isCorrect": true}, {"id": "4382569b-495c-4f6e-81b2-6b09fa0f45a0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('070264bb-dbc6-4b61-9bad-1623db2f7256', '21feff02-016d-46e2-bb9d-c27495133b1b', '85. óra: Projektóra', 'Családi költségvetés készítése megadott keretből, százalékos megoszlások számítása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "77f16a22-0da9-4d34-a379-2b899b257fcd", "text": "Ha a család havi jövedelme 400 000 Ft, és 30%-ot költenek lakhatásra, hány Ft a lakhatási költség?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "897e77b2-9924-46e2-b188-475c8a514ea3", "text": "Ha a jövedelem 40%-át élelmiszerre költik, hány Ft megy élelmiszerre? (400000 * 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160000"}, {"id": "f6cc303f-a040-41c1-82e7-d6a40d38fbfc", "text": "Hány Ft marad megtakarításra és egyéb kiadásokra? (400000 - 120000 - 160000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "b3a212db-8aa1-4d77-a210-76805777c546", "text": "A családi költségvetés készítésekor a kiadások összege nem haladhatja meg a bevételeket.", "type": "true-false", "options": [{"id": "79442d90-ad4d-4c50-aeba-d87ba5e042d0", "text": "Igaz", "isCorrect": true}, {"id": "175b36b8-089c-4c36-9b65-7b109e7e71f4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "90c8fea7-1a79-434b-8e03-916312cfbbfe", "text": "Hány százalékot tesz ki a megmaradt 120 000 Ft a 400 000 Ft-os jövedelemből?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "9efb6434-34be-4746-86e7-cc44bbc6b166", "text": "A százalékos megoszlás kördiagramon ábrázolva jól szemlélteti a kiadások arányát.", "type": "true-false", "options": [{"id": "95f10a75-46a4-4077-a93f-20ca13f0177f", "text": "Igaz", "isCorrect": true}, {"id": "f1fdd395-0c40-4c53-99b8-b35064a1b5df", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9bc2d3ea-779b-4d87-974a-a787b1df4d56", "text": "A tudatos pénzügyi tervezés segít elkerülni az eladósodást.", "type": "true-false", "options": [{"id": "c7e4f5b6-2f72-4079-87fc-aa2b59de7b67", "text": "Igaz", "isCorrect": true}, {"id": "80a0e698-19bc-49fe-9752-c868e9948c8c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('58c4b21c-1429-4dbe-80cc-b0c397b9bb1d', '21feff02-016d-46e2-bb9d-c27495133b1b', '86. óra: Nyitott mondatok', 'Lebontogatás (visszafelé gondolkodás) és próbálgatás módszere egyenleteknél.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "8f1c82ed-611a-4903-9508-cc5a8c5311ad", "text": "Mit jelent a lebontogatás (visszafelé gondolkodás) módszere?", "type": "multiple-choice", "options": [{"id": "642e25c5-0552-4e60-a18d-e5264a39d2ef", "text": "A végeredményből kiindulva az inverz (ellentétes) műveleteket végezzük el visszafelé", "isCorrect": true}, {"id": "a9948fec-f487-4739-9aec-badf4858f187", "text": "Visszafelé írjuk le a számokat", "isCorrect": false}, {"id": "51a30511-36f3-4031-bb8e-02a6ea258fec", "text": "Tippelünk egy számot és feladjuk", "isCorrect": false}, {"id": "f764e655-bf31-4680-89b0-2380263ebcd5", "text": "Kivonunk mindent 100-ból", "isCorrect": false}], "timeLimit": 15}, {"id": "ba834317-f278-47ed-ab8c-c2d6e102cbc7", "text": "Melyik szám teszi igazzá: 2 * x + 5 = 17? (17 - 5 = 12, 12 / 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "5938c20a-24a2-48e9-aff5-f482281cee06", "text": "Melyik szám teszi igazzá: (y - 4) : 3 = 5? (5 * 3 = 15, 15 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "19"}, {"id": "127cd6aa-2601-448d-b08a-d63227ed8351", "text": "Az ellenőrzés során a kapott értéket behelyettesítjük az eredeti nyitott mondatba.", "type": "true-false", "options": [{"id": "ee8053f1-0855-4591-9c12-db3918c05995", "text": "Igaz", "isCorrect": true}, {"id": "d860a04d-63e0-4dd6-b764-caca68b67656", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e30853f5-dabe-47ed-9d57-af4decbe13bc", "text": "Melyik szám teszi igazzá: 3 * a - 10 = 20?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "c9f46b49-c819-429e-b7dc-60056ce3251c", "text": "A próbálgatásos módszernél rendszerezett táblázatot érdemes vezetni.", "type": "true-false", "options": [{"id": "fa6f5841-a1df-4180-9e01-b5d15f6a06b2", "text": "Igaz", "isCorrect": true}, {"id": "91d3e602-4540-4142-a2c5-61e33ba65bda", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c762c50f-2604-45ba-9902-b7d36a248525", "text": "Melyik szám teszi igazzá: x / 4 + 2 = 7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e0042e21-b17e-4a37-b4ff-6d9490039d07', '21feff02-016d-46e2-bb9d-c27495133b1b', '90. óra: Gyakorlóóra', 'Matematikai szövegezésű feladatok gyakorlása, ábrakészítés, összefüggések.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "603f8aca-1426-489b-affb-01ebfd7c0a00", "text": "Apa 4 évvel idősebb, mint Anya. Életkoruk összege 76 év. Hány éves Anya? (2x + 4 = 76 -> 2x = 72)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "dbf803be-3d36-4db8-b6a1-1b24dd185360", "text": "Hány éves Apa? (36 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "629a2d6b-af5a-4144-96b6-d2f123c44042", "text": "Egy téglalap kerülete 40 cm. Hosszabbik oldala 4 cm-rel hosszabb a rövidebbnél. Hány cm a rövidebb oldal? (2*(x + x+4) = 40 -> 4x + 8 = 40)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "b817dab7-6304-4c45-9dfe-c8f45c13dd75", "text": "Hány cm a hosszabbik oldal? (8 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "86d1f9d6-8721-40ce-82d8-2b03730db1ad", "text": "A szakaszos ábrázolás nagymértékben segít a szöveges feladatok összefüggéseinek megértésében.", "type": "true-false", "options": [{"id": "49475664-508b-4377-a547-c28b31259f4a", "text": "Igaz", "isCorrect": true}, {"id": "c9643b94-f496-442c-8e9b-6a61371aefcb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b5e43674-fe0c-4f3f-8728-3257fce1521d", "text": "Három egymást követő egész szám összege 45. Mi a legkisebb szám? (x + x+1 + x+2 = 45 -> 3x + 3 = 45)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "a0197025-1b8e-4e55-a1a8-09590e94a12b", "text": "A válaszmondat felírása kötelező a szöveges feladat végén.", "type": "true-false", "options": [{"id": "38770f02-17db-4708-bd6f-f4db5178a570", "text": "Igaz", "isCorrect": true}, {"id": "45332765-364c-44c0-88de-f624d83599e6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b09ae6aa-b45f-4489-ac23-0925241c632c', '21feff02-016d-46e2-bb9d-c27495133b1b', '91. óra: Feladatmegoldás', 'Hétköznapi vásárlási, méréseket és egyenleteket tartalmazó szöveges feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "381e8a83-f50b-4f07-8834-e68b801eb075", "text": "3 füzet és 1 toll összesen 1100 Ft-ba kerül. A toll ára 200 Ft. Hány Ft 1 füzet ára? (3x + 200 = 1100 -> 3x = 900)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "dbfdc01a-dcd8-4d8f-8d92-d4696f419a8b", "text": "Peti 2000 Ft-tal ment a boltba. Vett 3 kg narancsot 500 Ft/kg áron. Hány Ft visszajárót kapott? (2000 - 1500)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "500"}, {"id": "57f0c1c4-cd86-41b0-a032-a999e8e28e89", "text": "Egy raktárban 120 láda gyümölcs van. Az első nap elvitték a 1/3-át, a második nap a megmaradt ládák felét. Hány láda maradt? (120 - 40 = 80, 80 - 40)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "bb5c4fcc-b8f8-413e-ae75-996aca455cc5", "text": "A mindennapi életben sok probléma modellezhető egyenlettel.", "type": "true-false", "options": [{"id": "ee56b05d-6fac-4f28-8fcb-bcfece3d77d2", "text": "Igaz", "isCorrect": true}, {"id": "1fb9aba2-7837-4ba5-b855-8dbd6def7b62", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d9158a5d-536d-46f8-a341-1c64c9a11cc2", "text": "Melyik egyenlet írja le: ''Egy szám 4-szeresénél 5-tel több a 25''? (4x + 5 = 25)", "type": "multiple-choice", "options": [{"id": "cd02e60c-03c2-4060-9217-4f3c458e335a", "text": "4x + 5 = 25", "isCorrect": true}, {"id": "978028bb-3e38-44d1-8683-b94cc61304e4", "text": "x + 4 + 5 = 25", "isCorrect": false}, {"id": "ca3c2338-0cb7-4e44-9d3b-b554a6d3073e", "text": "4x - 5 = 25", "isCorrect": false}, {"id": "dde4ef6d-178a-40a9-8c2d-13983ba78520", "text": "x / 4 + 5 = 25", "isCorrect": false}], "timeLimit": 15}, {"id": "8574501d-70f0-4342-8ca5-24aac486927a", "text": "Mennyi a gondolt szám a 4x + 5 = 25 egyenletben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "af0a51f7-d357-4ac8-b75e-74f010a61ee7", "text": "Az ellenőrzést a feladat eredeti szövegébe való behelyettesítéssel végezzük.", "type": "true-false", "options": [{"id": "6cf7f3cc-a9f1-48b4-8d55-9c97d89b9148", "text": "Igaz", "isCorrect": true}, {"id": "0a7423e7-e43f-406e-98c4-323248ba186b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ab2f434a-c1e4-4f58-8c80-0bc44d93c140', '21feff02-016d-46e2-bb9d-c27495133b1b', '92. óra: Több megoldás is lehet', 'Több megoldást megengedő szöveges feladatok és egyenlőtlenségek vizsgálata.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "a5c2c7d3-278d-4652-906e-f3417ae10429", "text": "Katinak legfeljebb 10 Ft-ja lehet, és páros számú forintja van. Hányféle lehetséges összege lehet természetes számokban? (0, 2, 4, 6, 8, 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "04af1909-2463-4a7b-94a3-6c2aa7927ccc", "text": "Mely kifejezés jelenti azt, hogy ''legfeljebb 5''?", "type": "multiple-choice", "options": [{"id": "ef5252a8-0843-4163-9f4d-d1fbfde36c9a", "text": "Kisebb vagy egyenlő, mint 5 (x <= 5)", "isCorrect": true}, {"id": "ef596cde-a0e5-4cf9-8a55-8b1620d5e163", "text": "Nagyobb, mint 5", "isCorrect": false}, {"id": "13d306e9-59b9-4f76-a7ea-c790b114667c", "text": "Pontosan 5", "isCorrect": false}, {"id": "da65aefd-6854-482a-be06-7103bc89cdb7", "text": "Legalább 5", "isCorrect": false}], "timeLimit": 15}, {"id": "4f09db06-44bb-4083-888e-a7d0cddf2527", "text": "Mely kifejezés jelenti azt, hogy ''legalább 5''?", "type": "multiple-choice", "options": [{"id": "a030cb92-a605-4854-9b01-2fbc2508c458", "text": "Nagyobb vagy egyenlő, mint 5 (x >= 5)", "isCorrect": true}, {"id": "b2c08182-7d28-4712-a7f8-178d6255713c", "text": "Kisebb, mint 5", "isCorrect": false}, {"id": "664bbb9d-6075-490b-9cd9-95a639241a09", "text": "Pontosan 5", "isCorrect": false}, {"id": "46a00190-f3a2-4824-be07-fa68278a1994", "text": "Legfeljebb 5", "isCorrect": false}], "timeLimit": 15}, {"id": "3c5e5f98-af09-485c-ba47-bc5d500813a4", "text": "A ''legalább 3 és legfeljebb 6'' feltételnek eleget tevő egész számok száma: 3, 4, 5, 6 (összesen 4 szám).", "type": "true-false", "options": [{"id": "3c0ae3b3-e64a-4c1d-a211-8bc2f3ddf17b", "text": "Igaz", "isCorrect": true}, {"id": "5466fe0d-b8a9-492b-a194-0f99d2ce6d0a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0c784982-9726-43d1-ad87-6ae4d3abf20b", "text": "Hány természetes szám megoldása van a 2 * x <= 8 egyenlőtlenségnek? (x = 0, 1, 2, 3, 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "ccc60c3d-f001-4f65-91e4-97c8f500e635", "text": "A több megoldással rendelkező feladatoknál az összes megoldás megtalálása a cél.", "type": "true-false", "options": [{"id": "5430da5d-2e03-43e6-8b1c-7c96c9a43366", "text": "Igaz", "isCorrect": true}, {"id": "3dfc1288-6437-4029-912d-d538de390b93", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4d50d3af-d4f9-4d70-9e10-5a63b620fb7b", "text": "Melyik legkisebb természetes szám teljesíti az x > 7 egyenlőtlenséget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('edd1a33f-2d69-4245-863b-a8700515fd1a', '21feff02-016d-46e2-bb9d-c27495133b1b', '93. óra: Létraverseny II.', 'Versenyszerű feladatmegoldás páros munkában a százalék és szöveges feladatok témakörében.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "a0ec66de-a54b-4fcd-8d57-13533bf8d17d", "text": "Mennyi 1000 Ft-nak a 15%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "4634ade7-1f19-4d6a-932e-677cb8f44a21", "text": "Melyik szám teszi igazzá: 2 * x + 10 = 50?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "be030d01-c651-4c17-ac60-90c68c7723e0", "text": "Ha 3 kg narancs 1200 Ft, mennyibe kerül 5 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "84170a2e-03d2-47b1-8f51-3938d4c4f18e", "text": "Hány százalék felel meg a 3/5 törtnek? (3/5 = 60/100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "b289be98-b339-4b9a-b25c-0a3060748c55", "text": "Gondoltam egy számot, elosztottam 3-mal, hozzáadtam 4-et és 10-et kaptam. Mi a szám? ((10-4)*3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "c306873d-7662-4510-8359-9d7d85b1a812", "text": "A játékos feladványok erősítik az osztály közösségét és a matematikai önbizalmat.", "type": "true-false", "options": [{"id": "12de0b76-b90b-4a36-9e48-f80193bc9984", "text": "Igaz", "isCorrect": true}, {"id": "3f7ce12a-8610-4308-8815-6fd09676af4b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d88e2728-05e8-4c09-a1af-09ab0713decd", "text": "Mennyi 400-nak a 25%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7cccdd65-c993-4b15-87a1-609e8c8ec7dc', '21feff02-016d-46e2-bb9d-c27495133b1b', '94. óra: Összefoglalás', 'A fejezet fogalmainak (arány, egyenes arányosság, százalék, nyitott mondatok) összefoglalása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "cdf5d82b-ffdf-42fe-b678-9b2b61043773", "text": "Mennyi a 8 : 24 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "e43e65ac-6a01-42cc-9db9-289a201ba543", "text": "1 : 3", "isCorrect": true}, {"id": "2d00c948-6c34-4416-8a46-e0f541dcfca2", "text": "1 : 4", "isCorrect": false}, {"id": "4248398c-0146-4943-911a-c3173276b8c0", "text": "2 : 3", "isCorrect": false}, {"id": "d1ccc797-b6f3-4087-a008-3572846d0dcc", "text": "3 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "c66ce2bf-43ec-4f9a-b197-fa8bf0906891", "text": "Hány százalék felel meg a 1/2-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "d8bb0f83-a027-465f-be7a-64ae60f7e096", "text": "Hány százalék felel meg a 1/5-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "6bc15673-9430-432a-b4f2-a6a32b1d9025", "text": "Mennyi 600 Ft-nak a 30%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "8171e1c0-e2ff-4862-9fbe-218f327413f4", "text": "Melyik szám teszi igazzá: 4 * x - 8 = 32? (40/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "e899de89-4a38-4dc5-a84f-c685cf3daff7", "text": "Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "01c2ca71-e1f6-4af6-80a5-e8c0ad6a4dd0", "text": "Igaz", "isCorrect": true}, {"id": "99ed6ccf-d756-4fa6-b544-f801ec4aa389", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f58a39f2-daa1-427e-83fa-7a1339fa4d93", "text": "Mennyi 150-nek a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c9538f50-8dc6-4c74-a607-8b41386729c2', '21feff02-016d-46e2-bb9d-c27495133b1b', '95. óra: Gyakorlóóra', 'Gyakorló feladatok önállóan, becslés és ellenőrzés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "143a2de4-40b3-45e0-ba01-ab6eb5057d35", "text": "Egy 8000 Ft-os táska ára 25%-kal csökkent. Hány Ft a kedvezmény? (8000 * 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "5e9f93aa-0a8b-4a8d-bb4e-35b74e5e26f3", "text": "Mennyi a táska új ára? (8000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6000"}, {"id": "e9c41ca2-1749-4ffe-8bd1-1b1799effc26", "text": "Melyik szám teszi igazzá: (x + 4) : 5 = 6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "26"}, {"id": "60a018f4-56a9-436c-bcf2-b7d0fdadc0f0", "text": "Ha 4 kg alma 1600 Ft, egyenes arányosság esetén 7 kg alma 2800 Ft-ba kerül.", "type": "true-false", "options": [{"id": "8ab44eeb-b3de-4b40-9640-8d9a2f5d7a1b", "text": "Igaz", "isCorrect": true}, {"id": "423bb632-e7fb-46ef-ae4c-71a10f6d766e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d4fa723e-aa70-4164-b2a4-a52bfb7cf8f7", "text": "Mennyi 50-nek a 120%-a? (50 * 1,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "528490de-8c2b-43d6-aba4-0defabb1fc81", "text": "Az ellenőrzés mindig megnyugtató visszajelzést ad a feladat helyességéről.", "type": "true-false", "options": [{"id": "790c063e-b890-4ea4-a305-297dfa2ba826", "text": "Igaz", "isCorrect": true}, {"id": "f3059f86-afd2-4c9b-b555-2509370f799d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f4e6439b-ef73-4685-be68-39307a22440a", "text": "Mennyi 1000-nek az 1%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4b45182b-34d9-437b-b98f-483ee3b8c1a4', '21feff02-016d-46e2-bb9d-c27495133b1b', '96. óra: Témazáró dolgozat', 'Témazáró számonkérés az Arány, százalék, szöveges feladatok témakörből (10 kérdés).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "0d82da41-57d6-4d57-985d-3ce0487577a3", "text": "1. Mennyi a 10 : 35 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "f9755400-72a4-4366-9b51-461ec43d9e10", "text": "2 : 7", "isCorrect": true}, {"id": "16d9ad9f-b040-4a46-aca0-39d420457608", "text": "1 : 35", "isCorrect": false}, {"id": "0e72a578-d100-4383-8a48-6de38160bb5d", "text": "2 : 5", "isCorrect": false}, {"id": "949ff0b0-3276-4164-8a25-26f703c91d27", "text": "5 : 7", "isCorrect": false}], "timeLimit": 15}, {"id": "82416f0e-5f84-42e7-acd6-cc434aae15be", "text": "2. Ossz el 600 Ft-ot 1 : 2 arányban! Hány Ft a nagyobbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "b2706f82-8a22-4c73-8781-697238879165", "text": "3. Ha 3 kg narancs 1500 Ft, mennyibe kerül 4 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "ffe9cfcb-0c04-4062-a003-9f66c5f74742", "text": "4. Hány százalék felel meg a 3/4 törtszámnak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "75"}, {"id": "c30ba9d0-96be-4d1e-85e4-cb46a0f76310", "text": "5. Mennyi 4000 Ft-nak a 15%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "600"}, {"id": "6c5eb887-3a2d-40af-9087-383f69f03d86", "text": "6. Melyik szám teszi igazzá: 3 * x + 8 = 35?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "5df7029f-363f-418c-a6e4-1ecf71ebcd15", "text": "7. Gondoltam egy számot, elosztottam 2-vel, kivontam belőle 5-öt, 10-et kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "25edaadb-a7da-4d45-bf6f-f9996c036c09", "text": "8. Mennyi 200-nak a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160"}, {"id": "9c2b6a34-24e2-4e2b-9a44-fe55b50d7934", "text": "9. Az egyenes arányosság esetén a két mennyiség hányadosa állandó.", "type": "true-false", "options": [{"id": "d400d5bb-6071-4948-a4be-04ef7a49511b", "text": "Igaz", "isCorrect": true}, {"id": "082478a9-f911-42aa-bb33-3d9b46784963", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bde37dfd-d059-421b-ba80-d746c62b0437", "text": "10. Egy 5000 Ft-os nadrág ára 10%-kal nőtt. Mennyi az új ár? (Ft-ban)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5500"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d0c2310f-3acc-4266-aedd-8d9cae455041', '21feff02-016d-46e2-bb9d-c27495133b1b', '100. óra: A sokszögek kerülete', 'Négyzet, téglalap, háromszög és sokszögek kerületének számítása (K).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "cd1ee824-e9ee-4372-adb3-e3c409a16b59", "text": "Mi a téglalap kerületének képlete (a és b oldallal)?", "type": "multiple-choice", "options": [{"id": "24781752-6270-426b-9ddc-68c07594a905", "text": "K = 2 * (a + b)", "isCorrect": true}, {"id": "792d148d-d87c-4406-a506-e23246d64455", "text": "K = a * b", "isCorrect": false}, {"id": "4771db57-15c3-4d40-a58d-e4cb83b85215", "text": "K = a + b", "isCorrect": false}, {"id": "061d025b-3d23-4257-ad8d-22366f257fcb", "text": "K = 4 * a", "isCorrect": false}], "timeLimit": 15}, {"id": "80801506-6917-49e9-a50f-6bb75d9cfd89", "text": "Mi a négyzet kerületének képlete (''a'' oldallal)?", "type": "multiple-choice", "options": [{"id": "e99814aa-980c-4dc8-a775-d0af4faffbe3", "text": "K = 4 * a", "isCorrect": true}, {"id": "ff23ec59-0a82-4209-8e12-67bb85bee74b", "text": "K = a * a", "isCorrect": false}, {"id": "9bd0e695-9cf5-4e3f-af4c-b1bc66d75dfa", "text": "K = 2 * a", "isCorrect": false}, {"id": "b2b07826-6e26-4653-afb8-b6f6baf56ebc", "text": "K = 6 * a", "isCorrect": false}], "timeLimit": 15}, {"id": "c0b7bd84-1356-4d94-85dc-2d4f325957bd", "text": "Mennyi a 6 cm és 8 cm oldalú téglalap kerülete? (2 * (6 + 8))", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "6747c842-212d-43eb-99bb-60d938256b2e", "text": "Mennyi a 7 cm oldalú négyzet kerülete? (4 * 7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "1868d6a0-80d5-464b-b86c-fbd7bcc82d7e", "text": "Mennyi a 3 cm, 4 cm, 5 cm oldalú háromszög kerülete? (3+4+5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "18bf2bc5-a306-4431-9617-c58c05c46f46", "text": "A kerület a sokszöget határoló oldalak hosszának összege.", "type": "true-false", "options": [{"id": "4ce74e26-76ff-4a7e-a4e5-1631024013a2", "text": "Igaz", "isCorrect": true}, {"id": "696bc9c2-8919-4832-9720-b93ac1f35ceb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e8680656-af33-4edd-ab9c-8fadb4992522", "text": "Mennyi a 5 cm oldalú szabályos ötszög kerülete? (5 * 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('542fb4f3-fb2b-4147-ba87-02155f9cb0bb', '21feff02-016d-46e2-bb9d-c27495133b1b', '101. óra: Feladatmegoldás', 'Összetett kerületszámítási és kerítésszámítási szöveges feladatok.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "85faab3a-5a90-4e9e-96c3-fd8de19cbc35", "text": "Egy téglalap alakú kert hossza 20 m, szélessége 15 m. Hány méter kerítés övezi a kertet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "ff1d2b9b-a054-4601-ae3f-9ada230e5283", "text": "Hány méter kerítés kell a 20m x 15m-es kerthez, ha hagyunk egy 2 m-es kaput? (70 - 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "68"}, {"id": "47d1ffff-f57c-48a5-89b4-ddb4c46c8f7c", "text": "Egy négyzet alakú pálya kerülete 100 m. Hány méter hosszú a pálya egy oldala? (100 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "2b60193d-d1b5-433d-b32d-854b4bf40b85", "text": "Ha a téglalap kerülete 30 cm, és egyik oldala 5 cm, mekkora a másik oldal? (15 - 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "0383d78c-830d-4b41-bad0-ba3064f4886a", "text": "A sokszögek kerületét mindig hosszúság-mértékegységben (m, cm, mm) adjuk meg.", "type": "true-false", "options": [{"id": "07c77095-1dfa-4d55-be49-3e555770083f", "text": "Igaz", "isCorrect": true}, {"id": "a7f1ba3b-4d7e-4bc9-9188-16b739fbff9a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "97198558-6359-4387-987f-7654bc4cdc01", "text": "Mennyi a 10 cm oldalú szabályos hatszög kerülete?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "4689a983-75a5-43bf-ba0a-f229baaf3406", "text": "A kerületszámításos feladatoknál az oldalaknak azonos mértékegységben kell lenniük.", "type": "true-false", "options": [{"id": "b7a77c0a-68e1-4311-a389-b498ea769dbb", "text": "Igaz", "isCorrect": true}, {"id": "a4c064da-4ae4-4e5b-8379-b032cb4416a3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5774ef4f-ec58-4c4f-b130-c1c79b72881e', '21feff02-016d-46e2-bb9d-c27495133b1b', '102. óra: A terület és a térfogat mérése', 'A terület és térfogat mértékegységei, lefedés, egységkockák, átváltások.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "4ef1caf8-a202-4078-93d8-fb027eba75ef", "text": "Mi a terület alapvető mértékegysége az SI-ben?", "type": "multiple-choice", "options": [{"id": "310d6dd4-4337-4dd9-8ddd-c864fb9a3442", "text": "Négyzetméter (m²)", "isCorrect": true}, {"id": "a4c8d8bf-cd78-4a0f-af35-7be67874f05e", "text": "Méter (m)", "isCorrect": false}, {"id": "a71c934a-7b36-43d6-9a24-09adee29ace1", "text": "Köbméter (m³)", "isCorrect": false}, {"id": "6c62e219-b2dd-4da8-bbe1-b514f25d84ce", "text": "Liter (l)", "isCorrect": false}], "timeLimit": 15}, {"id": "20dacabc-2c8d-40af-b637-a5038059b547", "text": "Hány cm² 1 dm²? (10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "9326a4d5-8601-46ff-9ddf-08e2e4b55bbe", "text": "Hány dm² 1 m²? (10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "4cef10cc-5930-4837-aec6-a0fa6cf251be", "text": "Hány dm³ 1 m³? (10 * 10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "fb681a74-a202-4650-97f3-938f3683fa71", "text": "1 liter űrtartalom pontosan 1 köbdeciméternek (1 dm³) felel meg.", "type": "true-false", "options": [{"id": "d6b43898-6753-43dc-a9f5-062d564afe0f", "text": "Igaz", "isCorrect": true}, {"id": "79ac3fa6-f353-4e45-b8b9-090f021814db", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3a47ce24-af08-44c0-a3aa-bbdb05f5ce81", "text": "Hány cm³ 1 dm³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "359041bd-e8f8-4743-8afe-dcba9e7cd4a4", "text": "A terület mértékegységei között a szomszédos váltószám 100 (területnél 10²).", "type": "true-false", "options": [{"id": "64cae63a-a240-4f2b-ae10-b399a8412271", "text": "Igaz", "isCorrect": true}, {"id": "9ae32b6b-7a28-43db-b69a-fbb71fb0700f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('24510f13-502f-4ec8-ba7a-3fc255ba9b16', '21feff02-016d-46e2-bb9d-c27495133b1b', '103. óra: Gyakorlóóra. A terület és a térfogat mérése', 'Terület- és térfogat-mértékegységek gyakorlása digitális feladatlapokon.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "52171738-52c5-420e-8f9c-9d610a6162e1", "text": "Hány mm² 1 cm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "146832c2-5009-418a-b3ee-de87ffc3ddd0", "text": "Hány cm³ 2 liter? (2 dm³ = 2000 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "adc231eb-ac17-490f-b546-e1f6a092b903", "text": "Hány m² 500 dm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "b9f42924-1f86-4f7d-bd5f-0da1481b12c3", "text": "Hány litere felel meg 3,5 dm³ víznek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3.5"}, {"id": "87bce388-40f7-4397-8935-92e1aaabd77d", "text": "A térfogat mértékegységei között a szomszédos váltószám 1000 (10³).", "type": "true-false", "options": [{"id": "7fda2cb3-9f04-45ab-93da-7fc8ac49b4d4", "text": "Igaz", "isCorrect": true}, {"id": "ab6de94e-4b55-473e-a1e4-453bb1a71569", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7a50131b-9dc0-47cc-a393-e4fa0f8ca1e2", "text": "Hány dl 1 liter?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "561f2722-da11-4747-a489-5666e5fe5857", "text": "Hány ml 1 dm³ (1 liter)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('64765e25-8df1-44e0-b0e3-37ae128c3907', '21feff02-016d-46e2-bb9d-c27495133b1b', '104. óra: A sokszögek területe', 'Négyzet, téglalap és derékszögű háromszög területe (T).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "37b61eec-7ab9-4d46-a16b-e74aacced23b", "text": "Mi a téglalap területének képlete (a és b oldallal)?", "type": "multiple-choice", "options": [{"id": "ebe628c2-1a79-4472-8dcd-2638f4891766", "text": "T = a * b", "isCorrect": true}, {"id": "fa24cd8e-ddcd-4b39-9060-a2d50f6e4b95", "text": "T = 2 * (a + b)", "isCorrect": false}, {"id": "03911e43-149d-461c-ac13-fff4c95e9fdb", "text": "T = a + b", "isCorrect": false}, {"id": "8312341b-cb02-44ed-8195-9151fc4f7686", "text": "T = a * a * a", "isCorrect": false}], "timeLimit": 15}, {"id": "7d67f838-c6bb-4332-b5cf-79f022db6966", "text": "Mi a négyzet területének képlete (''a'' oldallal)?", "type": "multiple-choice", "options": [{"id": "52b3a315-301f-4dea-956b-8cadf9ddfab3", "text": "T = a * a (a²)", "isCorrect": true}, {"id": "9588bb67-55e3-4de1-aed0-b5c8f511baa2", "text": "T = 4 * a", "isCorrect": false}, {"id": "92edb2c9-8f82-4186-ae0d-e759d3bbb8fa", "text": "T = 2 * a", "isCorrect": false}, {"id": "d298f9f9-fde8-4d10-9fd9-3d64ad932c6d", "text": "T = a * 10", "isCorrect": false}], "timeLimit": 15}, {"id": "d62463c2-74c2-4e74-bba4-da38b5777f2a", "text": "Mennyi a 6 cm és 8 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "d6ba2940-a13a-444f-86a8-9cdbd286613f", "text": "Mennyi a 5 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "c7fc5960-223c-413c-941b-5f937a4cd22d", "text": "Mi a derékszögű háromszög területének képlete (a és b befogókkal)?", "type": "multiple-choice", "options": [{"id": "a1ec203d-02ff-427e-a4fe-b3ae795677ea", "text": "T = (a * b) / 2", "isCorrect": true}, {"id": "ef585af3-4e5f-4dcc-be2c-e5001d45b10b", "text": "T = a * b", "isCorrect": false}, {"id": "0c0c57aa-8c4f-4a12-b7d5-f1990191e3c3", "text": "T = a + b", "isCorrect": false}, {"id": "d443a4de-9032-4fd6-9b68-dc82e9565549", "text": "T = 2 * a * b", "isCorrect": false}], "timeLimit": 15}, {"id": "0f69dc5d-4cc0-4105-9817-daec6f7802f6", "text": "Mennyi a 6 cm és 8 cm befogójú derékszögű háromszög területe? ((6*8)/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "e43d8740-5b57-43a2-aec2-4664d7c9ce81", "text": "A derékszögű háromszög területe a két befogójú téglalap területének fele.", "type": "true-false", "options": [{"id": "d2e12d31-9c46-4ad7-9a94-a095b24b7aca", "text": "Igaz", "isCorrect": true}, {"id": "b341bd6c-6610-4921-b4d4-9dca53754eb8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1253d852-32ab-43a5-87d7-300ab8ccc84a', '21feff02-016d-46e2-bb9d-c27495133b1b', '105. óra: Feladatmegoldás', 'Kerület- és területszámítási feladatok, lakóház és szobapadló tervezése.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "adaf9965-17a4-4223-bd85-7e78a4c99275", "text": "Egy 5 m hosszú és 4 m széles szobába szőnyeget fektetünk. Hány m² a szoba területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "42a90267-3319-459c-b2d1-f6f9d0eac99e", "text": "Ha a parketta ára 5000 Ft/m², mennyibe kerül a 20 m²-es szoba parkettázása?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100000"}, {"id": "8157b254-fe83-4f53-aa55-02c6d23fea4e", "text": "Hány méter szegélylécre van szükség a 5m x 4m-es szobához (kerület)? (2*(5+4))", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "2a15f4a4-4224-463d-9c7c-141160f64d00", "text": "Egy négyzet alakú szoba területe 36 m². Hány méter hosszú a szoba egy oldala?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "cdc5e5ff-a490-42e3-9d4f-85ece0df4e4c", "text": "A terület számításához a méreteket azonos mértékegységre kell hozni a szorzás előtt.", "type": "true-false", "options": [{"id": "f148abe5-0ae2-4527-bb0d-96422221c99f", "text": "Igaz", "isCorrect": true}, {"id": "5228eb23-51b1-4076-8d74-dfd19ba476d6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "daf7ead7-2b23-4c2c-8a88-20724a84486f", "text": "Mennyi a 10 cm és 4 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "4690cd14-17f1-41bf-9e3c-3cb0deb72fa1", "text": "A lakástervezésben a m² alapvető fontosságú.", "type": "true-false", "options": [{"id": "8a2f300d-310f-4867-afb6-3fb080a0d039", "text": "Igaz", "isCorrect": true}, {"id": "72de55a6-08f9-447d-b182-63b5b03dacc4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('bda6aefe-cab4-4e75-ac06-c6ffb5919e70', '21feff02-016d-46e2-bb9d-c27495133b1b', '106. óra: Alakzatok a térben', 'Testek elnevezései (kocka, téglatest, hasáb, piramis), él, lap, csúcs, nézetek (elölnézet, felülnézet, oldalnézet).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "066327bc-848d-4a30-9933-4d9f45421303", "text": "Hány lapja van a téglatestnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "5c98fd86-943a-422c-8e8a-1b02df9d031a", "text": "Hány csúcsa van a téglatestnek (és a kockának)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "f704dfe1-df97-4820-b45c-45eb5a20224a", "text": "Hány éle van a téglatestnek (és a kockának)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "edf381a7-bec8-48f8-bf79-133f8b2c507f", "text": "A kocka minden lapja egyenlő négyzet.", "type": "true-false", "options": [{"id": "dd087d9d-0554-4146-96a2-135e71189c87", "text": "Igaz", "isCorrect": true}, {"id": "d3b350af-8537-44d8-a928-16e8ce8d6952", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "44d5eafc-e20a-41c5-956b-9df0d02b8350", "text": "Milyen alakúak a téglatest lapjai?", "type": "multiple-choice", "options": [{"id": "7a58f2fd-3940-4d69-af52-018ee2f19418", "text": "Téglalapok (melyek között négyzet is lehet)", "isCorrect": true}, {"id": "534a6c33-8147-464b-8de7-e82532e02fc9", "text": "Háromszögek", "isCorrect": false}, {"id": "f6f3d6bb-15b6-4322-8ace-5bdd489e1551", "text": "Körök", "isCorrect": false}, {"id": "8eb0f8c1-f8e5-496e-9e3b-7582cea70658", "text": "Ötszögek", "isCorrect": false}], "timeLimit": 15}, {"id": "faa4966d-a9a4-47e2-aa48-7d78592a4ab5", "text": "A testek felülről, elölről és oldalról készített 2D vetületei a vetületi képek.", "type": "true-false", "options": [{"id": "c8c45f03-434e-42e8-898d-83cee5a1b222", "text": "Igaz", "isCorrect": true}, {"id": "0784d9d6-269e-476c-96b5-b8a368c4ad2b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ef80f9d7-f33e-4d06-8a75-02225aab3259", "text": "Hány lapja van a négyszög alapú gúlának (piramisnak)? (1 alap + 4 oldal)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a662641a-5a05-412b-a6c7-babde2874a36', '21feff02-016d-46e2-bb9d-c27495133b1b', '110. óra: Testek térfogata', 'Téglatest és kocka térfogatának (V) kiszámítása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "b39f5f2d-4c3e-4b75-818e-2077eb32dfb3", "text": "Mi a kocka térfogatának képlete (''a'' éllel)?", "type": "multiple-choice", "options": [{"id": "42b0a6c6-d459-435c-b619-5dd4f0916081", "text": "V = a * a * a (a³)", "isCorrect": true}, {"id": "2177e29c-71bf-447e-95d3-60adb6b2fc10", "text": "V = 6 * a²", "isCorrect": false}, {"id": "34660e69-a11c-4ee5-ba38-990045d2e3d3", "text": "V = 12 * a", "isCorrect": false}, {"id": "28df1be7-ccd4-4b34-80d6-2aefca72c690", "text": "V = a + a + a", "isCorrect": false}], "timeLimit": 15}, {"id": "423dd54f-aaea-4e87-ba8d-90673ee28d2a", "text": "Mi a téglatest térfogatának képlete (a, b, c élekkel)?", "type": "multiple-choice", "options": [{"id": "843d4bba-78fa-4d23-9b7a-b6ed67cf1e21", "text": "V = a * b * c", "isCorrect": true}, {"id": "2b668303-23f7-4e8c-a17f-8d403aa6006c", "text": "V = 2 * (a+b+c)", "isCorrect": false}, {"id": "007db31f-0ba3-45f9-8d37-495632ffdbc7", "text": "V = a * b", "isCorrect": false}, {"id": "61c70420-b11d-4d6b-84e7-4cf6a563743f", "text": "V = a + b + c", "isCorrect": false}], "timeLimit": 15}, {"id": "90e8bd4d-b503-46dd-b0c3-dc2f9a0f5e1e", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "ce9244f6-d587-4855-aa90-c88d50e40aeb", "text": "Mennyi a 2 cm, 4 cm, 5 cm élű téglatest térfogata? (2 * 4 * 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "fdf63392-ec95-4a8b-a9c6-b5cbdad44769", "text": "A térfogatot mindig köbmértékegységben (cm³, m³, dm³) vagy űrmértékben (liter, dl) adjuk meg.", "type": "true-false", "options": [{"id": "3686aa7e-8789-48e7-9ad7-5e39add76039", "text": "Igaz", "isCorrect": true}, {"id": "1fd20c31-54da-4f87-a0b2-ba18406b99c9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7c72f87f-562e-494b-9aec-c99c06292045", "text": "Mennyi a 4 cm élű kocka térfogata? (4 * 4 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "158ceff2-ebc4-4a93-be6b-5cecc57afec2", "text": "Mennyi a 10 cm élű kocka térfogata cm³-ben? (1000 cm³ = 1 liter)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b9ae19a9-26a3-478b-a150-03f77564bfc0', '21feff02-016d-46e2-bb9d-c27495133b1b', '111. óra: Projektóra', 'Épülettervezés I. - Vetületi képek megrajzolása, makett alaprajzának elkészítése.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "f26758b3-a0d3-488c-b9db-cf4754fd7fd8", "text": "Mit mutat meg egy épület felülnézete (alaprajza)?", "type": "multiple-choice", "options": [{"id": "b1082400-63bf-4776-883d-165117d79776", "text": "Az épület felülről látható elrendezését és méreteit", "isCorrect": true}, {"id": "433cfd2b-ff74-4fc8-bec7-8664163af58c", "text": "A tető színét", "isCorrect": false}, {"id": "1315e5d0-30ed-49f6-8d9f-6bd4adea8e7f", "text": "Az épület magasságát", "isCorrect": false}, {"id": "ebbafe39-cd9e-437d-9120-6008608dbec3", "text": "Az ablakok mintáját", "isCorrect": false}], "timeLimit": 15}, {"id": "758a8cd0-8acc-47d5-a54e-c2b86070eb88", "text": "Egy épület makettjének elkészítése segít a térbeli arányok megértésében.", "type": "true-false", "options": [{"id": "871020fe-e5de-4765-820c-7bc9110d4dd2", "text": "Igaz", "isCorrect": true}, {"id": "956539de-818a-4fa8-a177-c7977cb77e41", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c9510184-fc9e-4e3a-9343-929549a73534", "text": "Hány m² az 5 m x 6 m-es alaprajzú házalap területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "17c07822-86fa-48b2-9441-380e2577c8fd", "text": "A méretarányos rajz készítése elengedhetetlen az építészetben.", "type": "true-false", "options": [{"id": "3d0d1f1f-8add-426f-9514-99f6ccc8f3f3", "text": "Igaz", "isCorrect": true}, {"id": "e9fc48cd-f11a-4a3b-8d50-d78041027336", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dca464ed-3244-42c9-babe-373aafd948b7", "text": "Ha az 1:100 méretarányú rajzon a fal 5 cm, hány méter a valóságban? (5 * 100 cm)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "3d7a0ecb-d716-4c57-8dde-98590baf57ca", "text": "A csoportszervezés és munkamegosztás felgyorsítja a projekt elvégzését.", "type": "true-false", "options": [{"id": "09a15322-b8a6-456d-a766-c476e1bdf4c0", "text": "Igaz", "isCorrect": true}, {"id": "f01eeff2-74d8-4260-b0e4-de8f50c233b6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b30b993c-8c5d-4362-970b-c71f904fd51a", "text": "Hány oldallapja van a téglatest alakú épületnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e157b224-e599-4f8d-9c8d-aef55f962067', '21feff02-016d-46e2-bb9d-c27495133b1b', '112. óra: Projektóra II.', 'Épülettervezés II. - Makett megépítése kartonból, legóból, egységkockákból.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "f9e68249-79ea-417e-80c5-8ab565a0f788", "text": "Hány darab 1 cm³-es kiskockára van szükség egy 3 cm x 4 cm x 5 cm-es épületmakett megépítéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "0252685c-6011-440f-a8c3-ab967f2c4193", "text": "Az épületmakett térfogata megegyezik a felhasznált egységkockák térfogatának összegevel.", "type": "true-false", "options": [{"id": "28c5f7e7-e451-4ed9-b2ce-e1f79687b62d", "text": "Igaz", "isCorrect": true}, {"id": "9ff6a733-54f0-4f0d-a410-c011d061b56b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2f93f79f-2e8f-4975-930f-e3eaf9f34c82", "text": "Melyik testből építhető fel a legkönnyebben téglatest alakú ház?", "type": "multiple-choice", "options": [{"id": "8a02a797-2519-416e-8bc9-fdb89a5d2e81", "text": "Egységkockákból / kartondobozból", "isCorrect": true}, {"id": "be7f2309-72e1-4efb-8967-9c6d50e35afc", "text": "Gömbökből", "isCorrect": false}, {"id": "6f3b5a9c-8b96-41f6-bb65-3eadd9bcb51b", "text": "Kúpokból", "isCorrect": false}, {"id": "e351b022-656e-4daa-ad72-2be5776dd0af", "text": "Hengerekből", "isCorrect": false}], "timeLimit": 15}, {"id": "718b5477-3e9c-403b-a566-59a376822f6b", "text": "A makett készítése során a stabil szerkezet kialakítása a cél.", "type": "true-false", "options": [{"id": "a0200587-9595-4d2d-94c1-af7b0e967506", "text": "Igaz", "isCorrect": true}, {"id": "bfab3839-7e5a-46e9-9ef8-3e3cb62682cb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5062a770-95e0-47b0-b74c-e494da4899d2", "text": "Mennyi a 2 cm élű kockákból álló 2x2x2-es házikó térfogata? (8 * 8 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "0fecc9b8-f83c-494a-940b-49c448b5ee54", "text": "A projektmunka kreatív megoldásokat ösztönöz.", "type": "true-false", "options": [{"id": "3bc0816e-9a63-4eaf-bdf0-38ea199613a2", "text": "Igaz", "isCorrect": true}, {"id": "b76b8b03-960d-4e3d-9277-3919d685b233", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8ac61968-7b17-474a-a934-359f5e7608bf", "text": "Hány éle van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('11e4ac2b-cbf8-4e0d-9198-b0b7286664cf', '21feff02-016d-46e2-bb9d-c27495133b1b', '113. óra: Projektóra III.', 'Az elkészített projektek és makettek bemutatása, csoportértékelés.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "6ba6f926-c91e-422d-91c7-dddb9ae2ad87", "text": "Mi a projekt bemutatásának legfőbb értéke?", "type": "multiple-choice", "options": [{"id": "96e00d81-4425-4f4c-aade-f01882108f62", "text": "Az elvégzett munka, a mérések, számítások és az elkészült makett ismertetése", "isCorrect": true}, {"id": "30cdf133-2ea2-4ee7-a6bc-b56ddf216c62", "text": "Gyors befejezés elnémulva", "isCorrect": false}, {"id": "b881725d-9d9c-41a6-95ab-2c910dab913b", "text": "Más csoportok munkájának elrejtése", "isCorrect": false}, {"id": "91ace38f-6bc5-43db-b326-a2613a4560a0", "text": "Csak a színek felsorolása", "isCorrect": false}], "timeLimit": 15}, {"id": "fc70c890-e02a-4620-a494-56acbebc81b7", "text": "A prezentációs készség és a szaknyelv használata fontos részét képezi az értékelésnek.", "type": "true-false", "options": [{"id": "9cf8f95e-8c73-4e31-9f99-c989cac16d91", "text": "Igaz", "isCorrect": true}, {"id": "3eff7899-36f8-4e23-92a8-67bb452cf5ab", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "65e615ee-06be-4938-b539-175fba9c36fc", "text": "Az önértékelés és a társak építő kritikája segít a fejlődésben.", "type": "true-false", "options": [{"id": "beadbc08-ca6d-4f8a-b597-62bd5996757d", "text": "Igaz", "isCorrect": true}, {"id": "8617007f-de56-428d-a987-78bbd5add52c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8da0bfe0-61be-4016-acea-7db4cb073017", "text": "Mennyi a 10 cm x 10 cm x 10 cm-es kockamakett térfogata literekben? (1000 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "a21516b1-efb5-49c8-b83b-97fd3200048d", "text": "A projektmunka során a csoport minden tagjának részfeladatot kell vállalnia.", "type": "true-false", "options": [{"id": "e6874bbf-51a7-4192-ba2c-90dbc65afe2d", "text": "Igaz", "isCorrect": true}, {"id": "da8ad470-d86f-4c92-8644-ea4495adc651", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "72c53a10-aca0-4b3a-957c-c904950648b5", "text": "A térszemlélet fejlesztése elengedhetetlen a 3D-s tervezéshez.", "type": "true-false", "options": [{"id": "73bae701-a9b9-425f-8e90-69d93bbbd083", "text": "Igaz", "isCorrect": true}, {"id": "ac12130c-d620-4348-b3f3-52dc6e071ca4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "085462bc-fb62-4067-ad5f-a794603bfd9c", "text": "Mennyi 1 m³ dm³-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('cf738687-8702-4bab-bc73-dc36cef351c5', '21feff02-016d-46e2-bb9d-c27495133b1b', '114. óra: Összefoglalás', 'A Kerület, terület, felszín és térfogat fejezet összefoglalása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "88e68598-ea8c-4a09-b655-9f9361db7a2e", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "4f150347-6358-495e-be8a-a97998a33c57", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "cc86d010-e3c6-49b8-97a8-83a2e3744b76", "text": "Mennyi a 3 cm élű kocka felszíne? (6 * 9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "08bdbaaf-93ee-476d-8103-d6e478734adc", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "8aa97e4c-4281-4240-be6c-2348d168c6bc", "text": "1 liter víz térfogata 1 dm³.", "type": "true-false", "options": [{"id": "d89c1f88-2189-4137-b377-ce403ab75aa8", "text": "Igaz", "isCorrect": true}, {"id": "536391b7-ee0f-4fbb-a005-69d97ca53a39", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f27e6b92-30bc-4e41-9fae-b0d03832cc76", "text": "Hány cm² 1 m²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10000"}, {"id": "181cada2-a9d5-4105-9340-5b28a4cb4856", "text": "A kerület 1D (hosszúság), a terület 2D, a térfogat 3D mennyiség.", "type": "true-false", "options": [{"id": "69effc97-3f4c-4c53-868a-e60aef87df30", "text": "Igaz", "isCorrect": true}, {"id": "f6978343-ef37-4ff8-a3f7-d797a2082c77", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f1419643-5c1c-4184-adae-01cddbd51b24', '21feff02-016d-46e2-bb9d-c27495133b1b', '115. óra: Gyakorlóóra', 'Gyakorló feladatsor önálló megoldása a mérések témakörben.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "3f85f4ca-2aad-44b3-af33-a4ded3f15d45", "text": "Mennyi a 8 cm és 4 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "32"}, {"id": "bcecb39e-5397-4d2c-9fee-968d7e34022f", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "ef4e78dd-f351-456b-89d5-d8544c8f0d9f", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest felszíne? (2*(6+10+15) = 2*31)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "62"}, {"id": "42f45d87-74c3-4ceb-8c8b-b7ad67ab7cb3", "text": "A 1000 dm³ megegyezik 1 m³-rel.", "type": "true-false", "options": [{"id": "be96b865-dfa8-4e17-8593-dae47da85373", "text": "Igaz", "isCorrect": true}, {"id": "f299ea04-45e7-4096-b180-790f3cb0a39a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d1d43e34-e39f-4617-b4e5-8827b499c23f", "text": "Hány liter üdítő van egy 2500 cm³-es tartályban? (2,5 dm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "d9af94d2-edad-4822-a1b0-4b0ee442f2ee", "text": "A méréseknél az azonos mértékegységre való áttérés a sikeres számolás alapja.", "type": "true-false", "options": [{"id": "d21254c0-b789-4d1e-9973-2233440f3b05", "text": "Igaz", "isCorrect": true}, {"id": "e2cba6af-3abd-41b4-b8b4-2bc870b59efc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8c4e94ca-a24f-4f05-9cbc-c1f05a1c026d", "text": "Mennyi a 6 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b3514e97-9e32-47ff-a588-08ff9f4e81a5', '21feff02-016d-46e2-bb9d-c27495133b1b', '116. óra: Feladatmegoldás', 'Hétköznapi mérésekkel, kerülettel, területtel és térfogattal kapcsolatos feladatok.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "d9135187-eaf5-489c-bdb2-564d0132c6a7", "text": "Egy 10 m x 8 m-es medence 2 m mély. Hány m³ víz fér a medencébe tele állapotban? (10 * 8 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160"}, {"id": "a41dd24e-65e9-4a2f-b4d1-1598f194be23", "text": "Hány liter víz fér a 160 m³-es medencébe? (160 * 1000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160000"}, {"id": "c4ad3a03-291d-4b60-8c91-5c0e9dab5dca", "text": "Hány m² csempe kell a medence padlójának leburkolásához? (10 * 8)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "80"}, {"id": "8c4fa1db-2d34-4045-8e34-a8c18d47bc4d", "text": "A medence térfogata megadja a maximális vízkapacitást.", "type": "true-false", "options": [{"id": "e2aa6f68-35e0-4f75-afcb-7e2be544929a", "text": "Igaz", "isCorrect": true}, {"id": "a20eee88-f7e4-4bfe-bf5b-d5186dcd8955", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0980d923-8c9a-4b15-a3f0-7880e51cb07f", "text": "Mennyi a 4 m élű kocka alakú szoba térfogata? (m³-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "9355ca76-eed0-45ee-a970-aae8652cd6a6", "text": "Mennyi a 4 m élű kocka alakú szoba felszíne? (m²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "d9fe7b16-af17-48a8-8ec0-9a028ad95d01", "text": "A gyakorlati feladatok megoldása felkészít a mindennapi életmérésekre.", "type": "true-false", "options": [{"id": "aabf4ced-e36f-45e1-ae06-06af9108e32d", "text": "Igaz", "isCorrect": true}, {"id": "1bffcfa2-3a8b-4283-bb17-adfd03a1c1e6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9f020578-7f43-4fb4-b8a3-c0c9e201c421', '21feff02-016d-46e2-bb9d-c27495133b1b', '118. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat megbeszélése és a mérések összefoglalása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "4bd4f2c4-5823-47c9-89a2-7bd4a02e5889", "text": "Mi volt a leggyakoribb hiba a felszín- és térfogatszámítás során?", "type": "multiple-choice", "options": [{"id": "1ab2890e-1297-4bea-8a74-b56969fb92c2", "text": "A képletek és mértékegységek (cm² vs cm³) összetévesztése", "isCorrect": true}, {"id": "b5a00a46-9a8c-442e-ab1f-41c878a959aa", "text": "A ceruza radírozása", "isCorrect": false}, {"id": "c864de38-f2b5-43cc-bd0e-e4a01dddd638", "text": "A számláló írása", "isCorrect": false}, {"id": "24074d34-8b85-4c20-a7ff-d5a8baa5a266", "text": "Az összeadás hiánya", "isCorrect": false}], "timeLimit": 15}, {"id": "75127246-6be9-4989-ade6-da56c516bcc1", "text": "A térfogat a test által elfoglalt térrész nagyságát jelenti.", "type": "true-false", "options": [{"id": "a67ce02c-5416-4260-b297-484b07de2958", "text": "Igaz", "isCorrect": true}, {"id": "0f125ebd-293c-48ca-91d8-2e5138f90bad", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ce194b97-1596-4d97-a416-e4151310840f", "text": "Mennyi a 2 cm élű kocka térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "4dda0bdc-f9dc-4f5f-88c8-8a9c657915fc", "text": "Mennyi a 2 cm élű kocka felszíne?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "b4bdcf7f-d200-4077-98b9-58ddc88de6dc", "text": "A mértékegységek helyes megadása a válasz kötelező eleme.", "type": "true-false", "options": [{"id": "6982b91e-097b-4f4a-a5d3-47f02596fed2", "text": "Igaz", "isCorrect": true}, {"id": "44c651a0-71ab-45b1-8950-1dea65f9ab20", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d4049c0a-7cfc-4edf-9df4-0c6467a20e44", "text": "Mennyi a 4 cm és 3 cm befogójú derékszögű háromszög területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "bada7053-be11-4974-aae4-d28cb5e99b9e", "text": "A hibajavítás segít a pontosabb tudás megszilárdításában.", "type": "true-false", "options": [{"id": "9258d9ee-188d-4f87-9c50-ec65e5950890", "text": "Igaz", "isCorrect": true}, {"id": "54c1f0ef-a661-41d3-9b69-4e9901a55902", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('cd0ea3f6-7cb7-44ae-9611-2d07b562bc66', '21feff02-016d-46e2-bb9d-c27495133b1b', '120. óra: Grafikonok, diagramok, összefüggések', 'Oszlopdiagram, vonaldiagram, pontdiagram és táblázat olvasása.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "c545d294-3724-41d4-b53d-98cff8aa56b4", "text": "Mire alkalmas leginkább a vonaldiagram (grafikon)?", "type": "multiple-choice", "options": [{"id": "89f012b8-b4a1-454f-9bda-cc42897ebc5f", "text": "Folytonos adatok (pl. hőmérséklet) időbeli változásának szemléltetésére", "isCorrect": true}, {"id": "0532c1e5-a6df-47b8-886b-ff13c5da10e9", "text": "Egyetlen szám felírására", "isCorrect": false}, {"id": "bdd3c044-51d5-49e2-a415-05a495f7d536", "text": "Betűk csoportosítására", "isCorrect": false}, {"id": "1ede2d4d-616d-45d9-94a5-18c532db55d8", "text": "Körök osztására", "isCorrect": false}], "timeLimit": 15}, {"id": "e4e2f887-dc7a-4780-bc66-d44d9958630d", "text": "Mire alkalmas az oszlopdiagram?", "type": "multiple-choice", "options": [{"id": "79c0a452-a469-43ef-9c7d-654e3937523f", "text": "Különböző kategóriák mennyiségének gyors összehasonlítására oszlopok magasságával", "isCorrect": true}, {"id": "e449bc6d-27ba-4854-88a7-652a467e12df", "text": "Számok összeadására", "isCorrect": false}, {"id": "a75f1677-4569-424e-90db-930708c7fc21", "text": "Csak 2 adat ábrázolására", "isCorrect": false}, {"id": "ce7c7913-3748-43bd-819f-b878304a18ac", "text": "Videónézésre", "isCorrect": false}], "timeLimit": 15}, {"id": "0bd96679-6a4f-43de-a341-e518cfffc362", "text": "Ha a diagramon az 1 cm-es oszlop 5 tanulót jelent, hány tanulót jelent a 4 cm-es oszlop?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "6b9a39d9-5fbd-42bc-b923-c3e1e79979b0", "text": "A diagramok tengelyein jelölni kell a skálát és a mértékegységet.", "type": "true-false", "options": [{"id": "349b54f7-7fc0-452c-938d-941e56a8e4ca", "text": "Igaz", "isCorrect": true}, {"id": "40d5a45d-48dd-46e6-8620-81a346592f8e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d40001d9-a237-4675-9dcc-4176aef15c0e", "text": "A táblázat soraiból és oszlopaiból pontos értékek olvashatók le.", "type": "true-false", "options": [{"id": "950ffe48-c99d-4306-9807-e15797135f54", "text": "Igaz", "isCorrect": true}, {"id": "6680c8c5-5592-4714-b767-13403fbd90f9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "afc2d838-0f0f-46a2-bf70-9034d39180e3", "text": "A hibásan skálázott grafikon félrevezetheti az olvasót.", "type": "true-false", "options": [{"id": "b5ba7841-76b6-415a-bf37-5ce051277336", "text": "Igaz", "isCorrect": true}, {"id": "ace22d53-3619-4137-a24b-7824b2ef2832", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8cd3406c-0902-4fc1-9571-bf440a32a99b", "text": "Melyik a legmagasabb hőmérséklet, ha a heti mérések: 12°C, 15°C, 18°C, 14°C, 16°C?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d5c1b59b-5c68-4796-8b5b-9098c5540b56', '21feff02-016d-46e2-bb9d-c27495133b1b', '121. óra: Kördiagram', 'Kördiagram értelmezése, körcikkek szöge, százalékos megoszlás.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "ac83a05d-1b48-4c6c-9088-c667b53e2345", "text": "Mire szolgál a kördiagram?", "type": "multiple-choice", "options": [{"id": "2124ea7f-6c89-40fb-a69f-1dd990468f32", "text": "Az egyes részek teljes egészhez (100%) viszonyított arányának szemléltetésére", "isCorrect": true}, {"id": "e4799ab9-c8c4-4919-9919-9cb6dda86ad9", "text": "Vonalak összekötésére", "isCorrect": false}, {"id": "220dab5d-e750-4294-ae82-b12a56d2b038", "text": "Pontok rajzolására", "isCorrect": false}, {"id": "36c48f53-44d8-48f3-aca0-a50d7aacaad9", "text": "Időbeli növekedés ábrázolására", "isCorrect": false}], "timeLimit": 15}, {"id": "a76f4ddd-4ebf-461d-a052-88085c42b6a2", "text": "Hány fokos a kördiagram teljes köre (100%)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "15fe9e0b-0f55-4888-9d7f-fe2a2089c993", "text": "Hány fokos körcikk tartozik az 50%-os (fél) részhez? (360 / 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "079a7fec-0688-4889-9c35-6e3a0ffb08d0", "text": "Hány fokos körcikk tartozik a 25%-os (negyed) részhez? (360 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "34bb7f40-f63a-4d63-9d21-fcaa6b807ebb", "text": "Hány fokos körcikk tartozik a 10%-os részhez? (360 / 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "445708d3-17df-43f9-a854-c61f33a81f75", "text": "A kördiagramon a körcikkek középponti szögei egyenesen arányosak a képviselt százalékkal.", "type": "true-false", "options": [{"id": "e5555f7d-bebb-4862-8378-4c11ae62ef76", "text": "Igaz", "isCorrect": true}, {"id": "811f2482-1bda-41a1-a49b-9865b89bbf06", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fcb5ca25-21a2-4fea-a69e-0a637e987fab", "text": "A körcikkek szögeinek összege mindig 360°.", "type": "true-false", "options": [{"id": "859a4294-9493-449f-9a4a-6336e76a5aca", "text": "Igaz", "isCorrect": true}, {"id": "ca67957f-d194-4d92-bb3f-2300620f893a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('54412130-50c0-4980-9c20-ef91291242f7', '21feff02-016d-46e2-bb9d-c27495133b1b', '122. óra: Adatok ábrázolása, átlag', 'Számtani közép (átlag) kiszámítása és ábrázolás digitális eszközzel.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "59a6fc8d-564f-4898-9b11-d902d7b6ece7", "text": "Hogyan számítjuk ki több szám számtani középértékét (átlagát)?", "type": "multiple-choice", "options": [{"id": "376daeb8-ee1b-415a-af77-ec1745eccec5", "text": "Összeadjuk az adatokat, majd az összeget elosztjuk az adatok darabszámával", "isCorrect": true}, {"id": "34300b08-8b50-45bc-aaa9-38f811f4271c", "text": "Megszorozzuk az adatokat", "isCorrect": false}, {"id": "a715e5a7-e586-4a99-8f5f-7363851e81fc", "text": "Kivonjuk a legkisebbet a legnagyobból", "isCorrect": false}, {"id": "de97ba43-8f1c-4ccb-ad74-4102cccbcca2", "text": "Kiválasztjuk a leggyakoribb számot", "isCorrect": false}], "timeLimit": 15}, {"id": "d93b029f-bbed-4fc1-8ced-82f2cebc9677", "text": "Mennyi a 4, 6, 8, 10 számok átlaga? (28 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "b6f931dd-f759-4f7a-86f0-ed0920463bc7", "text": "Mennyi a 10, 20, 30, 40, 50 számok átlaga? (150 / 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "a5831db1-7af5-45b2-933b-e02dadedcc21", "text": "Egy diák osztályzatai: 5, 4, 5, 5, 3. Mennyi a tanulmányi átlaga? (22 / 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.4"}, {"id": "2e71338d-a3cd-46cd-8b76-0cc35f39c3c9", "text": "Az átlag értéke mindig a legkisebb és a legnagyobb adat közé esik.", "type": "true-false", "options": [{"id": "e820e14d-a696-4710-a5fb-af925aff9436", "text": "Igaz", "isCorrect": true}, {"id": "9d7a1ed9-8923-4d52-b273-5e613d806bdc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d782214a-88f8-4484-8026-ba8cc158a9de", "text": "Digitális táblázatkezelőben (pl. Excel) az ÁTLAG (AVERAGE) függvény azonnal kiszámolja az átlagot.", "type": "true-false", "options": [{"id": "bf4f7530-572c-4e92-bc46-b6ca6d05e1db", "text": "Igaz", "isCorrect": true}, {"id": "60cd0b80-e2f6-4dda-80f7-40e67924365f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bf5a9aad-e989-4bc4-a42c-eb78db892f97", "text": "Mennyi a 15 és 25 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('18c136bd-b0c2-47ad-aa1f-c4fccaf44d3c', '21feff02-016d-46e2-bb9d-c27495133b1b', '123. óra: Dobáljunk kockákat!', 'Kísérletezés dobókockával, gyakoriság, relatív gyakoriság és valószínűség.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "6d457ca2-2f4b-4475-879e-0e8d30b71e2e", "text": "Egy szabályos 6 oldalú dobókockával mekkora az esélye a 6-os dobásnak?", "type": "multiple-choice", "options": [{"id": "8e1feac2-583e-411b-97cf-a237cc608be0", "text": "1 a 6-ból (1/6)", "isCorrect": true}, {"id": "dab6b3f3-7ea3-43df-a79c-7e400d95c4cd", "text": "1 a 2-ből", "isCorrect": false}, {"id": "9c6d3d05-5324-472b-9b2d-f3cafb824c66", "text": "100%", "isCorrect": false}, {"id": "3d6d37e1-b2e5-4042-8e32-ac06778d755a", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "4a4e0b97-8f84-4de0-8af7-b3cf72efbdec", "text": "Mennyi a páros szám (2, 4, 6) dobásának valószínűsége dobókockával?", "type": "multiple-choice", "options": [{"id": "bd281e9e-2d15-4cce-af38-53261d037bb0", "text": "3 a 6-ból (3/6 = 1/2 azaz 50%)", "isCorrect": true}, {"id": "4ed903a8-2519-434f-8d0a-4f365ad63d38", "text": "1/6", "isCorrect": false}, {"id": "2eef68a6-e53a-41db-8aa7-5fdce163de79", "text": "2/6", "isCorrect": false}, {"id": "8100a0af-38fd-4ca0-bf0e-008b04f410eb", "text": "100%", "isCorrect": false}], "timeLimit": 15}, {"id": "c0a3ee92-cc5b-4c32-bcfa-703011bdb742", "text": "Sok dobási kísérlet végrehajtásakor a relatív gyakoriság megközelíti az elméleti valószínűséget.", "type": "true-false", "options": [{"id": "1d272140-6310-4905-a78d-f4e555eb419b", "text": "Igaz", "isCorrect": true}, {"id": "8cde9d71-29df-40b6-808b-879b087ab241", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4d3c0d40-eddf-40e3-9b28-e1889ccf6756", "text": "Milyen esemény egy kockával 7-est dobni?", "type": "multiple-choice", "options": [{"id": "10aec65d-9b18-46b1-91b8-3b0aca2d813b", "text": "Lehetetlen esemény (0%)", "isCorrect": true}, {"id": "a6f3624f-a4e4-45d0-9fda-7930b1b7e1c0", "text": "Biztos esemény", "isCorrect": false}, {"id": "07847bc0-fde3-45a6-a8dc-88f383178e08", "text": "Lehetséges", "isCorrect": false}, {"id": "33f2c31d-8ac3-4db2-ab85-377ece29c3be", "text": "Véletlen", "isCorrect": false}], "timeLimit": 15}, {"id": "6e890ed0-8eb4-4ee2-bfbf-f5b8f155f2a8", "text": "Milyen esemény egy kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "ce12ff63-5366-4443-a0af-dc00cbcc88c5", "text": "Biztos esemény (100%)", "isCorrect": true}, {"id": "f62ed211-b53e-456e-8e3c-83baf2661999", "text": "Lehetetlen", "isCorrect": false}, {"id": "efed3443-ee13-4dd2-b37a-c50d5a24f97d", "text": "Kétes", "isCorrect": false}, {"id": "860d8444-4fdf-4bbc-afde-c0d8c9cec1b5", "text": "Ritka", "isCorrect": false}], "timeLimit": 15}, {"id": "1d717e91-787d-494b-a0ab-2d6cf1b9849e", "text": "Hányféle kimenetele lehet két kocka dobásakor a kapott összegeknek? (2-től 12-ig: 11-féle)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "abab5b30-864b-4221-abee-141d9a704384", "text": "Két kockával a leggyakoribb dobási összeg a 7.", "type": "true-false", "options": [{"id": "b7c1fc58-b738-4980-9176-d38e85f583ad", "text": "Igaz", "isCorrect": true}, {"id": "bbed5436-5887-4b97-b33e-871d11251a1b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('eb6de54f-33d8-4ab6-9109-f0325d65c68c', '21feff02-016d-46e2-bb9d-c27495133b1b', '124. óra: Dobáljunk pénzérmét!', 'Kísérletezés érmével, fej vagy írás, tapasztalati valószínűség.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "76205f7b-6166-48ee-8432-77462f2b1997", "text": "Egy szabályos pénzérme feldobásakor mekkora a fej dobás valószínűsége?", "type": "multiple-choice", "options": [{"id": "6917a328-3f4b-4299-b575-4383e27d0117", "text": "1 a 2-ből (1/2 azaz 50%)", "isCorrect": true}, {"id": "1e3fe8da-a3de-4e03-a46f-bef7cc47bcf2", "text": "1/4", "isCorrect": false}, {"id": "1d55baa3-a8c1-4add-82f9-984e5ba107e7", "text": "100%", "isCorrect": false}, {"id": "78bb3d14-6bac-4331-a334-50acf15a1480", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "39d1df82-9316-4aae-bdd1-896bae6c0ffb", "text": "Ha 100-szor dobunk fel egy érmét, a fej dobások száma kb. 50 körül várható.", "type": "true-false", "options": [{"id": "295d8b5a-a672-45ca-97c8-f8405ab48846", "text": "Igaz", "isCorrect": true}, {"id": "7e218775-f6a3-4371-8fe3-44a100ad314a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "46ccae66-ef77-433e-8f0b-07a9cd10e44b", "text": "Hány kimenetele lehet 2 érme egyidejű feldobásának? (FF, FI, IF, II)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "1df23f1c-7261-46d7-92d5-47f6d752c2cb", "text": "Mekkora a valószínűsége annak, hogy 2 érmével mindkettő fej lesz? (1 a 4-ből = 25%)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "8ef2ac71-7ebf-4a7a-a33b-07599a1ae440", "text": "A véletlen kísérletek eredményét az egyes próbálkozásoknál nem lehet pontosan kiszámítani, de nagy számnál szabályszerűség mutatkozik.", "type": "true-false", "options": [{"id": "ad4db91b-b281-44ba-9121-749c30eac01a", "text": "Igaz", "isCorrect": true}, {"id": "7eca0154-7322-4deb-84e4-ca7bd6963e1e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5b34a096-7ef3-46ce-9650-052c8e211fcb", "text": "A biztos esemény valószínűsége 100% (vagy 1).", "type": "true-false", "options": [{"id": "cd3cbf55-d99d-4b1b-89a8-623e8f1a6fe4", "text": "Igaz", "isCorrect": true}, {"id": "ff43e3c6-f295-4b8b-86ca-0452acebda43", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4b993d86-29ca-4a15-b154-3c8c56fe5075", "text": "A lehetetlen esemény valószínűsége 0% (vagy 0).", "type": "true-false", "options": [{"id": "ff5e77f5-52f3-4d0a-b2c9-dc476e5eb6fa", "text": "Igaz", "isCorrect": true}, {"id": "9d2fae13-12db-4881-8ddb-419285b61a73", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b2213b4b-4887-4767-92f7-ab286250b358', '21feff02-016d-46e2-bb9d-c27495133b1b', '125. óra: Összefoglalás', 'Statisztikai és valószínűségi ismeretek összefoglalása.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "a129a2da-720a-43d0-80f7-5276e869af0b", "text": "Mennyi a 6, 8, 10, 12 számok átlaga? (36 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "8a02e869-9ff0-4c6c-9edf-40f82f29f09c", "text": "Hány fokos körcikk felel meg a kördiagramon a 50%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "9c4f440c-cf2c-4193-905e-6b87624c7cbd", "text": "Hány fokos körcikk felel meg a kördiagramon a 25%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "acb6e999-ed2a-4b8e-9544-297814f270d3", "text": "Egy kockával 6-ost dobni 1/6 valószínűségű esemény.", "type": "true-false", "options": [{"id": "92f7eee8-8e12-4e86-83d4-5c1110476c69", "text": "Igaz", "isCorrect": true}, {"id": "bb4e1778-e69e-4b16-8eb3-0db12af19470", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cc9ef35b-0f88-4432-83cd-9a563bc89ef2", "text": "Az adatok átlagához az összes adat összegét elosztjuk a darabszámmal.", "type": "true-false", "options": [{"id": "5fc469eb-8132-4bba-b57d-5358243a2ee3", "text": "Igaz", "isCorrect": true}, {"id": "71a8cf7a-f788-4476-b66d-16dd9f5273ca", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7f9a223b-f68a-43b0-8a9b-4bb9a935d3ad", "text": "Melyik grafikon alkalmas időbeli változás ábrázolására?", "type": "multiple-choice", "options": [{"id": "d709007a-acd0-426c-9080-439eed600b3c", "text": "Vonaldiagram", "isCorrect": true}, {"id": "fb18db8b-17ce-44cf-9c78-07b9c7902378", "text": "Kördiagram", "isCorrect": false}, {"id": "35f0dc9b-2399-4a1c-a563-c693ac419d22", "text": "Pontdiagram", "isCorrect": false}, {"id": "3df49372-4b03-4a95-ae67-9b12332ad4f7", "text": "Képrejtvény", "isCorrect": false}], "timeLimit": 15}, {"id": "749e7e21-f773-4232-ae50-97c101f548f7", "text": "Mennyi a 20 és 40 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('6f10a040-f960-479a-bcbb-b97a0d54a899', '21feff02-016d-46e2-bb9d-c27495133b1b', '126. óra: Számonkérés', 'Számonkérés projektmunka és teszt formájában a Statisztikából (10 kérdés).', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "68b1e63a-3d61-483b-a044-7687d2e43e62", "text": "1. Mennyi a 10, 20, 30 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "09a7a50b-2c8b-4918-84a6-c851782b7309", "text": "2. Mennyi a 2, 4, 6, 8, 10 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "3d4e9ad9-cb1c-44b6-a169-fdf5d9b398bd", "text": "3. Hány fokos a teljes kör a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "b470987a-dcbc-423c-a4fe-dcfc1031ec39", "text": "4. Hány fokos körcikk jelöli a 10%-ot a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "00ed34b4-be47-4e9c-a681-3aa299459e4f", "text": "5. Mekkora a fej dobás valószínűsége százalékban egy szabályos érmével?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "23c51f33-7a86-4bbb-acbe-29fd2b4f903a", "text": "6. Milyen esemény egy 6 oldalú kockával 8-ast dobni?", "type": "multiple-choice", "options": [{"id": "eb77a2a9-0d5f-4fdc-b117-8d5c86ed91ff", "text": "Lehetetlen esemény", "isCorrect": true}, {"id": "f5424b5d-b1b4-4c35-81c0-4a78c1417f43", "text": "Biztos esemény", "isCorrect": false}, {"id": "c8ed192e-3c7f-42c7-b480-be36cd9313b2", "text": "Lehetséges", "isCorrect": false}, {"id": "c21a3c34-d27b-429b-ba71-514497c49e25", "text": "Döntetlen", "isCorrect": false}], "timeLimit": 15}, {"id": "5752835f-0825-433a-b204-f617ec18c181", "text": "7. Milyen esemény egy 6 oldalú kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "b80d3caa-0491-4384-9ba6-035d05ef0d58", "text": "Biztos esemény", "isCorrect": true}, {"id": "019f173c-dcad-4921-8fb5-697132b5557e", "text": "Lehetetlen esemény", "isCorrect": false}, {"id": "65386f5b-8aab-4c14-88c6-ec6d744d9192", "text": "Ritka", "isCorrect": false}, {"id": "60117e76-965c-4cbf-ba60-496d65665c28", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "645a2d55-7a78-4453-a2c6-f26f18011844", "text": "8. Az adatok átlaga mindig a legkisebb és legnagyobb adat közé esik.", "type": "true-false", "options": [{"id": "bbd89e5b-ec1b-4bcd-9a15-660975f1ad53", "text": "Igaz", "isCorrect": true}, {"id": "475737ef-f3e6-4f1c-8300-76d4952a4bac", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "52dcf70c-90aa-4ff1-9c76-43390c8ac445", "text": "9. Hány kimenetele lehet 2 érme feldobásának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "53082f34-bfdf-41d8-a976-e825570da93a", "text": "10. A vonaldiagram az adatok időbeli alakulását mutatja meg jól.", "type": "true-false", "options": [{"id": "fe721341-8072-4da9-941b-87876263bb03", "text": "Igaz", "isCorrect": true}, {"id": "e2801bcc-7c16-48ee-8966-a52a0040f7c0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b32d12f8-b630-454a-9777-d2804022e542', '21feff02-016d-46e2-bb9d-c27495133b1b', '127. óra: A számonkérés értékelése', 'A statisztikai feladatok és projektmunkák megbeszélése, értékelése.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "59cc3ad2-8fac-4290-ac3f-d73a69034e1e", "text": "Mi volt a projektmunka és a számonkérés legfőbb tanulsága?", "type": "multiple-choice", "options": [{"id": "a88cf190-6b20-43b1-a00f-5137a0b79143", "text": "Az adatok pontos rögzítése és a helyes skálázás elengedhetetlen a helyes diagramokhoz", "isCorrect": true}, {"id": "e52d14f1-3ba0-4e33-a891-5ec008753242", "text": "A rajzolás nem fontos", "isCorrect": false}, {"id": "cd02c9c8-0fb4-4945-86d7-5b7ed43d1b21", "text": "A számolást el kell hagyni", "isCorrect": false}, {"id": "de7e4748-885c-4800-9af6-b830ae53f5ea", "text": "Mindegy a skála", "isCorrect": false}], "timeLimit": 15}, {"id": "bcb2f68c-d580-40e4-aee4-db58b69a6f28", "text": "Az átlag kiszámításánál a darabszámmal való osztást nem szabad elfelejteni.", "type": "true-false", "options": [{"id": "e6c76840-5ee6-4cf2-a5f9-3c3515167b2e", "text": "Igaz", "isCorrect": true}, {"id": "80add9f3-8b5b-4bb1-aee5-06331b9c0ee3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d4125fb2-53c7-4508-81ed-295758d91d81", "text": "Mennyi a 12 és 18 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "06d01b72-b994-42ac-8f1c-bd7d6fa385a5", "text": "A kördiagram körcikkei összefüggenek a százalékos megoszlással.", "type": "true-false", "options": [{"id": "b7d38fb4-217b-45a5-b53b-5ed050fe7ccc", "text": "Igaz", "isCorrect": true}, {"id": "073366c5-b80f-4dee-b2b3-61629b53ea67", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "89e895ed-51bd-416b-bbe4-20233b6610a8", "text": "A kísérletek során nyert adatok segítenek megérteni a valószínűségi elveket.", "type": "true-false", "options": [{"id": "308d4980-de2a-448a-a147-15888b759533", "text": "Igaz", "isCorrect": true}, {"id": "c40492ff-0000-4cbe-a99f-7142c43829d9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9ff7635f-bc4d-4458-83a1-b0e85c61bc90", "text": "Mennyi a 5, 10, 15 átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "f8e2e27d-8b41-494e-a129-b483e498c27c", "text": "A csoporteredmények bemutatása fejlesztette a kommunikációs készséget.", "type": "true-false", "options": [{"id": "cf0dd20a-043e-4e7e-b5b6-495e84b8cc79", "text": "Igaz", "isCorrect": true}, {"id": "d6673c38-c24b-40c8-b231-2ad22be9da85", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('866405b4-3032-49b9-8723-5a4ae5b4ba5b', '21feff02-016d-46e2-bb9d-c27495133b1b', '130. óra: Az egész számokról tanultak összefoglalása, vegyes feladatok', 'Év végi ismétlés: műveletek egész számokkal, előjelek, abszolút érték, ellentett.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "679b328a-fa43-4f9e-bf12-7d2b4ac88b8e", "text": "Mennyi (-15) + (+25)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "d774e05f-5b0d-4b06-8fec-fb49cd563095", "text": "Mennyi (-8) * (-7)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "56"}, {"id": "6b5f7b40-fd3f-40f6-92df-35aa7005ef65", "text": "Mennyi (-63) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-7"}, {"id": "3bac1373-ef82-4105-87de-e8f074a00da4", "text": "Két negatív szám szorzata mindig pozitív.", "type": "true-false", "options": [{"id": "070aab71-c333-4e12-afd9-70d658380006", "text": "Igaz", "isCorrect": true}, {"id": "6deda400-c30f-4d3f-86a6-cfe07d94d627", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ae0a1cfb-f163-4750-b5cb-45def15e57bd", "text": "Mennyi |-40|?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "31ac8048-ea8e-4add-8430-8c010c10d94c", "text": "Melyik szám nagyobb: -12 vagy -4?", "type": "multiple-choice", "options": [{"id": "7db5e482-b2af-4d45-b87a-bf1b542bd68d", "text": "-4", "isCorrect": true}, {"id": "e9727e60-e619-4039-ad5a-76211f408946", "text": "-12", "isCorrect": false}, {"id": "6084e510-40f6-4509-9f6c-bd5fc2f00165", "text": "Egyenlők", "isCorrect": false}, {"id": "a052eca6-096b-4da2-81c6-3ce5e61b283e", "text": "Nem eldönthető", "isCorrect": false}], "timeLimit": 15}, {"id": "080a7590-f11e-46a9-9d1e-2a18d17728b5", "text": "Mennyi (-5) * (-2) * (-3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-30"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9918b5ca-ec1b-4d73-8aef-d6aa87fc5f56', '21feff02-016d-46e2-bb9d-c27495133b1b', '131. óra: Az oszthatóságról tanultak összefoglalása', 'Év végi ismétlés: oszthatósági szabályok, prímek, lkkt és lnko.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "55a6ccbb-9068-4eb4-9836-f4380a1ef5e0", "text": "Osztható-e a 435 5-tel és 3-mal is (azaz 15-tel)?", "type": "true-false", "options": [{"id": "94eba5ba-dbb1-49e8-b453-966616a9a080", "text": "Igaz (5-re végződik és 4+3+5=12)", "isCorrect": true}, {"id": "91256a17-3310-48de-8254-f9fada5273f0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e1309f93-d8f4-4718-96a7-d0218f34b96f", "text": "Osztható-e a 612 4-gyel?", "type": "true-false", "options": [{"id": "a53ec1ff-be20-49ed-9c76-9fde35401e13", "text": "Igaz (12 osztható 4-gyel)", "isCorrect": true}, {"id": "5d4fb071-3280-4744-b3e3-293822261058", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a2554127-88dc-4712-9493-90df24c47b02", "text": "Mennyi lkkt(6, 8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "ac1b665a-55f8-48ea-85ef-2902d3fed774", "text": "Mennyi lnko(12, 18)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "97963c25-0a2b-448e-bdfe-2a5a02e664f3", "text": "Melyik a legkisebbkétjegyű prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "6e89857a-f0d0-44a8-913b-15647cde7f92", "text": "A 2 az egyetlen páros prímszám.", "type": "true-false", "options": [{"id": "7189da9f-e028-4179-bae9-d53e6c83af68", "text": "Igaz", "isCorrect": true}, {"id": "d0b645bc-09f9-4c40-84cd-6c046c4f0ca1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4db405cf-b709-4574-93f1-653b59ea95ac", "text": "Melyik szám osztható 9-cel?", "type": "multiple-choice", "options": [{"id": "c1b99d3f-9ef4-4164-96c1-52940deeaf5c", "text": "819 (8+1+9=18)", "isCorrect": true}, {"id": "4614f552-6848-4c78-a351-f8f8b4b2fa05", "text": "815", "isCorrect": false}, {"id": "8551f685-6f65-47ac-a064-a520fbc2f07d", "text": "812", "isCorrect": false}, {"id": "7d21d89a-d079-4a19-9ac6-41b738253cdd", "text": "811", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('835c873c-7439-4ba2-a402-e4b4bdb91737', '21feff02-016d-46e2-bb9d-c27495133b1b', '132. óra: A törtekről tanultak összefoglalása, vegyes feladatok', 'Év végi ismétlés: közönséges és tizedes törtek műveletei.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "a05314eb-2323-4e9f-ab91-2533755f64d9", "text": "Mennyi 3/4 + 1/2? (3/4 + 2/4)", "type": "multiple-choice", "options": [{"id": "6525d8f2-7308-42c4-a012-c55aa61741e0", "text": "5/4 (1 egész 1/4)", "isCorrect": true}, {"id": "216cbfae-64a8-4753-8450-3abf472d504c", "text": "4/6", "isCorrect": false}, {"id": "bf5bba1f-cd6d-4b77-8435-2acdd39d8573", "text": "4/4", "isCorrect": false}, {"id": "e660cfa5-b5f8-4399-a24b-d3ce1316a7ba", "text": "3/8", "isCorrect": false}], "timeLimit": 15}, {"id": "e52a2357-f97c-48b8-8b0d-6efffdd46649", "text": "Mennyi 2/3 * 3/5?", "type": "multiple-choice", "options": [{"id": "7a2bc016-dd4a-49ec-9235-cf7cbb2a1e03", "text": "2/5", "isCorrect": true}, {"id": "fbd9b11c-981e-4057-a6ae-3317c9dbab24", "text": "6/15", "isCorrect": false}, {"id": "e552e684-3355-4bf8-a10f-4a744a686dd4", "text": "5/8", "isCorrect": false}, {"id": "d05bdf2d-b4d3-48b5-a363-e2ecc1e1153f", "text": "6/8", "isCorrect": false}], "timeLimit": 15}, {"id": "d6db7beb-8c9f-444f-8306-cf7a14ca4e1f", "text": "Mennyi 1/2 : 1/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "24a6da26-db71-4daf-b6ae-14184e074d3d", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "f742a736-94ca-4267-a2a7-3351bbbad276", "text": "Mennyi 4,8 : 0,6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "bea445c6-7636-45e5-a33b-f05b3c0c8031", "text": "A 0,75 megegyezik a 3/4 törttel.", "type": "true-false", "options": [{"id": "64fba506-7757-4ffa-8e82-d0b153bcb90c", "text": "Igaz", "isCorrect": true}, {"id": "39d2176e-8a4e-4811-9cae-4a5d847679b1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "396eabb5-45ee-492f-b829-dd8de47721a8", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9a5bffbb-a6fd-4aff-80de-5eb1cdfe41e8', '21feff02-016d-46e2-bb9d-c27495133b1b', '133. óra: A geometriai ismeretek összefoglalása, vegyes feladatok', 'Év végi ismétlés: szögek, alakzatok, tengelyes tükrözés.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "dbbb7a11-3b19-4f61-be9a-b65f0e661a8e", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "9df804ce-5e20-4eec-ba3a-4b428a4b2de9", "text": "Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "ffae0fd0-f91b-4415-8fbf-917467d0e6f7", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "04ff1883-2c86-4393-ae04-1c49823723a8", "text": "Ha a kör sugara 6 cm, mekkora az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "1f5140a5-c905-463a-b169-bbbced781c8a", "text": "A tengelyes tükrözés távolságtartó transzformáció.", "type": "true-false", "options": [{"id": "0c3eebf2-bb62-4af7-9e65-0844b6a6ed42", "text": "Igaz", "isCorrect": true}, {"id": "768a26fa-6dc8-4e0e-a96d-c44a4e221742", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "122257c8-a4a4-4431-8019-c8b501df5059", "text": "Hány fokos szöget zár be a szakaszfelező merőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "a25ffc75-5997-44e3-90c4-eed17893df4b", "text": "Milyen szög a 90°-os szög?", "type": "multiple-choice", "options": [{"id": "ec07be2b-77fd-4c35-9518-7ee2f49eb232", "text": "Derékszög", "isCorrect": true}, {"id": "a5035b2e-bac0-4238-845d-1bdeeef8e4b3", "text": "Hegyesszög", "isCorrect": false}, {"id": "3f6d2201-a6ce-4371-b71b-62e9c776911e", "text": "Tompaszög", "isCorrect": false}, {"id": "62a9594f-71f8-4242-8edb-75e707421cc0", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());